            static std::string toLowerAsciiCopy(const std::string& input)
            {
                std::string out = input;
                std::transform(out.begin(), out.end(), out.begin(),
                               [](unsigned char c) { return static_cast<char>(std::tolower(c)); });
                return out;
            }

            static std::string toUpperAsciiCopy(const std::string& input)
            {
                return core::IdentifierUtils::toUpper(input);
            }

            static std::string trimAsciiCopy(const std::string& input)
            {
                size_t begin = 0;
                while (begin < input.size() &&
                       std::isspace(static_cast<unsigned char>(input[begin])) != 0)
                {
                    ++begin;
                }

                size_t end = input.size();
                while (end > begin &&
                       std::isspace(static_cast<unsigned char>(input[end - 1])) != 0)
                {
                    --end;
                }

                return input.substr(begin, end - begin);
            }

            static thread_local std::string g_v3_module_dialect_override;

            static bool isPostgreSqlDialectContext(const core::ConnectionContext* conn_ctx)
            {
                const auto is_postgres_tag = [](const std::string& tag) -> bool {
                    const std::string upper = toUpperAsciiCopy(trimAsciiCopy(tag));
                    return upper == "POSTGRESQL" || upper == "POSTGRES" || upper == "PG";
                };

                if (conn_ctx != nullptr && is_postgres_tag(conn_ctx->dialect_tag()))
                {
                    return true;
                }
                return is_postgres_tag(g_v3_module_dialect_override);
            }

            static bool textMentionsMissingSchema(const std::string& message)
            {
                const std::string lower = toLowerAsciiCopy(message);
                if (lower.find("schema") == std::string::npos)
                {
                    return false;
                }
                return lower.find("not found") != std::string::npos ||
                       lower.find("does not exist") != std::string::npos ||
                       lower.find("path not found") != std::string::npos;
            }

            static std::string firstPathComponent(const std::string& name)
            {
                const std::string trimmed = trimAsciiCopy(name);
                if (trimmed.empty())
                {
                    return std::string();
                }
                std::vector<std::string> components;
                size_t cursor = 0;
                while (cursor <= trimmed.size())
                {
                    size_t dot = trimmed.find('.', cursor);
                    std::string token = (dot == std::string::npos)
                        ? trimmed.substr(cursor)
                        : trimmed.substr(cursor, dot - cursor);
                    token = trimAsciiCopy(token);
                    if (!token.empty())
                    {
                        components.push_back(std::move(token));
                    }
                    if (dot == std::string::npos)
                    {
                        break;
                    }
                    cursor = dot + 1;
                }
                if (components.empty())
                {
                    return std::string();
                }

                size_t idx = 0;
                if (components.size() > 1 &&
                    core::IdentifierUtils::namesMatch(
                        components[0], false, "main", false))
                {
                    idx = 1;
                }
                return components[idx];
            }

            static std::string schemaPrefixFromQualifiedName(
                const std::string& qualified_name)
            {
                const std::string trimmed = trimAsciiCopy(qualified_name);
                size_t dot = trimmed.find('.');
                if (dot == std::string::npos || dot == 0)
                {
                    return std::string();
                }
                return firstPathComponent(trimmed.substr(0, dot));
            }

            static std::string firstSchemaQualifierFromSignature(
                const std::string& signature_text)
            {
                const std::string trimmed = trimAsciiCopy(signature_text);
                size_t lparen = trimmed.find('(');
                size_t rparen = trimmed.find_last_of(')');
                if (lparen == std::string::npos ||
                    rparen == std::string::npos ||
                    rparen <= lparen)
                {
                    return std::string();
                }

                std::string inner = trimmed.substr(lparen + 1, rparen - lparen - 1);
                size_t cursor = 0;
                while (cursor < inner.size())
                {
                    size_t comma = inner.find(',', cursor);
                    std::string arg = (comma == std::string::npos)
                        ? inner.substr(cursor)
                        : inner.substr(cursor, comma - cursor);
                    arg = trimAsciiCopy(arg);

                    size_t token_cursor = 0;
                    while (token_cursor < arg.size())
                    {
                        while (token_cursor < arg.size() &&
                               std::isspace(static_cast<unsigned char>(arg[token_cursor])) != 0)
                        {
                            ++token_cursor;
                        }
                        if (token_cursor >= arg.size())
                        {
                            break;
                        }

                        size_t token_end = token_cursor;
                        while (token_end < arg.size() &&
                               std::isspace(static_cast<unsigned char>(arg[token_end])) == 0)
                        {
                            ++token_end;
                        }
                        std::string token =
                            trimAsciiCopy(arg.substr(token_cursor, token_end - token_cursor));
                        if (!token.empty())
                        {
                            std::string schema_name =
                                schemaPrefixFromQualifiedName(token);
                            if (!schema_name.empty())
                            {
                                return schema_name;
                            }
                        }
                        token_cursor = token_end;
                    }

                    if (comma == std::string::npos)
                    {
                        break;
                    }
                    cursor = comma + 1;
                }

                return std::string();
            }

            static std::string lastPathComponent(const std::string& name)
            {
                const std::string trimmed = trimAsciiCopy(name);
                size_t dot = trimmed.find_last_of('.');
                if (dot == std::string::npos)
                {
                    return trimmed;
                }
                return trimAsciiCopy(trimmed.substr(dot + 1));
            }

            static void pushPostgreSqlIfExistsNotice(core::ConnectionContext* conn_ctx,
                                                     bool postgresql_dialect,
                                                     const std::string& object_type,
                                                     const std::string& object_name,
                                                     const std::string& error_hint)
            {
                if (!postgresql_dialect || conn_ctx == nullptr)
                {
                    return;
                }

                const std::string schema_name = firstPathComponent(object_name);
                if (object_type != "schema" &&
                    !schema_name.empty() &&
                    textMentionsMissingSchema(error_hint))
                {
                    conn_ctx->pushNotice("schema \"" + schema_name + "\" does not exist, skipping");
                    return;
                }

                std::string display_name = trimAsciiCopy(object_name);
                if (object_type == "schema")
                {
                    display_name = lastPathComponent(display_name);
                }
                conn_ctx->pushNotice(
                    object_type + " \"" + display_name + "\" does not exist, skipping");
            }

            static bool isTruthySetting(const char* value)
            {
                if (!value || value[0] == '\0')
                {
                    return false;
                }
                const std::string normalized = toUpperAsciiCopy(trimAsciiCopy(value));
                return normalized == "1" ||
                       normalized == "TRUE" ||
                       normalized == "YES" ||
                       normalized == "ON";
            }

            static bool relaxedEmulationPasswordPolicyEnabled()
            {
                return isTruthySetting(
                    std::getenv("SCRATCHBIRD_EMULATION_RELAXED_PASSWORD_POLICY"));
            }

            enum class ArrayUniquenessMode : uint8_t
            {
                WHOLE = 0,
                ELEMENT = 1
            };

            constexpr const char* kIndexParamArrayUniqueness = "sb.array_uniqueness";

            static const char* arrayUniquenessModeToText(ArrayUniquenessMode mode)
            {
                return mode == ArrayUniquenessMode::ELEMENT ? "ELEMENT" : "WHOLE";
            }

            static bool parseArrayUniquenessMode(const std::string& input,
                                                 ArrayUniquenessMode* mode_out)
            {
                if (!mode_out)
                {
                    return false;
                }

                std::string upper = toUpperAsciiCopy(trimAsciiCopy(input));
                if (upper.empty() || upper == "WHOLE" || upper == "WHOLE_ARRAY" ||
                    upper == "ARRAY")
                {
                    *mode_out = ArrayUniquenessMode::WHOLE;
                    return true;
                }
                if (upper == "ELEMENT" || upper == "ELEMENTS" ||
                    upper == "PER_ELEMENT" || upper == "ELEMENT_LEVEL")
                {
                    *mode_out = ArrayUniquenessMode::ELEMENT;
                    return true;
                }
                return false;
            }

            static bool tryGetIndexParamValue(const std::string& params,
                                              const std::string& key,
                                              std::string* value_out)
            {
                if (!value_out)
                {
                    return false;
                }

                const std::string key_upper = toUpperAsciiCopy(trimAsciiCopy(key));
                size_t start = 0;
                while (start <= params.size())
                {
                    size_t end = params.find(';', start);
                    std::string token =
                        (end == std::string::npos) ? params.substr(start)
                                                   : params.substr(start, end - start);
                    token = trimAsciiCopy(token);
                    if (!token.empty())
                    {
                        size_t eq = token.find('=');
                        if (eq != std::string::npos)
                        {
                            std::string token_key = toUpperAsciiCopy(trimAsciiCopy(token.substr(0, eq)));
                            if (token_key == key_upper)
                            {
                                *value_out = trimAsciiCopy(token.substr(eq + 1));
                                return true;
                            }
                        }
                    }

                    if (end == std::string::npos)
                    {
                        break;
                    }
                    start = end + 1;
                }

                return false;
            }

            // SBLR3_FUNC_NOW flag bit: 1 means CURRENT_TIMESTAMP semantics (txn-start anchored).
            constexpr uint16_t kFuncNowCurrentTimestampFlag = 0x0001;
            // SBLR3_FUNC_JSON_EXISTS mode flags.
            constexpr uint16_t kFuncJsonExistsAnyFlag = 0x0001;
            constexpr uint16_t kFuncJsonExistsAllFlag = 0x0002;

            static void initializeLanguageUdrCompileRegistry(scratchbird::udr::LanguageUdrRegistry& registry)
            {
                for (const auto& seed : kLanguageUdrCompileProfiles)
                {
                    scratchbird::udr::LanguageUdrRegistration registration{};
                    registration.module_id = core::generateUuidV7();
                    registration.module_name = "sb_udr_compile_" + toLowerAsciiCopy(seed.profile_id);
                    registration.engine_profile_id = seed.profile_id;
                    registration.engine_profile_version = "1.0";
                    registration.translation_mode = seed.translation_mode;
                    registration.module_semver = "1.0.0";
                    registration.artifact_hash = "artifact_" + toLowerAsciiCopy(seed.profile_id);
                    registration.signature_status =
                        scratchbird::udr::LanguageUdrSignatureStatus::TRUSTED;
                    registration.status = scratchbird::udr::LanguageUdrModuleStatus::ACTIVE;

                    core::ErrorContext ctx;
                    (void)registry.registerModule(
                        registration,
                        {"compile_route", "template_compile"},
                        &ctx);
                }
            }

            static scratchbird::udr::LanguageUdrRegistry& languageUdrCompileRegistry()
            {
                static scratchbird::udr::LanguageUdrRegistry registry;
                static std::once_flag init_once;
                std::call_once(init_once, [&]() { initializeLanguageUdrCompileRegistry(registry); });
                return registry;
            }

