        void Executor::executeShowDomain()
        {
            // Read bytecode parameters
            std::string object_name = readString();

            if (object_name.empty())
            {
                error("Domain name required");
            }

            auto* catalog = db_->catalog_manager();
            auto* domain_mgr = db_->domain_manager();
            if (!catalog || !domain_mgr)
            {
                error("Domain manager not available");
            }

            core::ErrorContext err_ctx;
            core::ID domain_id;
            core::CatalogManager::ObjectType resolved_type;
            auto resolve_status = resolveObjectIdForQualifiedName(
                object_name, core::CatalogManager::ObjectType::DOMAIN,
                domain_id, resolved_type, nullptr, &err_ctx);
            if (resolve_status != core::Status::OK)
            {
                error("Domain '" + object_name + "' not found");
            }
            (void)resolved_type;

            core::DomainInfo domain_info;
            auto status = domain_mgr->getDomain(domain_id, domain_info, &err_ctx);
            if (status != core::Status::OK)
            {
                error("Domain '" + object_name + "' not found");
            }

            if (!current_result_set_)
            {
                current_result_set_ = std::make_unique<ResultSet>();
            }

            current_result_set_->addColumn("Property", core::DataType::VARCHAR);
            current_result_set_->addColumn("Value", core::DataType::VARCHAR);

            auto domain_type_to_string = [](core::DomainType type) {
                switch (type)
                {
                case core::DomainType::BASIC: return "BASIC";
                case core::DomainType::RECORD: return "RECORD";
                case core::DomainType::ENUM: return "ENUM";
                case core::DomainType::SET: return "SET";
                case core::DomainType::VARIANT: return "VARIANT";
                case core::DomainType::RANGE: return "RANGE";
                case core::DomainType::BASE: return "BASE";
                case core::DomainType::SHELL: return "SHELL";
                    default: return "UNKNOWN";
                }
            };

            auto format_domain_type_ref = [&](const core::DomainTypeRef& ref) -> std::string {
                if (!isZeroUuid(ref.domain_id))
                {
                    core::DomainInfo ref_domain;
                    if (domain_mgr->getDomain(ref.domain_id, ref_domain, &err_ctx) == core::Status::OK)
                    {
                        return ref_domain.domain_name;
                    }
                    return "DOMAIN";
                }
                return formatType(ref.type, ref.precision, ref.scale);
            };

            auto constraint_to_string = [](const core::DomainConstraint& constraint) {
                std::string text;
                switch (constraint.type)
                {
                    case core::ConstraintType::CHECK:
                        text = constraint.expression.empty()
                            ? "CHECK Redacted"
                            : "CHECK " + constraint.expression;
                        break;
                    case core::ConstraintType::NOT_NULL:
                        text = "NOT NULL";
                        break;
                    case core::ConstraintType::UNIQUE:
                        text = "UNIQUE";
                        break;
                    case core::ConstraintType::DEFAULT:
                        text = constraint.expression.empty()
                            ? "DEFAULT Redacted"
                            : "DEFAULT " + constraint.expression;
                        break;
                    default:
                        text = "UNKNOWN";
                        break;
                }

                if (!constraint.name.empty())
                {
                    return constraint.name + ": " + text;
                }
                return text;
            };

            // Metadata visibility hook: apply redaction policy once security levels are wired in.
            bool redact_details = shouldRedactMetadata(
                domain_info.domain_id,
                core::CatalogManager::PermissionObjectType::DOMAIN,
                core::ID{},
                static_cast<uint32_t>(core::CatalogManager::Privilege::USAGE));

            std::string schema_path;
            if (!isZeroUuid(domain_info.schema_id))
            {
                if (catalog->getSchemaPath(domain_info.schema_id, schema_path, &err_ctx) != core::Status::OK)
                {
                    schema_path.clear();
                }
            }

            current_result_set_->addRow({Value::makeVarchar("Domain Name"),
                                         Value::makeVarchar(domain_info.domain_name)});
            if (!schema_path.empty())
            {
                current_result_set_->addRow({Value::makeVarchar("Schema"),
                                             Value::makeVarchar(schema_path)});
            }
            current_result_set_->addRow({Value::makeVarchar("Domain Type"),
                                         Value::makeVarchar(domain_type_to_string(domain_info.domain_type))});

            if (!domain_info.collation_name.empty())
            {
                current_result_set_->addRow({Value::makeVarchar("Collation"),
                                             Value::makeVarchar(domain_info.collation_name)});
            }

            if (!domain_info.dialect_tag.empty())
            {
                current_result_set_->addRow({Value::makeVarchar("Dialect"),
                                             Value::makeVarchar(domain_info.dialect_tag)});
            }

            if (!domain_info.compat_name.empty())
            {
                current_result_set_->addRow({Value::makeVarchar("Compat Name"),
                                             Value::makeVarchar(domain_info.compat_name)});
            }

            if (domain_info.domain_type == core::DomainType::BASIC)
            {
                current_result_set_->addRow({Value::makeVarchar("Base Type"),
                                             Value::makeVarchar(formatType(domain_info.base_type,
                                                                           domain_info.precision,
                                                                           domain_info.scale))});
            }
            else if (domain_info.domain_type == core::DomainType::SET)
            {
                current_result_set_->addRow({Value::makeVarchar("Element Type"),
                                             Value::makeVarchar(format_domain_type_ref(domain_info.set_element_type))});
            }
            else if (domain_info.domain_type == core::DomainType::VARIANT)
            {
                std::ostringstream out;
                for (size_t i = 0; i < domain_info.variant_allowed_types.size(); ++i)
                {
                    if (i > 0)
                    {
                        out << ", ";
                    }
                    out << format_domain_type_ref(domain_info.variant_allowed_types[i]);
                }
                current_result_set_->addRow({Value::makeVarchar("Allowed Types"),
                                             Value::makeVarchar(redact_details ? "Redacted" : out.str())});
            }

            current_result_set_->addRow({Value::makeVarchar("Nullable"),
                                         Value::makeVarchar(domain_info.nullable ? "YES" : "NO")});

            std::string default_value = domain_info.default_value.empty() ? "NONE"
                                                                           : domain_info.default_value;
            if (redact_details)
            {
                default_value = "Redacted";
            }
            current_result_set_->addRow({Value::makeVarchar("Default"),
                                         Value::makeVarchar(default_value)});

            if (!domain_info.constraints.empty())
            {
                std::ostringstream out;
                for (size_t i = 0; i < domain_info.constraints.size(); ++i)
                {
                    if (i > 0)
                    {
                        out << "; ";
                    }
                    out << constraint_to_string(domain_info.constraints[i]);
                }
                current_result_set_->addRow({Value::makeVarchar("Constraints"),
                                             Value::makeVarchar(redact_details ? "Redacted" : out.str())});
            }

            if (domain_info.domain_type == core::DomainType::RECORD)
            {
                std::ostringstream out;
                for (size_t i = 0; i < domain_info.fields.size(); ++i)
                {
                    if (i > 0)
                    {
                        out << ", ";
                    }
                    const auto& field = domain_info.fields[i];
                    std::string type_str = formatType(field.type, field.precision, field.scale);
                    if (!isZeroUuid(field.domain_id))
                    {
                        core::DomainInfo field_domain;
                        if (domain_mgr->getDomain(field.domain_id, field_domain, &err_ctx) == core::Status::OK)
                        {
                            type_str = field_domain.domain_name;
                        }
                    }
                    out << field.name << " " << type_str;
                    if (!field.nullable)
                    {
                        out << " NOT NULL";
                    }
                }
                current_result_set_->addRow({Value::makeVarchar("Fields"),
                                             Value::makeVarchar(redact_details ? "Redacted" : out.str())});
            }
            else if (domain_info.domain_type == core::DomainType::ENUM)
            {
                std::vector<core::EnumValue> values = domain_info.enum_values;
                std::sort(values.begin(), values.end(),
                          [](const core::EnumValue& a, const core::EnumValue& b) {
                              return a.position < b.position;
                          });

                std::ostringstream out;
                for (size_t i = 0; i < values.size(); ++i)
                {
                    if (i > 0)
                    {
                        out << ", ";
                    }
                    out << values[i].label;
                }
                current_result_set_->addRow({Value::makeVarchar("Values"),
                                             Value::makeVarchar(redact_details ? "Redacted" : out.str())});
                current_result_set_->addRow({Value::makeVarchar("Wrap"),
                                             Value::makeVarchar(domain_info.enum_wrap ? "TRUE" : "FALSE")});
            }

            if (!isZeroUuid(domain_info.parent_domain_id))
            {
                core::DomainInfo parent;
                std::string parent_name = domain_info.parent_domain_id.toString();
                if (domain_mgr->getDomain(domain_info.parent_domain_id, parent, &err_ctx) == core::Status::OK)
                {
                    parent_name = parent.domain_name;
                }
                current_result_set_->addRow({Value::makeVarchar("Parent Domain"),
                                             Value::makeVarchar(parent_name)});
            }

            if (!domain_info.dialect_tag.empty())
            {
                current_result_set_->addRow({Value::makeVarchar("Dialect Tag"),
                                             Value::makeVarchar(domain_info.dialect_tag)});
            }

            if (!domain_info.compat_name.empty())
            {
                current_result_set_->addRow({Value::makeVarchar("Compat Name"),
                                             Value::makeVarchar(domain_info.compat_name)});
            }

            std::string comment;
            if (catalog->getComment(domain_info.domain_id, comment, &err_ctx) == core::Status::OK)
            {
                current_result_set_->addRow({Value::makeVarchar("Comment"),
                                             Value::makeVarchar(comment)});
            }
        }

        void Executor::executeShowGenerator()
        {
            // Read bytecode parameters
            std::string object_name = readString();

            // Get catalog manager
            auto* catalog = db_->catalog_manager();

            // Look up sequence (generator is Firebird terminology for sequence)
            core::CatalogManager::SequenceInfo seq_info;
            core::ErrorContext err_ctx;
            core::ID sequence_id;
            core::CatalogManager::ObjectType resolved_type;
            core::CatalogManager::ResolvedObject resolved_seq;
            auto schema_status = resolveObjectIdForQualifiedName(
                object_name, core::CatalogManager::ObjectType::SEQUENCE,
                sequence_id, resolved_type, &resolved_seq, &err_ctx);
            if (schema_status != core::Status::OK)
            {
                error("Generator/Sequence '" + object_name + "' not found");
            }
            auto seq_status = catalog->getSequence(resolved_seq.schema_id, resolved_seq.object_name,
                                                    seq_info, &err_ctx);
            if (seq_status != core::Status::OK)
            {
                error("Generator/Sequence '" + object_name + "' not found");
            }

            // Create result set
            if (!current_result_set_)
            {
                current_result_set_ = std::make_unique<ResultSet>();
            }

            current_result_set_->addColumn("Property", core::DataType::VARCHAR);
            current_result_set_->addColumn("Value", core::DataType::VARCHAR);

            bool redact_sequence = shouldRedactMetadata(
                seq_info.sequence_id,
                core::CatalogManager::PermissionObjectType::SEQUENCE,
                seq_info.owner_id,
                static_cast<uint32_t>(core::CatalogManager::Privilege::SEQUENCE_USAGE));

            std::vector<Value> row1, row2, row3, row4, row5;
            row1.push_back(Value::makeVarchar("Generator Name"));
            row1.push_back(Value::makeVarchar(redact_sequence ? "Redacted" : seq_info.name));
            current_result_set_->addRow(row1);

            row2.push_back(Value::makeVarchar("Current Value"));
            row2.push_back(Value::makeVarchar(redact_sequence ? "Redacted"
                                                              : std::to_string(seq_info.current_value)));
            current_result_set_->addRow(row2);

            row3.push_back(Value::makeVarchar("Increment"));
            row3.push_back(Value::makeVarchar(redact_sequence ? "Redacted"
                                                              : std::to_string(seq_info.increment_by)));
            current_result_set_->addRow(row3);

            row4.push_back(Value::makeVarchar("Min Value"));
            row4.push_back(Value::makeVarchar(redact_sequence ? "Redacted"
                                                              : std::to_string(seq_info.min_value)));
            current_result_set_->addRow(row4);

            row5.push_back(Value::makeVarchar("Max Value"));
            row5.push_back(Value::makeVarchar(redact_sequence ? "Redacted"
                                                              : std::to_string(seq_info.max_value)));
            current_result_set_->addRow(row5);
        }

        void Executor::executeShowSchema()
        {
            // Read bytecode parameters
            std::string object_name = readString();

            // Get catalog manager
            auto* catalog = db_->catalog_manager();

            // Create result set
            if (!current_result_set_)
            {
                current_result_set_ = std::make_unique<ResultSet>();
            }

            if (object_name.empty())
            {
                // List all schemas
                current_result_set_->addColumn("Schema", core::DataType::VARCHAR);
                current_result_set_->addColumn("Owner", core::DataType::VARCHAR);

                std::vector<core::CatalogManager::SchemaInfo> schemas;
                core::ErrorContext err_ctx;
                auto status = catalog->listSchemas(schemas, &err_ctx);
                    if (status == core::Status::OK)
                    {
                        for (const auto& schema : schemas)
                        {
                            bool redact_schema = shouldRedactMetadata(
                                schema.schema_id,
                                core::CatalogManager::PermissionObjectType::SCHEMA,
                                schema.owner_id,
                                static_cast<uint32_t>(core::CatalogManager::Privilege::USAGE));
                            if (redact_schema)
                            {
                                continue;
                            }
                            current_result_set_->addRow({Value::makeVarchar(schema.schema_name), Value::makeVarchar("SYSDBA")});
                        }
                    }
                }
            else
            {
                // Show specific schema
                core::CatalogManager::SchemaInfo schema_info;
                core::ErrorContext err_ctx;
                core::ID schema_id;
                core::CatalogManager::ObjectType resolved_type;
                auto status = resolveObjectIdForQualifiedName(
                    object_name, core::CatalogManager::ObjectType::SCHEMA,
                    schema_id, resolved_type, nullptr, &err_ctx);
                if (status != core::Status::OK)
                {
                    error("Schema '" + object_name + "' not found");
                }

                status = catalog->getSchema(schema_id, schema_info, &err_ctx);
                if (status != core::Status::OK)
                {
                    error("Schema '" + object_name + "' not found");
                }

                current_result_set_->addColumn("Property", core::DataType::VARCHAR);
                current_result_set_->addColumn("Value", core::DataType::VARCHAR);

                bool redact_schema = shouldRedactMetadata(
                    schema_info.schema_id,
                    core::CatalogManager::PermissionObjectType::SCHEMA,
                    schema_info.owner_id,
                    static_cast<uint32_t>(core::CatalogManager::Privilege::USAGE));
                current_result_set_->addRow({Value::makeVarchar("Schema Name"),
                                             Value::makeVarchar(redact_schema ? "Redacted"
                                                                              : schema_info.schema_name)});
            }
        }

        void Executor::executeShowRole()
        {
            // Read bytecode parameters
            std::string object_name = readString();

            // Get catalog manager
            auto* catalog = db_->catalog_manager();

            // Look up role by name
            core::CatalogManager::RoleInfo role_info;
            core::ErrorContext err_ctx;
            auto status = catalog->getRoleByName(object_name, role_info, &err_ctx);
            if (status != core::Status::OK)
            {
                error("Role '" + object_name + "' not found");
            }

            // Create result set
            if (!current_result_set_)
            {
                current_result_set_ = std::make_unique<ResultSet>();
            }

            current_result_set_->addColumn("Role", core::DataType::VARCHAR);
            current_result_set_->addColumn("Owner", core::DataType::VARCHAR);

            std::vector<Value> row;
            row.push_back(Value::makeVarchar(role_info.role_name));
            row.push_back(Value::makeVarchar("SYSDBA"));
            current_result_set_->addRow(row);
        }

        void Executor::executeShowGrants()
        {
            // Read bytecode parameters
            std::string object_name = readString();

            auto* catalog = db_->catalog_manager();
            if (!catalog)
            {
                error("Catalog manager not available");
            }

            // Create result set - list grants for object or all
            if (!current_result_set_)
            {
                current_result_set_ = std::make_unique<ResultSet>();
            }

            current_result_set_->addColumn("Grantee", core::DataType::VARCHAR);
            current_result_set_->addColumn("Object", core::DataType::VARCHAR);
            current_result_set_->addColumn("Privilege", core::DataType::VARCHAR);
            current_result_set_->addColumn("Grantor", core::DataType::VARCHAR);
            current_result_set_->addColumn("Grant Option", core::DataType::VARCHAR);

            core::ErrorContext err_ctx;

            // Metadata visibility hook: apply redaction policy once security levels are wired in.
            bool redact_details = false;

            auto format_grantee = [&](const core::ID& grantee_id,
                                      core::CatalogManager::GranteeType grantee_type) -> std::string {
                switch (grantee_type)
                {
                    case core::CatalogManager::GranteeType::PUBLIC:
                        return "PUBLIC";
                    case core::CatalogManager::GranteeType::USER:
                    {
                        core::CatalogManager::UserInfo user;
                        if (catalog->getUser(grantee_id, user, &err_ctx) == core::Status::OK)
                        {
                            return user.username;
                        }
                        return grantee_id.toString();
                    }
                    case core::CatalogManager::GranteeType::ROLE:
                    {
                        core::CatalogManager::RoleInfo role;
                        if (catalog->getRole(grantee_id, role, &err_ctx) == core::Status::OK)
                        {
                            return role.role_name;
                        }
                        return grantee_id.toString();
                    }
                    case core::CatalogManager::GranteeType::GROUP:
                    {
                        core::CatalogManager::GroupInfo group;
                        if (catalog->getGroup(grantee_id, group, &err_ctx) == core::Status::OK)
                        {
                            return group.group_name;
                        }
                        return grantee_id.toString();
                    }
                }
                return grantee_id.toString();
            };

            auto format_grantor = [&](const core::ID& grantor_id) -> std::string {
                if (isZeroUuid(grantor_id))
                {
                    return "SYSTEM";
                }
                core::CatalogManager::UserInfo user;
                if (catalog->getUser(grantor_id, user, &err_ctx) == core::Status::OK)
                {
                    return user.username;
                }
                return grantor_id.toString();
            };

            auto normalize_principal = [&](const std::string& name) -> std::string {
                std::string cleaned = name;
                auto at_pos = cleaned.find('@');
                if (at_pos != std::string::npos)
                {
                    cleaned = cleaned.substr(0, at_pos);
                }
                if (cleaned.size() >= 2)
                {
                    char first = cleaned.front();
                    char last = cleaned.back();
                    if ((first == '\'' && last == '\'') ||
                        (first == '"' && last == '"') ||
                        (first == '`' && last == '`'))
                    {
                        cleaned = cleaned.substr(1, cleaned.size() - 2);
                    }
                }
                return cleaned;
            };

            auto resolve_grantee = [&](const std::string& name,
                                       core::CatalogManager::GranteeType* type_out,
                                       core::ID* id_out,
                                       std::string* label_out) -> bool {
                std::string resolved_name = name;
                if (resolved_name.empty())
                {
                    if (!conn_ctx_)
                    {
                        return false;
                    }
                    core::CatalogManager::UserInfo user;
                    if (catalog->getUser(conn_ctx_->getCurrentUserId(), user, &err_ctx) != core::Status::OK)
                    {
                        return false;
                    }
                    *type_out = core::CatalogManager::GranteeType::USER;
                    *id_out = user.user_id;
                    *label_out = user.username;
                    return true;
                }

                resolved_name = normalize_principal(resolved_name);
                std::string upper = scratchbird::core::IdentifierUtils::toUpper(resolved_name);
                if (upper == "CURRENT_USER" || upper == "CURRENT_USER()")
                {
                    if (!conn_ctx_)
                    {
                        return false;
                    }
                    core::CatalogManager::UserInfo user;
                    if (catalog->getUser(conn_ctx_->getCurrentUserId(), user, &err_ctx) != core::Status::OK)
                    {
                        return false;
                    }
                    *type_out = core::CatalogManager::GranteeType::USER;
                    *id_out = user.user_id;
                    *label_out = user.username;
                    return true;
                }
                if (upper == "PUBLIC")
                {
                    *type_out = core::CatalogManager::GranteeType::PUBLIC;
                    *id_out = core::ID{};
                    *label_out = "PUBLIC";
                    return true;
                }

                core::CatalogManager::UserInfo user;
                if (catalog->getUserByName(resolved_name, user, &err_ctx) == core::Status::OK)
                {
                    *type_out = core::CatalogManager::GranteeType::USER;
                    *id_out = user.user_id;
                    *label_out = user.username;
                    return true;
                }

                core::CatalogManager::RoleInfo role;
                if (catalog->getRoleByName(resolved_name, role, &err_ctx) == core::Status::OK)
                {
                    *type_out = core::CatalogManager::GranteeType::ROLE;
                    *id_out = role.role_id;
                    *label_out = role.role_name;
                    return true;
                }

                return false;
            };

            auto add_privilege_rows = [&](const std::string& grantee,
                                          const std::string& object_label,
                                          const std::string& grantor,
                                          bool grant_option,
                                          uint32_t privileges) {
                const uint32_t all_mask = static_cast<uint32_t>(core::CatalogManager::Privilege::ALL);
                auto add_row = [&](const std::string& privilege_name) {
                    current_result_set_->addRow({
                        Value::makeVarchar(grantee),
                        Value::makeVarchar(object_label),
                        Value::makeVarchar(privilege_name),
                        Value::makeVarchar(grantor),
                        Value::makeVarchar(grant_option ? "YES" : "NO")
                    });
                };

                if (privileges == all_mask)
                {
                    add_row("ALL");
                    return;
                }

                struct PrivEntry
                {
                    core::CatalogManager::Privilege priv;
                    const char* name;
                };
                static const PrivEntry entries[] = {
                    {core::CatalogManager::Privilege::SELECT, "SELECT"},
                    {core::CatalogManager::Privilege::INSERT, "INSERT"},
                    {core::CatalogManager::Privilege::UPDATE, "UPDATE"},
                    {core::CatalogManager::Privilege::DELETE, "DELETE"},
                    {core::CatalogManager::Privilege::TRUNCATE, "TRUNCATE"},
                    {core::CatalogManager::Privilege::REFERENCES, "REFERENCES"},
                    {core::CatalogManager::Privilege::TRIGGER, "TRIGGER"},
                    {core::CatalogManager::Privilege::CREATE, "CREATE"},
                    {core::CatalogManager::Privilege::USAGE, "USAGE"},
                    {core::CatalogManager::Privilege::SEQUENCE_USAGE, "SEQUENCE_USAGE"},
                    {core::CatalogManager::Privilege::SEQUENCE_UPDATE, "SEQUENCE_UPDATE"},
                    {core::CatalogManager::Privilege::EXECUTE, "EXECUTE"},
                    {core::CatalogManager::Privilege::CONNECT, "CONNECT"},
                    {core::CatalogManager::Privilege::TEMPORARY, "TEMPORARY"},
                    {core::CatalogManager::Privilege::COPY_FILE, "COPY"},
                    {core::CatalogManager::Privilege::CREATE_JOB, "CREATE JOB"},
                    {core::CatalogManager::Privilege::VIEW_JOB_HISTORY, "VIEW JOB HISTORY"},
                    {core::CatalogManager::Privilege::EXECUTE_EXTERNAL_JOB, "EXECUTE EXTERNAL JOB"}
                };

                bool any = false;
                for (const auto& entry : entries)
                {
                    const uint32_t mask = static_cast<uint32_t>(entry.priv);
                    if ((privileges & mask) != 0)
                    {
                        add_row(entry.name);
                        any = true;
                    }
                }

                if (!any)
                {
                    add_row("UNKNOWN");
                }
            };

            auto add_role_memberships = [&](const std::string& grantee_label,
                                            const core::ID& user_id) {
                std::vector<core::CatalogManager::RoleMembershipInfo> memberships;
                if (catalog->getUserRoles(user_id, memberships, &err_ctx) != core::Status::OK)
                {
                    return;
                }
                for (const auto& membership : memberships)
                {
                    core::CatalogManager::RoleInfo role;
                    if (catalog->getRole(membership.role_id, role, &err_ctx) != core::Status::OK)
                    {
                        continue;
                    }
                    std::string grantor = format_grantor(membership.granted_by);
                    current_result_set_->addRow({
                        Value::makeVarchar(grantee_label),
                        Value::makeVarchar("ROLE " + role.role_name),
                        Value::makeVarchar("ROLE"),
                        Value::makeVarchar(grantor),
                        Value::makeVarchar(membership.with_admin_option ? "YES" : "NO")
                    });
                }
            };

            auto build_search_path = [&]() {
                std::vector<std::string> normalized_paths;
                if (conn_ctx_)
                {
                    const auto& paths = conn_ctx_->search_path();
                    normalized_paths.reserve(paths.size());
                    for (const auto& entry : paths)
                    {
                        std::string normalized = scratchbird::core::IdentifierUtils::toUpper(
                            normalizeSchemaPath(entry));
                        if (!normalized.empty())
                        {
                            normalized_paths.push_back(normalized);
                        }
                    }
                }
                return normalized_paths;
            };

            auto schema_visible = [&](const std::string& schema_path,
                                      const std::vector<std::string>& normalized_paths) {
                if (normalized_paths.empty())
                {
                    return true;
                }
                if (schema_path.empty())
                {
                    return true;
                }
                std::string normalized_schema = scratchbird::core::IdentifierUtils::toUpper(
                    normalizeSchemaPath(schema_path));
                for (const auto& entry : normalized_paths)
                {
                    if (normalized_schema == entry ||
                        normalized_schema.rfind(entry + ".", 0) == 0)
                    {
                        return true;
                    }
                }
                return false;
            };

            core::CatalogManager::GranteeType filter_type =
                core::CatalogManager::GranteeType::USER;
            core::ID filter_id;
            std::string filter_label;
            bool filter_by_grantee = resolve_grantee(object_name, &filter_type, &filter_id, &filter_label);

            if (filter_by_grantee)
            {
                std::vector<core::CatalogManager::PermissionInfo> permissions;
                auto status = catalog->listPermissions(permissions, &err_ctx);
                if (status != core::Status::OK)
                {
                    error("Failed to load grants");
                }

                const auto normalized_paths = build_search_path();

                auto grantee_matches = [&](const auto& perm) {
                    if (perm.grantee_type == filter_type && perm.grantee_id == filter_id)
                    {
                        return true;
                    }
                    if (filter_type == core::CatalogManager::GranteeType::USER &&
                        perm.grantee_type == core::CatalogManager::GranteeType::PUBLIC)
                    {
                        return true;
                    }
                    return false;
                };

                for (const auto& perm : permissions)
                {
                    if (!grantee_matches(perm))
                    {
                        continue;
                    }
                    std::string object_label = perm.object_id.toString();
                    core::CatalogManager::ResolvedObject resolved;
                    if (catalog->resolveObjectId(perm.object_id, resolved, &err_ctx) == core::Status::OK)
                    {
                        if (!schema_visible(resolved.schema_path, normalized_paths))
                        {
                            continue;
                        }
                        if (!resolved.full_path.empty())
                        {
                            object_label = resolved.full_path;
                        }
                    }

                    bool redact_entry = shouldRedactMetadata(
                        perm.object_id,
                        perm.object_type,
                        core::ID{},
                        static_cast<uint32_t>(core::CatalogManager::Privilege::ALL));
                    if (redact_entry)
                    {
                        continue;
                    }

                    std::string grantee = format_grantee(perm.grantee_id, perm.grantee_type);
                    std::string grantor = format_grantor(perm.grantor_id);
                    add_privilege_rows(grantee, object_label, grantor,
                                       perm.grant_option, perm.privileges);
                }

                std::vector<core::CatalogManager::SchemaInfo> schemas;
                if (catalog->listSchemas(schemas, &err_ctx) == core::Status::OK)
                {
                    for (const auto& schema : schemas)
                    {
                        std::string schema_path;
                        if (catalog->getSchemaPath(schema.schema_id, schema_path, &err_ctx) != core::Status::OK)
                        {
                            schema_path = schema.schema_name;
                        }
                        if (!schema_visible(schema_path, normalized_paths))
                        {
                            continue;
                        }

                        std::vector<core::CatalogManager::TableInfo> tables;
                        if (catalog->listTables(schema.schema_id, tables, &err_ctx) != core::Status::OK)
                        {
                            continue;
                        }

                        for (const auto& table : tables)
                        {
                            bool redact_columns = shouldRedactMetadata(
                                table.table_id,
                                core::CatalogManager::PermissionObjectType::TABLE,
                                core::ID{},
                                static_cast<uint32_t>(core::CatalogManager::Privilege::ALL));
                            if (redact_columns)
                            {
                                continue;
                            }

                            std::vector<core::CatalogManager::ColumnPermissionInfo> column_perms;
                            if (catalog->getColumnPermissions(table.table_id, column_perms, &err_ctx) != core::Status::OK)
                            {
                                continue;
                            }

                            if (column_perms.empty())
                            {
                                continue;
                            }

                            std::string table_label = schema_path.empty()
                                ? table.table_name
                                : schema_path + "." + table.table_name;

                            for (const auto& perm : column_perms)
                            {
                                if (!grantee_matches(perm))
                                {
                                    continue;
                                }
                                std::string grantee = format_grantee(perm.grantee_id, perm.grantee_type);
                                std::string grantor = format_grantor(perm.grantor_id);
                                std::string column_label = table_label + "." + perm.column_name;
                                add_privilege_rows(grantee, column_label, grantor,
                                                   perm.grant_option, perm.privileges);
                            }
                        }
                    }
                }

                if (filter_type == core::CatalogManager::GranteeType::USER)
                {
                    add_role_memberships(filter_label, filter_id);
                }

                return;
            }

            if (!object_name.empty())
            {
                core::ID object_id;
                core::CatalogManager::ObjectType resolved_type;
                auto status = resolveObjectIdForQualifiedName(
                    object_name, core::CatalogManager::ObjectType::UNKNOWN,
                    object_id, resolved_type, nullptr, &err_ctx);
                if (status != core::Status::OK)
                {
                    core::CatalogManager::JobInfo job_info;
                    if (catalog->getJobByName(object_name, job_info, &err_ctx) == core::Status::OK)
                    {
                        object_id = job_info.job_id;
                        resolved_type = core::CatalogManager::ObjectType::JOB;
                    }
                    else
                    {
                        error("Object '" + object_name + "' not found");
                    }
                }

                core::CatalogManager::PermissionObjectType perm_type;
                switch (resolved_type)
                {
                    case core::CatalogManager::ObjectType::SCHEMA:
                        perm_type = core::CatalogManager::PermissionObjectType::SCHEMA;
                        break;
                    case core::CatalogManager::ObjectType::TABLE:
                        perm_type = core::CatalogManager::PermissionObjectType::TABLE;
                        break;
                    case core::CatalogManager::ObjectType::VIEW:
                        perm_type = core::CatalogManager::PermissionObjectType::VIEW;
                        break;
                    case core::CatalogManager::ObjectType::SEQUENCE:
                        perm_type = core::CatalogManager::PermissionObjectType::SEQUENCE;
                        break;
                    case core::CatalogManager::ObjectType::PROCEDURE:
                        perm_type = core::CatalogManager::PermissionObjectType::PROCEDURE;
                        break;
                    case core::CatalogManager::ObjectType::FUNCTION:
                        perm_type = core::CatalogManager::PermissionObjectType::FUNCTION;
                        break;
                    case core::CatalogManager::ObjectType::DOMAIN:
                        perm_type = core::CatalogManager::PermissionObjectType::DOMAIN;
                        break;
                    case core::CatalogManager::ObjectType::JOB:
                        perm_type = core::CatalogManager::PermissionObjectType::JOB;
                        break;
                    case core::CatalogManager::ObjectType::DATABASE:
                        perm_type = core::CatalogManager::PermissionObjectType::DATABASE;
                        break;
                    default:
                        error("SHOW GRANTS not supported for object type");
                }

                redact_details = shouldRedactMetadata(
                    object_id,
                    perm_type,
                    core::ID{},
                    static_cast<uint32_t>(core::CatalogManager::Privilege::ALL));

                std::vector<core::CatalogManager::PermissionInfo> permissions;
                status = catalog->getObjectPermissions(object_id, perm_type, permissions, &err_ctx);
                if (status != core::Status::OK)
                {
                    error("Failed to load grants");
                }

                std::string object_label = object_name;
                core::CatalogManager::ResolvedObject resolved;
                if (catalog->resolveObjectId(object_id, resolved, &err_ctx) == core::Status::OK &&
                    !resolved.full_path.empty())
                {
                    object_label = resolved.full_path;
                }

                if (redact_details)
                {
                    current_result_set_->addRow({
                        Value::makeVarchar("Redacted"),
                        Value::makeVarchar(object_label),
                        Value::makeVarchar("Redacted"),
                        Value::makeVarchar("Redacted"),
                        Value::makeVarchar("Redacted")
                    });
                    return;
                }

                for (const auto& perm : permissions)
                {
                    std::string grantee = format_grantee(perm.grantee_id, perm.grantee_type);
                    std::string grantor = format_grantor(perm.grantor_id);
                    add_privilege_rows(grantee, object_label, grantor,
                                       perm.grant_option, perm.privileges);
                }

                if (perm_type == core::CatalogManager::PermissionObjectType::TABLE)
                {
                    std::vector<core::CatalogManager::ColumnPermissionInfo> column_perms;
                    if (catalog->getColumnPermissions(object_id, column_perms, &err_ctx) == core::Status::OK)
                    {
                        for (const auto& perm : column_perms)
                        {
                            std::string grantee = format_grantee(perm.grantee_id, perm.grantee_type);
                            std::string grantor = format_grantor(perm.grantor_id);
                            std::string column_label = object_label + "." + perm.column_name;
                            add_privilege_rows(grantee, column_label, grantor,
                                               perm.grant_option, perm.privileges);
                        }
                    }
                }

                return;
            }

            std::vector<core::CatalogManager::PermissionInfo> permissions;
            auto status = catalog->listPermissions(permissions, &err_ctx);
            if (status != core::Status::OK)
            {
                error("Failed to load grants");
            }

            const auto normalized_paths = build_search_path();

            for (const auto& perm : permissions)
            {
                std::string object_label = perm.object_id.toString();
                core::CatalogManager::ResolvedObject resolved;
                if (catalog->resolveObjectId(perm.object_id, resolved, &err_ctx) == core::Status::OK)
                {
                    if (!schema_visible(resolved.schema_path, normalized_paths))
                    {
                        continue;
                    }
                    if (!resolved.full_path.empty())
                    {
                        object_label = resolved.full_path;
                    }
                }

                bool redact_entry = shouldRedactMetadata(
                    perm.object_id,
                    perm.object_type,
                    core::ID{},
                    static_cast<uint32_t>(core::CatalogManager::Privilege::ALL));
                if (redact_entry)
                {
                    continue;
                }

                std::string grantee = format_grantee(perm.grantee_id, perm.grantee_type);
                std::string grantor = format_grantor(perm.grantor_id);
                add_privilege_rows(grantee, object_label, grantor,
                                   perm.grant_option, perm.privileges);
            }

            std::vector<core::CatalogManager::SchemaInfo> schemas;
            if (catalog->listSchemas(schemas, &err_ctx) != core::Status::OK)
            {
                return;
            }

            for (const auto& schema : schemas)
            {
                std::string schema_path;
                if (catalog->getSchemaPath(schema.schema_id, schema_path, &err_ctx) != core::Status::OK)
                {
                    schema_path = schema.schema_name;
                }
                if (!schema_visible(schema_path, normalized_paths))
                {
                    continue;
                }

                std::vector<core::CatalogManager::TableInfo> tables;
                if (catalog->listTables(schema.schema_id, tables, &err_ctx) != core::Status::OK)
                {
                    continue;
                }

                for (const auto& table : tables)
                {
                    bool redact_columns = shouldRedactMetadata(
                        table.table_id,
                        core::CatalogManager::PermissionObjectType::TABLE,
                        core::ID{},
                        static_cast<uint32_t>(core::CatalogManager::Privilege::ALL));
                    if (redact_columns)
                    {
                        continue;
                    }

                    std::vector<core::CatalogManager::ColumnPermissionInfo> column_perms;
                    if (catalog->getColumnPermissions(table.table_id, column_perms, &err_ctx) != core::Status::OK)
                    {
                        continue;
                    }

                    if (column_perms.empty())
                    {
                        continue;
                    }

                    std::string table_label = schema_path.empty()
                        ? table.table_name
                        : schema_path + "." + table.table_name;

                    for (const auto& perm : column_perms)
                    {
                        std::string grantee = format_grantee(perm.grantee_id, perm.grantee_type);
                        std::string grantor = format_grantor(perm.grantor_id);
                        std::string column_label = table_label + "." + perm.column_name;
                        add_privilege_rows(grantee, column_label, grantor,
                                           perm.grant_option, perm.privileges);
                    }
                }
            }
        }

        void Executor::executeShowJobs()
        {
            std::string like_pattern = readString();

            auto* catalog = db_->catalog_manager();
            if (!catalog)
            {
                error("Catalog manager not available");
            }

            std::vector<core::CatalogManager::JobInfo> jobs;
            core::ErrorContext err_ctx;
            if (catalog->listJobs(jobs, &err_ctx) != core::Status::OK)
            {
                error("Failed to list jobs");
            }

            if (!current_result_set_)
            {
                current_result_set_ = std::make_unique<ResultSet>();
            }

            current_result_set_->addColumn("Job Name", core::DataType::VARCHAR);
            current_result_set_->addColumn("Job Type", core::DataType::VARCHAR);
            current_result_set_->addColumn("Schedule", core::DataType::VARCHAR);
            current_result_set_->addColumn("Next Run", core::DataType::TIMESTAMP);
            current_result_set_->addColumn("State", core::DataType::VARCHAR);
            current_result_set_->addColumn("Owner", core::DataType::VARCHAR);

            auto scheduleToString = [](core::CatalogManager::ScheduleKind kind) -> std::string {
                switch (kind)
                {
                    case core::CatalogManager::ScheduleKind::CRON: return "CRON";
                    case core::CatalogManager::ScheduleKind::AT: return "AT";
                    case core::CatalogManager::ScheduleKind::EVERY: return "EVERY";
                    default: return "UNKNOWN";
                }
            };

            auto typeToString = [](core::CatalogManager::JobType type) -> std::string {
                switch (type)
                {
                    case core::CatalogManager::JobType::SQL: return "SQL";
                    case core::CatalogManager::JobType::PROCEDURE: return "PROCEDURE";
                    case core::CatalogManager::JobType::EXTERNAL: return "EXTERNAL";
                    default: return "UNKNOWN";
                }
            };

            auto stateToString = [](core::CatalogManager::JobState state) -> std::string {
                switch (state)
                {
                    case core::CatalogManager::JobState::ENABLED: return "ENABLED";
                    case core::CatalogManager::JobState::DISABLED: return "DISABLED";
                    case core::CatalogManager::JobState::PAUSED: return "PAUSED";
                    default: return "UNKNOWN";
                }
            };

            auto can_view_history = [&]() -> bool {
                if (!conn_ctx_)
                {
                    return true;
                }
                if (conn_ctx_->isSuperuser() || hasJobAdminPrivilege(catalog, conn_ctx_))
                {
                    return true;
                }
                return checkPermission(
                    db_->uuid(),
                    core::CatalogManager::PermissionObjectType::DATABASE,
                    static_cast<uint32_t>(core::CatalogManager::Privilege::VIEW_JOB_HISTORY));
            };

            bool view_history = can_view_history();

            auto can_access = [&](const core::CatalogManager::JobInfo& job) -> bool {
                if (view_history)
                {
                    return true;
                }
                if (!conn_ctx_)
                {
                    return true;
                }
                if (!isZeroUuid(conn_ctx_->getCurrentUserId()) &&
                    job.created_by_user_uuid == conn_ctx_->getCurrentUserId())
                {
                    return true;
                }
                return checkPermission(
                    job.job_id,
                    core::CatalogManager::PermissionObjectType::JOB,
                    static_cast<uint32_t>(core::CatalogManager::Privilege::EXECUTE));
            };

            for (const auto& job : jobs)
            {
                if (!like_pattern.empty() && !matchSqlLike(job.job_name, like_pattern))
                {
                    continue;
                }
                if (!can_access(job))
                {
                    continue;
                }

                std::string owner = job.created_by_user_uuid.toString();
                if (!isZeroUuid(job.created_by_user_uuid))
                {
                    core::CatalogManager::UserInfo owner_info;
                    if (catalog->getUser(job.created_by_user_uuid, owner_info, &err_ctx) == core::Status::OK)
                    {
                        owner = owner_info.username;
                    }
                }

                Value next_run = Value::makeNull(core::DataType::TIMESTAMP);
                if (job.next_run_time > 0)
                {
                    next_run = Value::makeTimestamp(static_cast<int64_t>(job.next_run_time) * 1000);
                }

                current_result_set_->addRow({
                    Value::makeVarchar(job.job_name),
                    Value::makeVarchar(typeToString(job.job_type)),
                    Value::makeVarchar(scheduleToString(job.schedule_kind)),
                    next_run,
                    Value::makeVarchar(stateToString(job.state)),
                    Value::makeVarchar(owner)
                });
            }
        }

        void Executor::executeShowJob()
        {
            std::string job_name = readString();
            if (job_name.empty())
            {
                error("SHOW JOB requires a job name");
            }

            auto* catalog = db_->catalog_manager();
            if (!catalog)
            {
                error("Catalog manager not available");
            }

            core::CatalogManager::JobInfo job;
            core::ErrorContext err_ctx;
            if (catalog->getJobByName(job_name, job, &err_ctx) != core::Status::OK)
            {
                error("Job not found: " + job_name);
            }

            bool can_view_history = !conn_ctx_ ||
                conn_ctx_->isSuperuser() ||
                hasJobAdminPrivilege(catalog, conn_ctx_) ||
                checkPermission(db_->uuid(),
                                core::CatalogManager::PermissionObjectType::DATABASE,
                                static_cast<uint32_t>(core::CatalogManager::Privilege::VIEW_JOB_HISTORY));

            if (conn_ctx_ && !can_view_history &&
                !(job.created_by_user_uuid == conn_ctx_->getCurrentUserId()) &&
                !checkPermission(job.job_id,
                                 core::CatalogManager::PermissionObjectType::JOB,
                                 static_cast<uint32_t>(core::CatalogManager::Privilege::EXECUTE)))
            {
                error("Permission denied: SHOW JOB requires job owner or VIEW JOB HISTORY privilege");
            }

            if (!current_result_set_)
            {
                current_result_set_ = std::make_unique<ResultSet>();
            }

            current_result_set_->addColumn("Job Name", core::DataType::VARCHAR);
            current_result_set_->addColumn("Job Type", core::DataType::VARCHAR);
            current_result_set_->addColumn("Schedule", core::DataType::VARCHAR);
            current_result_set_->addColumn("Cron", core::DataType::VARCHAR);
            current_result_set_->addColumn("Interval Seconds", core::DataType::INT64);
            current_result_set_->addColumn("Starts At", core::DataType::TIMESTAMP);
            current_result_set_->addColumn("Ends At", core::DataType::TIMESTAMP);
            current_result_set_->addColumn("Next Run", core::DataType::TIMESTAMP);
            current_result_set_->addColumn("State", core::DataType::VARCHAR);

            Value starts_at = job.starts_at ? Value::makeTimestamp(static_cast<int64_t>(job.starts_at) * 1000)
                                            : Value::makeNull(core::DataType::TIMESTAMP);
            Value ends_at = job.ends_at ? Value::makeTimestamp(static_cast<int64_t>(job.ends_at) * 1000)
                                        : Value::makeNull(core::DataType::TIMESTAMP);
            Value next_run = job.next_run_time ? Value::makeTimestamp(static_cast<int64_t>(job.next_run_time) * 1000)
                                               : Value::makeNull(core::DataType::TIMESTAMP);

            auto scheduleToString = [](core::CatalogManager::ScheduleKind kind) -> std::string {
                switch (kind)
                {
                    case core::CatalogManager::ScheduleKind::CRON: return "CRON";
                    case core::CatalogManager::ScheduleKind::AT: return "AT";
                    case core::CatalogManager::ScheduleKind::EVERY: return "EVERY";
                    default: return "UNKNOWN";
                }
            };

            auto typeToString = [](core::CatalogManager::JobType type) -> std::string {
                switch (type)
                {
                    case core::CatalogManager::JobType::SQL: return "SQL";
                    case core::CatalogManager::JobType::PROCEDURE: return "PROCEDURE";
                    case core::CatalogManager::JobType::EXTERNAL: return "EXTERNAL";
                    default: return "UNKNOWN";
                }
            };

            auto stateToString = [](core::CatalogManager::JobState state) -> std::string {
                switch (state)
                {
                    case core::CatalogManager::JobState::ENABLED: return "ENABLED";
                    case core::CatalogManager::JobState::DISABLED: return "DISABLED";
                    case core::CatalogManager::JobState::PAUSED: return "PAUSED";
                    default: return "UNKNOWN";
                }
            };

            current_result_set_->addRow({
                Value::makeVarchar(job.job_name),
                Value::makeVarchar(typeToString(job.job_type)),
                Value::makeVarchar(scheduleToString(job.schedule_kind)),
                Value::makeVarchar(job.cron_expression),
                Value::makeInt64(job.interval_seconds),
                starts_at,
                ends_at,
                next_run,
                Value::makeVarchar(stateToString(job.state))
            });
        }

        void Executor::executeShowJobRuns()
        {
            std::string job_name = readString();
            if (job_name.empty())
            {
                error("SHOW JOB RUNS requires a job name");
            }

            auto* catalog = db_->catalog_manager();
            if (!catalog)
            {
                error("Catalog manager not available");
            }

            core::CatalogManager::JobInfo job;
            core::ErrorContext err_ctx;
            if (catalog->getJobByName(job_name, job, &err_ctx) != core::Status::OK)
            {
                error("Job not found: " + job_name);
            }

            bool can_view_history = !conn_ctx_ ||
                conn_ctx_->isSuperuser() ||
                hasJobAdminPrivilege(catalog, conn_ctx_) ||
                checkPermission(db_->uuid(),
                                core::CatalogManager::PermissionObjectType::DATABASE,
                                static_cast<uint32_t>(core::CatalogManager::Privilege::VIEW_JOB_HISTORY));

            if (conn_ctx_ && !can_view_history &&
                !(job.created_by_user_uuid == conn_ctx_->getCurrentUserId()) &&
                !checkPermission(job.job_id,
                                 core::CatalogManager::PermissionObjectType::JOB,
                                 static_cast<uint32_t>(core::CatalogManager::Privilege::EXECUTE)))
            {
                error("Permission denied: SHOW JOB RUNS requires job owner or VIEW JOB HISTORY privilege");
            }

            std::vector<core::CatalogManager::JobRunInfo> runs;
            if (catalog->listJobRuns(job.job_id, runs, &err_ctx) != core::Status::OK)
            {
                error("Failed to list job runs");
            }

            if (!current_result_set_)
            {
                current_result_set_ = std::make_unique<ResultSet>();
            }

            current_result_set_->addColumn("Job Run ID", core::DataType::VARCHAR);
            current_result_set_->addColumn("State", core::DataType::VARCHAR);
            current_result_set_->addColumn("Scheduled At", core::DataType::TIMESTAMP);
            current_result_set_->addColumn("Started At", core::DataType::TIMESTAMP);
            current_result_set_->addColumn("Completed At", core::DataType::TIMESTAMP);
            current_result_set_->addColumn("Retry Count", core::DataType::INT32);
            current_result_set_->addColumn("Rows Affected", core::DataType::INT64);
            current_result_set_->addColumn("Error Code", core::DataType::INT32);
            current_result_set_->addColumn("Message", core::DataType::VARCHAR);

            auto stateToString = [](core::CatalogManager::JobRunState state) -> std::string {
                switch (state)
                {
                    case core::CatalogManager::JobRunState::PENDING: return "PENDING";
                    case core::CatalogManager::JobRunState::RUNNING: return "RUNNING";
                    case core::CatalogManager::JobRunState::COMPLETED: return "COMPLETED";
                    case core::CatalogManager::JobRunState::FAILED: return "FAILED";
                    case core::CatalogManager::JobRunState::CANCELLED: return "CANCELLED";
                    default: return "UNKNOWN";
                }
            };

            for (const auto& run : runs)
            {
                Value scheduled = run.scheduled_time ? Value::makeTimestamp(static_cast<int64_t>(run.scheduled_time) * 1000)
                                                    : Value::makeNull(core::DataType::TIMESTAMP);
                Value started = run.started_at ? Value::makeTimestamp(static_cast<int64_t>(run.started_at) * 1000)
                                              : Value::makeNull(core::DataType::TIMESTAMP);
                Value completed = run.completed_at ? Value::makeTimestamp(static_cast<int64_t>(run.completed_at) * 1000)
                                                  : Value::makeNull(core::DataType::TIMESTAMP);

                current_result_set_->addRow({
                    Value::makeVarchar(run.job_run_id.toString()),
                    Value::makeVarchar(stateToString(run.state)),
                    scheduled,
                    started,
                    completed,
                    Value::makeInt32(static_cast<int32_t>(run.retry_count)),
                    Value::makeInt64(run.rows_affected),
                    Value::makeInt32(run.error_code),
                    Value::makeVarchar(run.result_message)
                });
            }
        }

        void Executor::executeShowChecks()
        {
            // Read bytecode parameters
            std::string object_name = readString();

            // Create result set - list check constraints for table
            if (!current_result_set_)
            {
                current_result_set_ = std::make_unique<ResultSet>();
            }

            current_result_set_->addColumn("Constraint Name", core::DataType::VARCHAR);
            current_result_set_->addColumn("Table", core::DataType::VARCHAR);
            current_result_set_->addColumn("Check Clause", core::DataType::VARCHAR);

            auto* catalog = db_->catalog_manager();
            if (!catalog)
            {
                error("Catalog manager not available");
            }

            core::ErrorContext err_ctx;

            auto add_check_row = [&](const core::CatalogManager::ConstraintInfo& constraint,
                                     const std::string& table_label,
                                     bool redact_details) {
                std::string clause = constraint.check_expression;
                if (clause.empty())
                {
                    clause = redact_details ? "Redacted" : "N/A";
                }
                if (redact_details)
                {
                    clause = "Redacted";
                }
                std::string name = constraint.constraint_name.empty() ? "<unnamed>"
                                                                      : constraint.constraint_name;
                current_result_set_->addRow({
                    Value::makeVarchar(name),
                    Value::makeVarchar(table_label),
                    Value::makeVarchar(clause)
                });
            };

            if (!object_name.empty())
            {
                core::ID table_id;
                core::CatalogManager::ObjectType resolved_type;
                auto schema_status = resolveObjectIdForQualifiedName(
                    object_name, core::CatalogManager::ObjectType::TABLE,
                    table_id, resolved_type, nullptr, &err_ctx);
                if (schema_status != core::Status::OK)
                {
                    error("Table '" + object_name + "' not found");
                }

                core::CatalogManager::TableInfo table_info;
                if (catalog->getTable(table_id, table_info, &err_ctx) != core::Status::OK)
                {
                    error("Table '" + object_name + "' not found");
                }

                std::vector<core::CatalogManager::ConstraintInfo> constraints;
                auto status = catalog->getConstraintsByType(
                    table_info.table_id,
                    core::CatalogManager::ConstraintType::CHECK,
                    constraints,
                    &err_ctx);
                if (status != core::Status::OK)
                {
                    error("Failed to load check constraints");
                }

                std::string schema_path;
                if (catalog->getSchemaPath(table_info.schema_id, schema_path, &err_ctx) != core::Status::OK)
                {
                    schema_path.clear();
                }
                std::string table_label = schema_path.empty()
                    ? table_info.table_name
                    : schema_path + "." + table_info.table_name;

                bool redact_details = shouldRedactMetadata(
                    table_info.table_id,
                    core::CatalogManager::PermissionObjectType::TABLE,
                    table_info.owner_id,
                    static_cast<uint32_t>(core::CatalogManager::Privilege::ALL));

                for (const auto& constraint : constraints)
                {
                    add_check_row(constraint, table_label, redact_details);
                }
                return;
            }

            std::vector<core::CatalogManager::SchemaInfo> schemas;
            if (catalog->listSchemas(schemas, &err_ctx) != core::Status::OK)
            {
                return;
            }

            std::vector<std::string> normalized_paths;
            if (conn_ctx_)
            {
                for (const auto& entry : conn_ctx_->search_path())
                {
                    std::string normalized = scratchbird::core::IdentifierUtils::toUpper(
                        normalizeSchemaPath(entry));
                    if (!normalized.empty())
                    {
                        normalized_paths.push_back(normalized);
                    }
                }
            }

            auto schema_visible = [&](const std::string& schema_path) {
                if (normalized_paths.empty())
                {
                    return true;
                }
                if (schema_path.empty())
                {
                    return true;
                }
                std::string normalized_schema = scratchbird::core::IdentifierUtils::toUpper(
                    normalizeSchemaPath(schema_path));
                for (const auto& entry : normalized_paths)
                {
                    if (normalized_schema == entry ||
                        normalized_schema.rfind(entry + ".", 0) == 0)
                    {
                        return true;
                    }
                }
                return false;
            };

            for (const auto& schema : schemas)
            {
                std::string schema_path;
                if (catalog->getSchemaPath(schema.schema_id, schema_path, &err_ctx) != core::Status::OK)
                {
                    schema_path = schema.schema_name;
                }
                if (!schema_visible(schema_path))
                {
                    continue;
                }

                std::vector<core::CatalogManager::TableInfo> tables;
                if (catalog->listTables(schema.schema_id, tables, &err_ctx) != core::Status::OK)
                {
                    continue;
                }

                for (const auto& table : tables)
                {
                    bool redact_details = shouldRedactMetadata(
                        table.table_id,
                        core::CatalogManager::PermissionObjectType::TABLE,
                        table.owner_id,
                        static_cast<uint32_t>(core::CatalogManager::Privilege::ALL));
                    if (redact_details)
                    {
                        continue;
                    }

                    std::vector<core::CatalogManager::ConstraintInfo> constraints;
                    auto status = catalog->getConstraintsByType(
                        table.table_id,
                        core::CatalogManager::ConstraintType::CHECK,
                        constraints,
                        &err_ctx);
                    if (status != core::Status::OK || constraints.empty())
                    {
                        continue;
                    }

                    std::string table_label = schema_path.empty()
                        ? table.table_name
                        : schema_path + "." + table.table_name;

                    for (const auto& constraint : constraints)
                    {
                        add_check_row(constraint, table_label, false);
                    }
                }
            }
        }

        void Executor::executeShowCollations()
        {
            // Read bytecode parameters
            std::string like_pattern = readString();

            // Create result set - list available collations
            if (!current_result_set_)
            {
                current_result_set_ = std::make_unique<ResultSet>();
            }

            current_result_set_->addColumn("Collation", core::DataType::VARCHAR);
            current_result_set_->addColumn("Character Set", core::DataType::VARCHAR);

            // Add known collations
            std::vector<std::pair<std::string, std::string>> collations = {
                {"UTF8_UNICODE", "UTF8"},
                {"UTF8_UNICODE_CI", "UTF8"},
                {"ASCII", "ASCII"},
                {"UTF8_BINARY", "UTF8"},
                {"ISO8859_1", "ISO8859_1"},
                {"NONE", "NONE"}
            };

            for (const auto& coll : collations)
            {
                if (like_pattern.empty() || matchSqlLike(coll.first, like_pattern))
                {
                    current_result_set_->addRow({
                        Value::makeVarchar(coll.first),
                        Value::makeVarchar(coll.second)
                    });
                }
            }
        }

        void Executor::executeShowComments()
        {
            // Read bytecode parameters
            std::string object_name = readString();

            if (!current_result_set_)
            {
                current_result_set_ = std::make_unique<ResultSet>();
            }

            current_result_set_->addColumn("Object", core::DataType::VARCHAR);
            current_result_set_->addColumn("Comment", core::DataType::VARCHAR);

            auto* catalog = db_->catalog_manager();
            core::ErrorContext err_ctx;
            auto should_redact_comment = [&](const core::ID& object_id,
                                             core::CatalogManager::ObjectType object_type,
                                             const core::ID& owner_id) -> bool {
                const auto spec = getMetadataVisibilitySpec(object_type);
                if (spec.supported)
                {
                    core::ID resolved_owner = owner_id;
                    if (resolved_owner == core::ID{})
                    {
                        switch (object_type)
                        {
                            case core::CatalogManager::ObjectType::SCHEMA:
                            {
                                core::CatalogManager::SchemaInfo info;
                                if (catalog->getSchema(object_id, info, &err_ctx) == core::Status::OK)
                                {
                                    resolved_owner = info.owner_id;
                                }
                                break;
                            }
                            case core::CatalogManager::ObjectType::TABLE:
                            {
                                core::CatalogManager::TableInfo info;
                                if (catalog->getTable(object_id, info, &err_ctx) == core::Status::OK)
                                {
                                    resolved_owner = info.owner_id;
                                }
                                break;
                            }
                            case core::CatalogManager::ObjectType::VIEW:
                            {
                                core::CatalogManager::ViewInfo info;
                                if (catalog->getViewById(object_id, info, &err_ctx) == core::Status::OK)
                                {
                                    resolved_owner = info.owner_id;
                                }
                                break;
                            }
                            case core::CatalogManager::ObjectType::SEQUENCE:
                            {
                                core::CatalogManager::SequenceInfo info;
                                if (catalog->getSequenceById(object_id, info, &err_ctx) == core::Status::OK)
                                {
                                    resolved_owner = info.owner_id;
                                }
                                break;
                            }
                            default:
                                break;
                        }
                    }
                    return shouldRedactMetadata(object_id, spec.perm_type, resolved_owner, spec.privilege);
                }
                return shouldRedactMetadata(object_id,
                                            core::CatalogManager::PermissionObjectType::TABLE,
                                            owner_id,
                                            0);
            };

            auto resolve_object = [&](const std::string& name,
                                      core::ID& object_id_out,
                                      core::CatalogManager::ObjectType& type_out) -> core::Status {
                object_id_out = core::ID{};
                type_out = core::CatalogManager::ObjectType::UNKNOWN;
                const std::array<core::CatalogManager::ObjectType, 8> candidates = {
                    core::CatalogManager::ObjectType::TABLE,
                    core::CatalogManager::ObjectType::VIEW,
                    core::CatalogManager::ObjectType::SEQUENCE,
                    core::CatalogManager::ObjectType::FUNCTION,
                    core::CatalogManager::ObjectType::PROCEDURE,
                    core::CatalogManager::ObjectType::PACKAGE,
                    core::CatalogManager::ObjectType::TRIGGER,
                    core::CatalogManager::ObjectType::SCHEMA
                };

                int matches = 0;
                core::ID found_id{};
                core::CatalogManager::ObjectType found_type = core::CatalogManager::ObjectType::UNKNOWN;

                for (auto candidate : candidates)
                {
                    core::ID candidate_id;
                    core::CatalogManager::ObjectType resolved_type;
                    core::ErrorContext type_ctx;
                    auto status = resolveObjectIdForQualifiedName(
                        name, candidate, candidate_id, resolved_type, nullptr, &type_ctx);
                    if (status == core::Status::OK)
                    {
                        if (matches == 0)
                        {
                            found_id = candidate_id;
                            found_type = candidate;
                        }
                        ++matches;
                        continue;
                    }
                    if (status == core::Status::AMBIGUOUS_COLUMN)
                    {
                        SET_ERROR_CONTEXT(&err_ctx, status, "Ambiguous object name");
                        return status;
                    }
                }

                if (matches == 0)
                {
                    core::ObjectPath path;
                    auto path_status = buildObjectPathFromName(name, path, &err_ctx);
                    if (path_status != core::Status::OK)
                    {
                        return path_status;
                    }
                    if (path.type == core::PathType::UNQUALIFIED && path.components.size() == 1)
                    {
                        core::CatalogManager::DatabaseTriggerInfo db_trig_info;
                        if (catalog->getDatabaseTriggerByName(name, db_trig_info, &err_ctx) == core::Status::OK)
                        {
                            object_id_out = db_trig_info.trigger_id;
                            type_out = core::CatalogManager::ObjectType::TRIGGER;
                            return core::Status::OK;
                        }
                    }

                    SET_ERROR_CONTEXT(&err_ctx, core::Status::NOT_FOUND, "Object not found");
                    return core::Status::NOT_FOUND;
                }
                if (matches > 1)
                {
                    SET_ERROR_CONTEXT(&err_ctx, core::Status::AMBIGUOUS_COLUMN, "Ambiguous object name");
                    return core::Status::AMBIGUOUS_COLUMN;
                }

                object_id_out = found_id;
                type_out = found_type;
                return core::Status::OK;
            };

            if (object_name.empty())
            {
                std::vector<core::CatalogManager::CommentInfo> comments;
                auto status = catalog->listComments(comments, &err_ctx);
                if (status != core::Status::OK)
                {
                    error("Failed to list comments");
                }

                for (const auto& comment : comments)
                {
                    if (should_redact_comment(comment.object_id, comment.object_type, comment.owner_id))
                    {
                        continue;
                    }
                    std::string object_label = comment.object_id.toString();
                    core::CatalogManager::ResolvedObject resolved;
                    if (catalog->resolveObjectId(comment.object_id, resolved, &err_ctx) == core::Status::OK &&
                        !resolved.full_path.empty())
                    {
                        object_label = resolved.full_path;
                    }
                    current_result_set_->addRow({
                        Value::makeVarchar(object_label),
                        Value::makeVarchar(comment.comment_text)
                    });
                }

                return;
            }

            core::ID object_id;
            core::CatalogManager::ObjectType object_type;
            auto status = resolve_object(object_name, object_id, object_type);
            if (status != core::Status::OK)
            {
                std::string msg = "Object '" + object_name + "' not found";
                if (!err_ctx.message.empty())
                {
                    msg += ": " + err_ctx.message;
                }
                error(msg);
            }

            std::string comment;
            if (catalog->getComment(object_id, comment, &err_ctx) != core::Status::OK)
            {
                comment = "(no comments)";
            }

            std::string object_label = object_name;
            core::CatalogManager::ResolvedObject resolved;
            if (catalog->resolveObjectId(object_id, resolved, &err_ctx) == core::Status::OK &&
                !resolved.full_path.empty())
            {
                object_label = resolved.full_path;
            }

            if (should_redact_comment(object_id, object_type, core::ID{}))
            {
                comment = "Redacted";
            }

            current_result_set_->addRow({
                Value::makeVarchar(object_label),
                Value::makeVarchar(comment)
            });
        }

        void Executor::executeShowDependencies()
        {
            // Read bytecode parameters
            std::string object_name = readString();

            if (!current_result_set_)
            {
                current_result_set_ = std::make_unique<ResultSet>();
            }

            current_result_set_->addColumn("Dependent Object", core::DataType::VARCHAR);
            current_result_set_->addColumn("Depends On", core::DataType::VARCHAR);
            current_result_set_->addColumn("Dependency Type", core::DataType::VARCHAR);

            auto* catalog = db_->catalog_manager();
            core::ErrorContext err_ctx;

            auto resolve_object = [&](const std::string& name,
                                      core::ID& object_id_out,
                                      core::CatalogManager::ObjectType& type_out) -> core::Status {
                object_id_out = core::ID{};
                type_out = core::CatalogManager::ObjectType::UNKNOWN;
                const std::array<core::CatalogManager::ObjectType, 8> candidates = {
                    core::CatalogManager::ObjectType::TABLE,
                    core::CatalogManager::ObjectType::VIEW,
                    core::CatalogManager::ObjectType::SEQUENCE,
                    core::CatalogManager::ObjectType::FUNCTION,
                    core::CatalogManager::ObjectType::PROCEDURE,
                    core::CatalogManager::ObjectType::PACKAGE,
                    core::CatalogManager::ObjectType::TRIGGER,
                    core::CatalogManager::ObjectType::SCHEMA
                };

                int matches = 0;
                core::ID found_id{};
                core::CatalogManager::ObjectType found_type = core::CatalogManager::ObjectType::UNKNOWN;

                for (auto candidate : candidates)
                {
                    core::ID candidate_id;
                    core::CatalogManager::ObjectType resolved_type;
                    core::ErrorContext type_ctx;
                    auto status = resolveObjectIdForQualifiedName(
                        name, candidate, candidate_id, resolved_type, nullptr, &type_ctx);
                    if (status == core::Status::OK)
                    {
                        if (matches == 0)
                        {
                            found_id = candidate_id;
                            found_type = candidate;
                        }
                        ++matches;
                        continue;
                    }
                    if (status == core::Status::AMBIGUOUS_COLUMN)
                    {
                        SET_ERROR_CONTEXT(&err_ctx, status, "Ambiguous object name");
                        return status;
                    }
                }

                if (matches == 0)
                {
                    core::ObjectPath path;
                    auto path_status = buildObjectPathFromName(name, path, &err_ctx);
                    if (path_status != core::Status::OK)
                    {
                        return path_status;
                    }
                    if (path.type == core::PathType::UNQUALIFIED && path.components.size() == 1)
                    {
                        core::CatalogManager::DatabaseTriggerInfo db_trig_info;
                        if (catalog->getDatabaseTriggerByName(name, db_trig_info, &err_ctx) == core::Status::OK)
                        {
                            object_id_out = db_trig_info.trigger_id;
                            type_out = core::CatalogManager::ObjectType::TRIGGER;
                            return core::Status::OK;
                        }
                    }

                    SET_ERROR_CONTEXT(&err_ctx, core::Status::NOT_FOUND, "Object not found");
                    return core::Status::NOT_FOUND;
                }
                if (matches > 1)
                {
                    SET_ERROR_CONTEXT(&err_ctx, core::Status::AMBIGUOUS_COLUMN, "Ambiguous object name");
                    return core::Status::AMBIGUOUS_COLUMN;
                }

                object_id_out = found_id;
                type_out = found_type;
                return core::Status::OK;
            };

            auto resolve_label = [&](const core::ID& id) -> std::string {
                core::CatalogManager::ResolvedObject resolved;
                if (catalog->resolveObjectId(id, resolved, &err_ctx) == core::Status::OK &&
                    !resolved.full_path.empty())
                {
                    return resolved.full_path;
                }
                return id.toString();
            };

            auto dependencyTypeToString = [](core::CatalogManager::DependencyType type) -> std::string {
                switch (type)
                {
                    case core::CatalogManager::DependencyType::NORMAL: return "NORMAL";
                    case core::CatalogManager::DependencyType::AUTO: return "AUTO";
                    case core::CatalogManager::DependencyType::INTERNAL: return "INTERNAL";
                    case core::CatalogManager::DependencyType::PIN: return "PIN";
                    default: return "UNKNOWN";
                }
            };

            auto should_redact_object = [&](const core::ID& object_id,
                                            core::CatalogManager::ObjectType object_type) -> bool {
                const auto spec = getMetadataVisibilitySpec(object_type);
                if (spec.supported)
                {
                    core::ID owner_id{};
                    switch (object_type)
                    {
                        case core::CatalogManager::ObjectType::SCHEMA:
                        {
                            core::CatalogManager::SchemaInfo info;
                            if (catalog->getSchema(object_id, info, &err_ctx) == core::Status::OK)
                            {
                                owner_id = info.owner_id;
                            }
                            break;
                        }
                        case core::CatalogManager::ObjectType::TABLE:
                        {
                            core::CatalogManager::TableInfo info;
                            if (catalog->getTable(object_id, info, &err_ctx) == core::Status::OK)
                            {
                                owner_id = info.owner_id;
                            }
                            break;
                        }
                        case core::CatalogManager::ObjectType::VIEW:
                        {
                            core::CatalogManager::ViewInfo info;
                            if (catalog->getViewById(object_id, info, &err_ctx) == core::Status::OK)
                            {
                                owner_id = info.owner_id;
                            }
                            break;
                        }
                        case core::CatalogManager::ObjectType::SEQUENCE:
                        {
                            core::CatalogManager::SequenceInfo info;
                            if (catalog->getSequenceById(object_id, info, &err_ctx) == core::Status::OK)
                            {
                                owner_id = info.owner_id;
                            }
                            break;
                        }
                        default:
                            break;
                    }
                    return shouldRedactMetadata(object_id, spec.perm_type, owner_id, spec.privilege);
                }

                core::CatalogManager::ResolvedObject resolved;
                if (catalog->resolveObjectId(object_id, resolved, &err_ctx) == core::Status::OK &&
                    resolved.parent_object_id != core::ID{})
                {
                    core::CatalogManager::TableInfo table_info;
                    if (catalog->getTable(resolved.parent_object_id, table_info, &err_ctx) == core::Status::OK)
                    {
                        return shouldRedactMetadata(
                            table_info.table_id,
                            core::CatalogManager::PermissionObjectType::TABLE,
                            table_info.owner_id,
                            static_cast<uint32_t>(core::CatalogManager::Privilege::SELECT));
                    }
                }

                return true;
            };

            std::vector<core::CatalogManager::DependencyInfo> deps;
            if (object_name.empty())
            {
                auto status = catalog->listDependencies(deps, &err_ctx);
                if (status != core::Status::OK)
                {
                    error("Failed to list dependencies");
                }
            }
            else
            {
                core::ID object_id;
                core::CatalogManager::ObjectType object_type;
                auto status = resolve_object(object_name, object_id, object_type);
                if (status != core::Status::OK)
                {
                    std::string msg = "Object '" + object_name + "' not found";
                    if (!err_ctx.message.empty())
                    {
                        msg += ": " + err_ctx.message;
                    }
                    error(msg);
                }

                status = catalog->getDependenciesFor(object_id, deps, &err_ctx);
                if (status != core::Status::OK)
                {
                    error("Failed to get dependencies");
                }

                if (should_redact_object(object_id, object_type))
                {
                    current_result_set_->addRow({
                        Value::makeVarchar("Redacted"),
                        Value::makeVarchar("Redacted"),
                        Value::makeVarchar("Redacted")
                    });
                    return;
                }
            }

            for (const auto& dep : deps)
            {
                if (should_redact_object(dep.dependent_object_id, dep.dependent_type) ||
                    should_redact_object(dep.referenced_object_id, dep.referenced_type))
                {
                    continue;
                }
                current_result_set_->addRow({
                    Value::makeVarchar(resolve_label(dep.dependent_object_id)),
                    Value::makeVarchar(resolve_label(dep.referenced_object_id)),
                    Value::makeVarchar(dependencyTypeToString(dep.dependency_type))
                });
            }
        }

        void Executor::executeShowPackage()
        {
            // Read bytecode parameters
            std::string object_name = readString();

            if (object_name.empty())
            {
                error("Package name required");
            }

            auto* catalog = db_->catalog_manager();
            core::ErrorContext err_ctx;
            core::ID package_id;
            core::CatalogManager::ObjectType resolved_type;
            auto schema_status = resolveObjectIdForQualifiedName(
                object_name, core::CatalogManager::ObjectType::PACKAGE,
                package_id, resolved_type, nullptr, &err_ctx);
            if (schema_status != core::Status::OK)
            {
                error("Package '" + object_name + "' not found");
            }

            core::CatalogManager::PackageInfo pkg_info;
            auto status = catalog->getPackage(package_id, pkg_info, &err_ctx);
            if (status != core::Status::OK)
            {
                error("Package '" + object_name + "' not found");
            }

            if (!current_result_set_)
            {
                current_result_set_ = std::make_unique<ResultSet>();
            }

            current_result_set_->addColumn("Property", core::DataType::VARCHAR);
            current_result_set_->addColumn("Value", core::DataType::VARCHAR);

            std::string schema_path;
            if (catalog->getSchemaPath(pkg_info.schema_id, schema_path, &err_ctx) != core::Status::OK)
            {
                schema_path.clear();
            }

            current_result_set_->addRow({Value::makeVarchar("Package Name"),
                                         Value::makeVarchar(pkg_info.package_name)});
            if (!schema_path.empty())
            {
                current_result_set_->addRow({Value::makeVarchar("Schema"),
                                             Value::makeVarchar(schema_path)});
            }

            bool redact_package = shouldRedactMetadata(
                pkg_info.package_id,
                core::CatalogManager::PermissionObjectType::PROCEDURE,
                pkg_info.owner_id,
                static_cast<uint32_t>(core::CatalogManager::Privilege::EXECUTE));
            std::string header = (redact_package || pkg_info.package_header.empty())
                ? "Redacted"
                : pkg_info.package_header;
            std::string body = (redact_package || pkg_info.package_body.empty())
                ? "Redacted"
                : pkg_info.package_body;
            current_result_set_->addRow({Value::makeVarchar("Header"),
                                         Value::makeVarchar(header)});
            current_result_set_->addRow({Value::makeVarchar("Body"),
                                         Value::makeVarchar(body)});

            std::string comment;
            if (catalog->getComment(pkg_info.package_id, comment, &err_ctx) == core::Status::OK)
            {
                current_result_set_->addRow({Value::makeVarchar("Comment"),
                                             Value::makeVarchar(comment)});
            }
        }

        void Executor::executeShowSystem()
        {
            // Show system information
            if (!current_result_set_)
            {
                current_result_set_ = std::make_unique<ResultSet>();
            }

            current_result_set_->addColumn("Property", core::DataType::VARCHAR);
            current_result_set_->addColumn("Value", core::DataType::VARCHAR);

            current_result_set_->addRow({Value::makeVarchar("Database Engine"), Value::makeVarchar("ScratchBird")});
            current_result_set_->addRow({Value::makeVarchar("Server Version"), Value::makeVarchar("1.0.0-alpha")});
            current_result_set_->addRow({Value::makeVarchar("Protocol"), Value::makeVarchar("SBCP 1.0")});
            current_result_set_->addRow({Value::makeVarchar("Page Size"), Value::makeVarchar(std::to_string(db_->page_size()))});
            current_result_set_->addRow({Value::makeVarchar("Architecture"), Value::makeVarchar("Firebird MGA")});
        }

        void Executor::executeShowMetrics()
        {
            if (!current_result_set_)
            {
                current_result_set_ = std::make_unique<ResultSet>();
            }

            current_result_set_->addColumn("MetricName", core::DataType::VARCHAR);
            current_result_set_->addColumn("Labels", core::DataType::VARCHAR);
            current_result_set_->addColumn("Value", core::DataType::VARCHAR);

            auto& metrics = core::ScratchBirdMetrics::getInstance();
            metrics.initialize();

            const auto rows = core::MetricsRegistry::getInstance().snapshotSamples();
            for (const auto& row : rows)
            {
                std::string labels;
                for (size_t i = 0; i < row.labels.size(); ++i)
                {
                    if (i > 0)
                    {
                        labels += ", ";
                    }
                    labels += row.labels[i].name;
                    labels += "=";
                    labels += row.labels[i].value;
                }

                std::ostringstream value_stream;
                value_stream << std::fixed << std::setprecision(6) << row.value;
                current_result_set_->addRow({Value::makeVarchar(row.metric_name),
                                             Value::makeVarchar(labels),
                                             Value::makeVarchar(value_stream.str())});
            }
        }

        void Executor::executeShowSqlDialect()
        {
            // Show current SQL dialect (Firebird compatibility)
            if (!current_result_set_)
            {
                current_result_set_ = std::make_unique<ResultSet>();
            }

            current_result_set_->addColumn("SQL Dialect", core::DataType::INT32);

            // Default to dialect 3 (modern SQL)
            int dialect = 3;
            if (conn_ctx_)
            {
                dialect = conn_ctx_->sql_dialect();
            }
            current_result_set_->addRow({Value::makeInt32(dialect)});
        }

