        // ========================================================================
        // XML HELPER FUNCTIONS (Nov 14, 2025)
        // ========================================================================

#ifdef HAVE_LIBXML2
        // Helper: Convert xmlChar* to std::string
        static std::string xmlCharToString(const xmlChar* xmlStr)
        {
            if (!xmlStr) return "";
            return std::string(reinterpret_cast<const char*>(xmlStr));
        }

        // Helper: Convert xmlDocPtr to string representation
        static std::string xmlDocToString(xmlDocPtr doc)
        {
            if (!doc) return "";

            xmlChar* xmlbuff;
            int buffersize;
            xmlDocDumpFormatMemory(doc, &xmlbuff, &buffersize, 1);

            std::string result(reinterpret_cast<char*>(xmlbuff), buffersize);
            xmlFree(xmlbuff);

            return result;
        }

        // Helper: Get last XML error message
        static std::string getLastXMLError()
        {
            const xmlError* err = xmlGetLastError();
            if (err) {
                return std::string(err->message);
            }
            return "Unknown XML error";
        }

        // Helper: Initialize libxml2 (call once)
        static void initLibXML2()
        {
            static bool initialized = false;
            if (!initialized) {
                xmlInitParser();
                initialized = true;
            }
        }

        // Helper: Cleanup libxml2 (call at shutdown)
        static void cleanupLibXML2()
        {
            xmlCleanupParser();
        }
#endif

        // ========================================================================
        // XML FUNCTIONS (Nov 14, 2025)
        // ========================================================================

        void Executor::executeXMLParse()
        {
#ifdef HAVE_LIBXML2
            // Initialize libxml2
            initLibXML2();

            // XMLPARSE(DOCUMENT|CONTENT, xml_text)
            // Pop xml_text from stack
            Value xml_text = stack_.top(); stack_.pop();

            // Pop document_or_content flag (ignored for now)
            Value mode = stack_.top(); stack_.pop();

            if (xml_text.isNull())
            {
                stack_.push(Value::makeNull());
                return;
            }

            std::string xml_str = xml_text.toString();

            // Parse XML with full validation using libxml2
            xmlDocPtr doc = xmlReadMemory(
                xml_str.c_str(),
                xml_str.length(),
                nullptr,
                nullptr,
                XML_PARSE_NONET | XML_PARSE_NOENT
            );

            if (!doc)
            {
                std::string err_msg = getLastXMLError();
                xmlResetLastError();
                // SECURITY FIX (HIGH-1): Log detailed error internally, return generic error to client
                LOG_ERROR(EXECUTOR, "Invalid XML: %s", err_msg.c_str());
                error("Invalid XML");
            }

            // Convert back to string (validates and normalizes)
            std::string result = xmlDocToString(doc);
            xmlFreeDoc(doc);

            stack_.push(Value::makeVarchar(result));
#else
            // Fallback: basic string-based implementation without libxml2
            Value xml_text = stack_.top(); stack_.pop();
            Value mode = stack_.top(); stack_.pop();

            if (xml_text.isNull())
            {
                stack_.push(Value::makeNull());
                return;
            }

            std::string xml_str = xml_text.toString();

            // Basic XML validation - check if it looks like XML
            if (xml_str.empty() || xml_str.find('<') == std::string::npos)
            {
                error("Invalid XML: must contain at least one element");
            }

            // Return the XML as a string
            stack_.push(Value::makeVarchar(xml_str));
#endif
        }

        void Executor::executeXMLSerialize()
        {
            // XMLSERIALIZE(CONTENT|DOCUMENT xml AS type)
            // Pop type (e.g., VARCHAR)
            Value type = stack_.top(); stack_.pop();

            // Pop XML value
            Value xml = stack_.top(); stack_.pop();

            // Pop mode (CONTENT or DOCUMENT)
            Value mode = stack_.top(); stack_.pop();

            if (xml.isNull())
            {
                stack_.push(Value::makeNull());
                return;
            }

            // Convert XML to string
            std::string xml_str = xml.toString();

            // Return as VARCHAR
            stack_.push(Value::makeVarchar(xml_str));
        }

        void Executor::executeXMLElement()
        {
            // XMLELEMENT(NAME element_name [, attributes] [, content])
            // For simplicity: XMLELEMENT(NAME name, content)

            // Pop content
            Value content = stack_.top(); stack_.pop();

            // Pop element name
            Value name = stack_.top(); stack_.pop();

            if (name.isNull())
            {
                error("XML element name cannot be NULL");
            }

            std::string element_name = name.toString();
            std::string element_content = content.isNull() ? "" : content.toString();

            // Build XML element
            std::string xml = "<" + element_name + ">" + element_content + "</" + element_name + ">";

            stack_.push(Value::makeVarchar(xml));
        }

        void Executor::executeXMLConcat()
        {
            // XMLCONCAT(xml1, xml2, ...)
            // Number of arguments is on the stack
            uint8_t arg_count = readByte();

            std::vector<std::string> xml_parts;

            for (uint8_t i = 0; i < arg_count; i++)
            {
                Value xml_val = stack_.top(); stack_.pop();
                if (!xml_val.isNull())
                {
                    xml_parts.push_back(xml_val.toString());
                }
            }

            // Concatenate all XML parts
            std::string result;
            for (auto it = xml_parts.rbegin(); it != xml_parts.rend(); ++it)
            {
                result += *it;
            }

            stack_.push(Value::makeVarchar(result));
        }

        void Executor::executeXMLForest()
        {
            // XMLFOREST(expr1 AS name1, expr2 AS name2, ...)
            // Creates: <name1>expr1</name1><name2>expr2</name2>...

            uint8_t arg_count = readByte();

            std::vector<std::pair<std::string, std::string>> elements;

            for (uint8_t i = 0; i < arg_count; i++)
            {
                // Pop name
                Value name = stack_.top(); stack_.pop();
                // Pop value
                Value value = stack_.top(); stack_.pop();

                if (!value.isNull() && !name.isNull())
                {
                    elements.push_back({name.toString(), value.toString()});
                }
            }

            // Build XML forest
            std::string result;
            for (auto it = elements.rbegin(); it != elements.rend(); ++it)
            {
                result += "<" + it->first + ">" + it->second + "</" + it->first + ">";
            }

            stack_.push(Value::makeVarchar(result));
        }

        void Executor::executeXMLComment()
        {
            // XMLCOMMENT(text)
            Value text = stack_.top(); stack_.pop();

            if (text.isNull())
            {
                stack_.push(Value::makeNull());
                return;
            }

            std::string comment_text = text.toString();

            // Check for invalid comment content (-- is not allowed in XML comments)
            if (comment_text.find("--") != std::string::npos)
            {
                error("XML comment cannot contain '--'");
            }

            std::string xml = "<!--" + comment_text + "-->";
            stack_.push(Value::makeVarchar(xml));
        }

        void Executor::executeXMLRoot()
        {
            // XMLROOT(xml, VERSION version [, STANDALONE yes|no])
            // Simplified: XMLROOT(xml, version, standalone)

            // Pop standalone flag (yes=1, no=0, omitted=-1)
            Value standalone = stack_.top(); stack_.pop();

            // Pop version
            Value version = stack_.top(); stack_.pop();

            // Pop XML content
            Value xml = stack_.top(); stack_.pop();

            if (xml.isNull())
            {
                stack_.push(Value::makeNull());
                return;
            }

            std::string xml_content = xml.toString();
            std::string version_str = version.isNull() ? "1.0" : version.toString();

            // Build XML declaration
            std::string declaration = "<?xml version=\"" + version_str + "\"";

            if (!standalone.isNull())
            {
                int standalone_val = static_cast<int>(standalone.toInt64());
                if (standalone_val == 1)
                {
                    declaration += " standalone=\"yes\"";
                }
                else if (standalone_val == 0)
                {
                    declaration += " standalone=\"no\"";
                }
            }

            declaration += "?>";

            std::string result = declaration + xml_content;
            stack_.push(Value::makeVarchar(result));
        }

        void Executor::executeXPath()
        {
            // XPATH(xpath_expr, xml)
            Value xml = stack_.top(); stack_.pop();
            Value xpath_expr = stack_.top(); stack_.pop();

            if (xml.isNull() || xpath_expr.isNull())
            {
                stack_.push(Value::makeNull());
                return;
            }

#ifdef HAVE_LIBXML2
            initLibXML2();

            std::string xml_str = xml.toString();
            std::string xpath = xpath_expr.toString();

            // Parse XML
            xmlDocPtr doc = xmlReadMemory(
                xml_str.c_str(),
                xml_str.length(),
                nullptr,
                nullptr,
                XML_PARSE_NONET | XML_PARSE_NOENT
            );

            if (!doc)
            {
                std::string err_msg = getLastXMLError();
                xmlResetLastError();
                error("Invalid XML in XPATH: " + err_msg);
            }

            // Create XPath context
            xmlXPathContextPtr xpathCtx = xmlXPathNewContext(doc);
            if (!xpathCtx)
            {
                xmlFreeDoc(doc);
                error("Failed to create XPath context");
            }

            // Evaluate XPath expression
            xmlXPathObjectPtr xpathObj = xmlXPathEvalExpression(
                reinterpret_cast<const xmlChar*>(xpath.c_str()),
                xpathCtx
            );

            if (!xpathObj)
            {
                xmlXPathFreeContext(xpathCtx);
                xmlFreeDoc(doc);
                error("Invalid XPath expression: " + xpath);
            }

            // Convert result to SQL array of strings
            std::vector<std::string> results;

            if (xpathObj->type == XPATH_NODESET && xpathObj->nodesetval)
            {
                xmlNodeSetPtr nodeset = xpathObj->nodesetval;
                for (int i = 0; i < nodeset->nodeNr; i++)
                {
                    xmlNodePtr node = nodeset->nodeTab[i];
                    xmlChar* content = xmlNodeGetContent(node);
                    if (content)
                    {
                        results.push_back(xmlCharToString(content));
                        xmlFree(content);
                    }
                }
            }

            // Cleanup
            xmlXPathFreeObject(xpathObj);
            xmlXPathFreeContext(xpathCtx);
            xmlFreeDoc(doc);

            // Build JSON array result
            json j_array = json::array();
            for (const auto& res : results)
            {
                j_array.push_back(res);
            }

            stack_.push(Value::makeVarchar(j_array.dump()));
#else
            error("XPATH requires libxml2 library - not available in this build");
#endif
        }

        void Executor::executeXMLExists()
        {
            // XMLEXISTS(xpath_expr, xml) - returns boolean
            Value xml = stack_.top(); stack_.pop();
            Value xpath_expr = stack_.top(); stack_.pop();

            if (xml.isNull() || xpath_expr.isNull())
            {
                stack_.push(Value::makeNull());
                return;
            }

#ifdef HAVE_LIBXML2
            initLibXML2();

            std::string xml_str = xml.toString();
            std::string xpath = xpath_expr.toString();

            // Parse XML
            xmlDocPtr doc = xmlReadMemory(
                xml_str.c_str(),
                xml_str.length(),
                nullptr,
                nullptr,
                XML_PARSE_NONET | XML_PARSE_NOENT
            );

            if (!doc)
            {
                std::string err_msg = getLastXMLError();
                xmlResetLastError();
                error("Invalid XML in XMLEXISTS: " + err_msg);
            }

            // Create XPath context
            xmlXPathContextPtr xpathCtx = xmlXPathNewContext(doc);
            if (!xpathCtx)
            {
                xmlFreeDoc(doc);
                error("Failed to create XPath context");
            }

            // Evaluate XPath expression
            xmlXPathObjectPtr xpathObj = xmlXPathEvalExpression(
                reinterpret_cast<const xmlChar*>(xpath.c_str()),
                xpathCtx
            );

            bool exists = false;

            if (xpathObj)
            {
                // Check if any nodes were found
                if (xpathObj->type == XPATH_NODESET && xpathObj->nodesetval)
                {
                    exists = (xpathObj->nodesetval->nodeNr > 0);
                }
                else if (xpathObj->type == XPATH_BOOLEAN)
                {
                    exists = xpathObj->boolval;
                }

                xmlXPathFreeObject(xpathObj);
            }

            // Cleanup
            xmlXPathFreeContext(xpathCtx);
            xmlFreeDoc(doc);

            stack_.push(Value::makeBoolean(exists));
#else
            error("XMLEXISTS requires libxml2 library - not available in this build");
#endif
        }

        void Executor::executeExtract()
        {
            // Spec: docs/specifications/EXTRACT_AND_ALTER_ELEMENT.md
            uint8_t field_id = readByte();
            uint8_t arg_count = readByte();
            ExtractField field = static_cast<ExtractField>(field_id);

            auto is_deterministic_extract_error = [](const std::string& message) {
                return message.rfind("EXTRACT_FIELD_UNKNOWN(", 0) == 0 ||
                       message.rfind("EXTRACT_FIELD_NOT_VALID_FOR_TYPE(", 0) == 0 ||
                       message.rfind("EXTRACT_FIELD_VALUE_CONSTRAINT_VIOLATION(", 0) == 0;
            };

            auto extract_data_type_name = [](core::DataType type) -> std::string {
                switch (type)
                {
                    case core::DataType::DATE: return "DATE";
                    case core::DataType::TIME: return "TIME";
                    case core::DataType::TIME_WITH_ZONE: return "TIME_WITH_ZONE";
                    case core::DataType::TIMESTAMP: return "TIMESTAMP";
                    case core::DataType::TIMESTAMP_WITH_ZONE: return "TIMESTAMP_WITH_ZONE";
                    case core::DataType::DATETIME: return "DATETIME";
                    case core::DataType::INTERVAL: return "INTERVAL";
                    case core::DataType::UUID: return "UUID";
                    case core::DataType::JSON: return "JSON";
                    case core::DataType::JSONB: return "JSONB";
                    case core::DataType::XML: return "XML";
                    case core::DataType::BYTEA: return "BYTEA";
                    case core::DataType::BINARY: return "BINARY";
                    case core::DataType::VARBINARY: return "VARBINARY";
                    case core::DataType::BLOB: return "BLOB";
                    case core::DataType::VECTOR: return "VECTOR";
                    case core::DataType::ARRAY: return "ARRAY";
                    case core::DataType::COMPOSITE: return "COMPOSITE";
                    case core::DataType::VARIANT: return "VARIANT";
                    case core::DataType::CHAR: return "CHAR";
                    case core::DataType::VARCHAR: return "VARCHAR";
                    case core::DataType::TEXT: return "TEXT";
                    case core::DataType::TSVECTOR: return "TSVECTOR";
                    case core::DataType::TSQUERY: return "TSQUERY";
                    case core::DataType::INET: return "INET";
                    case core::DataType::CIDR: return "CIDR";
                    case core::DataType::MACADDR: return "MACADDR";
                    case core::DataType::MACADDR8: return "MACADDR8";
                    case core::DataType::UNKNOWN: return "UNKNOWN";
                    case core::DataType::NULL_TYPE: return "NULL";
                    default:
                        break;
                }
                return "TYPE_" + std::to_string(static_cast<uint16_t>(type));
            };

            Value source = pop();

            std::vector<Value> args(arg_count);
            for (uint8_t i = 0; i < arg_count; ++i)
            {
                args[arg_count - 1 - i] = pop();
            }

            Value result;
            std::string err;
            if (!extractElement(source, field, args, &result, &err))
            {
                std::string failure = err.empty() ? "EXTRACT failed" : err;
                if (!is_deterministic_extract_error(failure))
                {
                    std::ostringstream oss;
                    oss << "EXTRACT_FIELD_VALUE_CONSTRAINT_VIOLATION("
                        << extractFieldToString(field)
                        << ", " << extract_data_type_name(source.type())
                        << ", " << failure << ")";
                    failure = oss.str();
                }
                error(failure);
                return;
            }
            push(result);
        }

        void Executor::executeAlterElement()
        {
            // Spec: docs/specifications/EXTRACT_AND_ALTER_ELEMENT.md
            uint8_t field_id = readByte();
            uint8_t arg_count = readByte();
            ExtractField field = static_cast<ExtractField>(field_id);

            Value new_value = pop();
            Value source = pop();

            std::vector<Value> args(arg_count);
            for (uint8_t i = 0; i < arg_count; ++i)
            {
                args[arg_count - 1 - i] = pop();
            }

            Value result;
            std::string err;
            if (!alterElement(source, field, args, new_value, &result, &err))
            {
                error(err.empty() ? "ALTER_ELEMENT failed" : err);
                return;
            }
            push(result);
        }

        void Executor::executeEncode()
        {
            // WP-4 EXEC-7: ENCODE(data bytea, format text) -> text
            Value format_val = stack_.top(); stack_.pop();
            Value data_val = stack_.top(); stack_.pop();

            if (data_val.isNull() || format_val.isNull())
            {
                stack_.push(Value::makeNull());
                return;
            }

            std::string format = format_val.toString();
            std::transform(format.begin(), format.end(), format.begin(), ::tolower);

            // Get data as bytes
            std::vector<uint8_t> data;
            if (data_val.type() == core::DataType::BYTEA || data_val.type() == core::DataType::BLOB ||
                data_val.type() == core::DataType::BINARY || data_val.type() == core::DataType::VARBINARY)
            {
                data = data_val.getUUID();  // getUUID() returns binary_data_ for binary types
            }
            else
            {
                // Treat string as raw bytes
                std::string str = data_val.toString();
                data.assign(str.begin(), str.end());
            }

            std::string result;
            if (format == "hex")
            {
                // Hex encoding
                static const char hex_chars[] = "0123456789abcdef";
                result.reserve(data.size() * 2);
                for (uint8_t byte : data)
                {
                    result.push_back(hex_chars[(byte >> 4) & 0x0F]);
                    result.push_back(hex_chars[byte & 0x0F]);
                }
            }
            else if (format == "base64")
            {
                // Base64 encoding
                static const char base64_chars[] =
                    "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
                result.reserve(((data.size() + 2) / 3) * 4);

                size_t i = 0;
                while (i + 2 < data.size())
                {
                    uint32_t val = (static_cast<uint32_t>(data[i]) << 16) |
                                   (static_cast<uint32_t>(data[i + 1]) << 8) |
                                   static_cast<uint32_t>(data[i + 2]);
                    result.push_back(base64_chars[(val >> 18) & 0x3F]);
                    result.push_back(base64_chars[(val >> 12) & 0x3F]);
                    result.push_back(base64_chars[(val >> 6) & 0x3F]);
                    result.push_back(base64_chars[val & 0x3F]);
                    i += 3;
                }

                if (i + 1 == data.size())
                {
                    // 1 byte remaining
                    uint32_t val = static_cast<uint32_t>(data[i]) << 16;
                    result.push_back(base64_chars[(val >> 18) & 0x3F]);
                    result.push_back(base64_chars[(val >> 12) & 0x3F]);
                    result.push_back('=');
                    result.push_back('=');
                }
                else if (i + 2 == data.size())
                {
                    // 2 bytes remaining
                    uint32_t val = (static_cast<uint32_t>(data[i]) << 16) |
                                   (static_cast<uint32_t>(data[i + 1]) << 8);
                    result.push_back(base64_chars[(val >> 18) & 0x3F]);
                    result.push_back(base64_chars[(val >> 12) & 0x3F]);
                    result.push_back(base64_chars[(val >> 6) & 0x3F]);
                    result.push_back('=');
                }
            }
            else if (format == "escape")
            {
                // PostgreSQL escape encoding: non-printable as \nnn octal
                result.reserve(data.size());
                for (uint8_t byte : data)
                {
                    if (byte == '\\')
                    {
                        result.append("\\\\");
                    }
                    else if (byte >= 32 && byte < 127)
                    {
                        result.push_back(static_cast<char>(byte));
                    }
                    else
                    {
                        result.push_back('\\');
                        result.push_back('0' + ((byte >> 6) & 0x07));
                        result.push_back('0' + ((byte >> 3) & 0x07));
                        result.push_back('0' + (byte & 0x07));
                    }
                }
            }
            else
            {
                error("Unknown encoding format: " + format + " (use 'hex', 'base64', or 'escape')");
                return;
            }

            stack_.push(Value::makeText(result));
        }

        void Executor::executeDecode()
        {
            // WP-4 EXEC-8: DECODE(text, format text) -> bytea
            Value format_val = stack_.top(); stack_.pop();
            Value text_val = stack_.top(); stack_.pop();

            if (text_val.isNull() || format_val.isNull())
            {
                stack_.push(Value::makeNull());
                return;
            }

            std::string format = format_val.toString();
            std::transform(format.begin(), format.end(), format.begin(), ::tolower);
            std::string text = text_val.toString();

            std::vector<uint8_t> result;
            if (format == "hex")
            {
                // Hex decoding
                if (text.size() % 2 != 0)
                {
                    error("Invalid hex string: odd length");
                    return;
                }

                result.reserve(text.size() / 2);
                for (size_t i = 0; i < text.size(); i += 2)
                {
                    char hi = text[i];
                    char lo = text[i + 1];

                    auto hex_val = [](char c) -> int {
                        if (c >= '0' && c <= '9') return c - '0';
                        if (c >= 'a' && c <= 'f') return c - 'a' + 10;
                        if (c >= 'A' && c <= 'F') return c - 'A' + 10;
                        return -1;
                    };

                    int hi_val = hex_val(hi);
                    int lo_val = hex_val(lo);

                    if (hi_val < 0 || lo_val < 0)
                    {
                        error("Invalid hex character in string");
                        return;
                    }

                    result.push_back(static_cast<uint8_t>((hi_val << 4) | lo_val));
                }
            }
            else if (format == "base64")
            {
                // Base64 decoding
                auto base64_val = [](char c) -> int {
                    if (c >= 'A' && c <= 'Z') return c - 'A';
                    if (c >= 'a' && c <= 'z') return c - 'a' + 26;
                    if (c >= '0' && c <= '9') return c - '0' + 52;
                    if (c == '+') return 62;
                    if (c == '/') return 63;
                    if (c == '=') return -1;  // Padding
                    return -2;  // Invalid
                };

                // Remove whitespace
                text.erase(std::remove_if(text.begin(), text.end(), ::isspace), text.end());

                if (text.size() % 4 != 0)
                {
                    error("Invalid base64 string: length not multiple of 4");
                    return;
                }

                result.reserve((text.size() / 4) * 3);
                for (size_t i = 0; i < text.size(); i += 4)
                {
                    int v0 = base64_val(text[i]);
                    int v1 = base64_val(text[i + 1]);
                    int value_two = base64_val(text[i + 2]);
                    int v3 = base64_val(text[i + 3]);

                    if (v0 < 0 || v1 < 0 || value_two == -2 || v3 == -2)
                    {
                        error("Invalid base64 character");
                        return;
                    }

                    result.push_back(static_cast<uint8_t>((v0 << 2) | (v1 >> 4)));

                    if (value_two >= 0)
                    {
                        result.push_back(static_cast<uint8_t>(((v1 & 0x0F) << 4) | (value_two >> 2)));

                        if (v3 >= 0)
                        {
                            result.push_back(static_cast<uint8_t>(((value_two & 0x03) << 6) | v3));
                        }
                    }
                }
            }
            else if (format == "escape")
            {
                // PostgreSQL escape decoding
                result.reserve(text.size());
                for (size_t i = 0; i < text.size(); i++)
                {
                    if (text[i] == '\\' && i + 1 < text.size())
                    {
                        if (text[i + 1] == '\\')
                        {
                            result.push_back('\\');
                            i++;
                        }
                        else if (i + 3 < text.size() &&
                                 text[i + 1] >= '0' && text[i + 1] <= '3' &&
                                 text[i + 2] >= '0' && text[i + 2] <= '7' &&
                                 text[i + 3] >= '0' && text[i + 3] <= '7')
                        {
                            // Octal escape
                            uint8_t val = static_cast<uint8_t>(
                                ((text[i + 1] - '0') << 6) |
                                ((text[i + 2] - '0') << 3) |
                                (text[i + 3] - '0'));
                            result.push_back(val);
                            i += 3;
                        }
                        else
                        {
                            result.push_back(static_cast<uint8_t>(text[i]));
                        }
                    }
                    else
                    {
                        result.push_back(static_cast<uint8_t>(text[i]));
                    }
                }
            }
            else
            {
                error("Unknown decoding format: " + format + " (use 'hex', 'base64', or 'escape')");
                return;
            }

            stack_.push(Value::makeUUID(result));  // makeUUID creates binary/bytea type
        }

