        // ============================================================================
        // SPECIALIZED INDEX OPERATIONS (November 19, 2025)
        // Operations for indexes with unique APIs (GIN, HNSW, Columnstore)
        // ============================================================================

        void Executor::executeGinInsert()
        {
            // GIN INSERT Bytecode Format:
            // - Index UUID (16 bytes)
            // - Value length (2 bytes)
            // - Value data (variable)
            // - TID: GPID (8 bytes) + slot (2 bytes)
            // - xmin (8 bytes)
            // - Extractor ID (2 bytes) - identifies the key extraction function

            // Read index UUID (16 bytes)
            core::ID index_uuid;
            for (int i = 0; i < 16; i++)
            {
                if (pc_ >= bytecode_size_)
                {
                    error("Incomplete index UUID in EXT_GIN_INSERT");
                    return;
                }
                index_uuid.bytes[i] = bytecode_[pc_++];
            }

            // Read value length (2 bytes, little-endian)
            if (pc_ + 1 >= bytecode_size_)
            {
                error("Incomplete value length in EXT_GIN_INSERT");
                return;
            }
            uint16_t value_len = bytecode_[pc_++];
            value_len |= (static_cast<uint16_t>(bytecode_[pc_++]) << 8);

            // Read value data
            if (pc_ + value_len > bytecode_size_)
            {
                error("Incomplete value data in EXT_GIN_INSERT");
                return;
            }
            std::vector<uint8_t> value(&bytecode_[0] + pc_, &bytecode_[0] + pc_ + value_len);
            pc_ += value_len;

            // Read TID (10 bytes: GPID 8 + slot 2)
            if (pc_ + 10 > bytecode_size_)
            {
                error("Incomplete TID in EXT_GIN_INSERT");
                return;
            }
            uint64_t gpid = 0;
            for (int i = 0; i < 8; i++)
            {
                gpid |= (static_cast<uint64_t>(bytecode_[pc_++]) << (i * 8));
            }
            uint16_t slot = bytecode_[pc_++];
            slot |= (static_cast<uint16_t>(bytecode_[pc_++]) << 8);
            core::TID tid(gpid, slot);

            // Read xmin (8 bytes, little-endian)
            if (pc_ + 7 >= bytecode_size_)
            {
                error("Incomplete xmin in EXT_GIN_INSERT");
                return;
            }
            uint64_t xmin = 0;
            for (int i = 0; i < 8; i++)
            {
                xmin |= (static_cast<uint64_t>(bytecode_[pc_++]) << (i * 8));
            }

            // Read extractor ID (2 bytes)
            if (pc_ + 1 >= bytecode_size_)
            {
                error("Incomplete extractor ID in EXT_GIN_INSERT");
                return;
            }
            uint16_t extractor_id = bytecode_[pc_++];
            extractor_id |= (static_cast<uint16_t>(bytecode_[pc_++]) << 8);

            // Get the key extractor function from registry
            // NOTE: This assumes a key extractor registry exists
            // For now, we'll use a placeholder implementation
            core::ErrorContext err_ctx;
            core::CatalogManager::IndexInfo index_info;
            auto status = db_->catalog_manager()->getIndex(index_uuid, index_info, &err_ctx);
            if (status != core::Status::OK)
            {
                error("Index not found: " + std::string(err_ctx.message));
                return;
            }

            auto gin = core::GinIndex::open(db_, index_uuid, index_info.root_gpid, &err_ctx);
            if (!gin)
            {
                error("Failed to open GIN index");
                return;
            }

            // Get key extractor from registry (November 20, 2025)
            auto extractor = GinExtractorRegistry::instance().getExtractor(extractor_id);
            if (!extractor) {
                error("Invalid GIN extractor ID: " + std::to_string(extractor_id));
                return;
            }

            // Note: xmin is not used in GIN insert API - GIN handles transaction tracking internally
            (void)xmin; // Suppress unused parameter warning
            core::Status gin_status = gin->insert(value.data(), value.size(), tid, extractor, &err_ctx);

            if (gin_status != core::Status::OK)
            {
                error("GIN insert failed: " + std::string(err_ctx.message));
            }
        }

        void Executor::executeGinSearch()
        {
            // GIN SEARCH Bytecode Format:
            // - Index UUID (16 bytes)
            // - Query length (2 bytes)
            // - Query data (variable)
            // - current_xid (8 bytes)
            // - Extractor ID (2 bytes)

            // Read index UUID (16 bytes)
            core::ID index_uuid;
            for (int i = 0; i < 16; i++)
            {
                if (pc_ >= bytecode_size_)
                {
                    error("Incomplete index UUID in EXT_GIN_SEARCH");
                    return;
                }
                index_uuid.bytes[i] = bytecode_[pc_++];
            }

            // Read query length (2 bytes, little-endian)
            if (pc_ + 1 >= bytecode_size_)
            {
                error("Incomplete query length in EXT_GIN_SEARCH");
                return;
            }
            uint16_t query_len = bytecode_[pc_++];
            query_len |= (static_cast<uint16_t>(bytecode_[pc_++]) << 8);

            // Read query data
            if (pc_ + query_len > bytecode_size_)
            {
                error("Incomplete query data in EXT_GIN_SEARCH");
                return;
            }
            std::vector<uint8_t> query(&bytecode_[0] + pc_, &bytecode_[0] + pc_ + query_len);
            pc_ += query_len;

            // Read current_xid (8 bytes, little-endian)
            if (pc_ + 7 >= bytecode_size_)
            {
                error("Incomplete current_xid in EXT_GIN_SEARCH");
                return;
            }
            uint64_t current_xid = 0;
            for (int i = 0; i < 8; i++)
            {
                current_xid |= (static_cast<uint64_t>(bytecode_[pc_++]) << (i * 8));
            }

            // Read extractor ID (2 bytes)
            if (pc_ + 1 >= bytecode_size_)
            {
                error("Incomplete extractor ID in EXT_GIN_SEARCH");
                return;
            }
            uint16_t extractor_id = bytecode_[pc_++];
            extractor_id |= (static_cast<uint16_t>(bytecode_[pc_++]) << 8);

            // Open GIN index and perform search
            core::ErrorContext err_ctx;
            core::CatalogManager::IndexInfo index_info;
            auto status_get = db_->catalog_manager()->getIndex(index_uuid, index_info, &err_ctx);
            if (status_get != core::Status::OK)
            {
                error("Index not found: " + std::string(err_ctx.message));
                return;
            }

            auto gin = core::GinIndex::open(db_, index_uuid, index_info.root_gpid, &err_ctx);
            if (!gin)
            {
                error("Failed to open GIN index");
                return;
            }

            std::vector<core::TID> results;
            // GIN uses find() for searching, not search()
            core::Status status = gin->find(query.data(), query.size(), current_xid, &results, &err_ctx);

            if (status != core::Status::OK)
            {
                error("GIN search failed: " + std::string(err_ctx.message));
                return;
            }

            // Push results count onto stack
            push(Value::makeInt64(static_cast<int64_t>(results.size())));
        }

        void Executor::executeHnswInsert()
        {
            // HNSW INSERT Bytecode Format:
            // - Index UUID (16 bytes)
            // - Vector dimension (2 bytes)
            // - Vector data (dimension * 4 bytes for float32)
            // - TID: GPID (8 bytes) + slot (2 bytes)
            // - xmin (8 bytes)

            // Read index UUID (16 bytes)
            core::ID index_uuid;
            for (int i = 0; i < 16; i++)
            {
                if (pc_ >= bytecode_size_)
                {
                    error("Incomplete index UUID in EXT_HNSW_INSERT");
                    return;
                }
                index_uuid.bytes[i] = bytecode_[pc_++];
            }

            // Read vector dimension (2 bytes, little-endian)
            if (pc_ + 1 >= bytecode_size_)
            {
                error("Incomplete vector dimension in EXT_HNSW_INSERT");
                return;
            }
            uint16_t dimension = bytecode_[pc_++];
            dimension |= (static_cast<uint16_t>(bytecode_[pc_++]) << 8);

            // Read vector data (dimension * 4 bytes for float32)
            uint32_t vector_bytes = dimension * 4;
            if (pc_ + vector_bytes > bytecode_size_)
            {
                error("Incomplete vector data in EXT_HNSW_INSERT");
                return;
            }
            std::vector<float> vector_data(dimension);
            for (uint16_t i = 0; i < dimension; i++)
            {
                uint32_t float_bits = 0;
                for (int j = 0; j < 4; j++)
                {
                    float_bits |= (static_cast<uint32_t>(bytecode_[pc_++]) << (j * 8));
                }
                // Reinterpret bits as float
                std::memcpy(&vector_data[i], &float_bits, sizeof(float));
            }

            // Read TID (10 bytes: GPID 8 + slot 2)
            if (pc_ + 10 > bytecode_size_)
            {
                error("Incomplete TID in EXT_HNSW_INSERT");
                return;
            }
            uint64_t gpid = 0;
            for (int i = 0; i < 8; i++)
            {
                gpid |= (static_cast<uint64_t>(bytecode_[pc_++]) << (i * 8));
            }
            uint16_t slot = bytecode_[pc_++];
            slot |= (static_cast<uint16_t>(bytecode_[pc_++]) << 8);
            core::TID tid(gpid, slot);

            // Read xmin (8 bytes, little-endian)
            if (pc_ + 7 >= bytecode_size_)
            {
                error("Incomplete xmin in EXT_HNSW_INSERT");
                return;
            }
            uint64_t xmin = 0;
            for (int i = 0; i < 8; i++)
            {
                xmin |= (static_cast<uint64_t>(bytecode_[pc_++]) << (i * 8));
            }

            // Create VectorValue and insert into HNSW index
            core::ErrorContext err_ctx;
            core::CatalogManager::IndexInfo index_info;
            auto status_idx = db_->catalog_manager()->getIndex(index_uuid, index_info, &err_ctx);
            if (status_idx != core::Status::OK)
            {
                error("Index not found: " + std::string(err_ctx.message));
                return;
            }

            auto hnsw = core::HnswIndex::open(db_, index_uuid, index_info.root_gpid, &err_ctx);
            if (!hnsw)
            {
                error("Failed to open HNSW index");
                return;
            }

            // Create VectorValue from float vector
            core::VectorValue vec(vector_data);

            // HNSW insert doesn't take xmin parameter - it manages versioning internally
            core::Status status = hnsw->insert(vec, tid, &err_ctx);

            if (status != core::Status::OK)
            {
                error("HNSW insert failed: " + std::string(err_ctx.message));
            }
        }

        void Executor::executeHnswSearch()
        {
            // HNSW SEARCH Bytecode Format:
            // - Index UUID (16 bytes)
            // - Vector dimension (2 bytes)
            // - Vector data (dimension * 4 bytes for float32)
            // - k (2 bytes) - number of nearest neighbors
            // - current_xid (8 bytes)

            // Read index UUID (16 bytes)
            core::ID index_uuid;
            for (int i = 0; i < 16; i++)
            {
                if (pc_ >= bytecode_size_)
                {
                    error("Incomplete index UUID in EXT_HNSW_SEARCH");
                    return;
                }
                index_uuid.bytes[i] = bytecode_[pc_++];
            }

            // Read vector dimension (2 bytes, little-endian)
            if (pc_ + 1 >= bytecode_size_)
            {
                error("Incomplete vector dimension in EXT_HNSW_SEARCH");
                return;
            }
            uint16_t dimension = bytecode_[pc_++];
            dimension |= (static_cast<uint16_t>(bytecode_[pc_++]) << 8);

            // Read vector data (dimension * 4 bytes for float32)
            uint32_t vector_bytes = dimension * 4;
            if (pc_ + vector_bytes > bytecode_size_)
            {
                error("Incomplete vector data in EXT_HNSW_SEARCH");
                return;
            }
            std::vector<float> vector_data(dimension);
            for (uint16_t i = 0; i < dimension; i++)
            {
                uint32_t float_bits = 0;
                for (int j = 0; j < 4; j++)
                {
                    float_bits |= (static_cast<uint32_t>(bytecode_[pc_++]) << (j * 8));
                }
                std::memcpy(&vector_data[i], &float_bits, sizeof(float));
            }

            // Read k (2 bytes, little-endian)
            if (pc_ + 1 >= bytecode_size_)
            {
                error("Incomplete k in EXT_HNSW_SEARCH");
                return;
            }
            uint16_t k = bytecode_[pc_++];
            k |= (static_cast<uint16_t>(bytecode_[pc_++]) << 8);

            // Read current_xid (8 bytes, little-endian)
            if (pc_ + 7 >= bytecode_size_)
            {
                error("Incomplete current_xid in EXT_HNSW_SEARCH");
                return;
            }
            uint64_t current_xid = 0;
            for (int i = 0; i < 8; i++)
            {
                current_xid |= (static_cast<uint64_t>(bytecode_[pc_++]) << (i * 8));
            }

            // Open HNSW index and perform k-NN search
            core::ErrorContext err_ctx;
            core::CatalogManager::IndexInfo index_info;
            auto status_hnsw = db_->catalog_manager()->getIndex(index_uuid, index_info, &err_ctx);
            if (status_hnsw != core::Status::OK)
            {
                error("Index not found: " + std::string(err_ctx.message));
                return;
            }

            auto hnsw = core::HnswIndex::open(db_, index_uuid, index_info.root_gpid, &err_ctx);
            if (!hnsw)
            {
                error("Failed to open HNSW index");
                return;
            }

            // Create VectorValue for query from float vector
            core::VectorValue query_vec(vector_data);

            std::vector<core::HnswSearchResult> results;
            core::Status status = hnsw->search(query_vec, k, current_xid, &results, &err_ctx);

            if (status != core::Status::OK)
            {
                error("HNSW search failed: " + std::string(err_ctx.message));
                return;
            }

            // Push results count onto stack
            push(Value::makeInt64(static_cast<int64_t>(results.size())));
        }

        void Executor::executeColumnstoreInsert()
        {
            // COLUMNSTORE INSERT Bytecode Format:
            // - Index UUID (16 bytes)
            // - Column ID (2 bytes)
            // - Row count (4 bytes)
            // - Column data length (4 bytes)
            // - Column data (variable)

            // Read index UUID (16 bytes)
            core::ID index_uuid;
            for (int i = 0; i < 16; i++)
            {
                if (pc_ >= bytecode_size_)
                {
                    error("Incomplete index UUID in EXT_COLUMNSTORE_INSERT");
                    return;
                }
                index_uuid.bytes[i] = bytecode_[pc_++];
            }

            // Read column ID (2 bytes, little-endian)
            if (pc_ + 1 >= bytecode_size_)
            {
                error("Incomplete column ID in EXT_COLUMNSTORE_INSERT");
                return;
            }
            uint16_t column_id = bytecode_[pc_++];
            column_id |= (static_cast<uint16_t>(bytecode_[pc_++]) << 8);

            // Read row count (4 bytes, little-endian)
            if (pc_ + 3 >= bytecode_size_)
            {
                error("Incomplete row count in EXT_COLUMNSTORE_INSERT");
                return;
            }
            uint32_t row_count = 0;
            for (int i = 0; i < 4; i++)
            {
                row_count |= (static_cast<uint32_t>(bytecode_[pc_++]) << (i * 8));
            }

            // Read data length (4 bytes, little-endian)
            if (pc_ + 3 >= bytecode_size_)
            {
                error("Incomplete data length in EXT_COLUMNSTORE_INSERT");
                return;
            }
            uint32_t data_len = 0;
            for (int i = 0; i < 4; i++)
            {
                data_len |= (static_cast<uint32_t>(bytecode_[pc_++]) << (i * 8));
            }

            // Read column data
            if (pc_ + data_len > bytecode_size_)
            {
                error("Incomplete column data in EXT_COLUMNSTORE_INSERT");
                return;
            }
            std::vector<uint8_t> column_data(bytecode_ + pc_, bytecode_ + pc_ + data_len);
            pc_ += data_len;

            // Open columnstore index and insert
            core::ErrorContext err_ctx;
            core::CatalogManager::IndexInfo index_info;
            auto status = db_->catalog_manager()->getIndex(index_uuid, index_info, &err_ctx);
            if (status != core::Status::OK)
            {
                error("Index not found: " + std::string(err_ctx.message));
                return;
            }

            auto columnstore = core::ColumnstoreIndexSimple::open(db_, index_uuid, index_info.root_gpid, &err_ctx);
            if (!columnstore)
            {
                error("Failed to open Columnstore index");
                return;
            }

            core::Status insert_status = columnstore->insertColumn(column_id, row_count, column_data, &err_ctx);

            if (insert_status != core::Status::OK)
            {
                error("Columnstore insert failed: " + std::string(err_ctx.message));
            }
        }

        void Executor::executeColumnstoreScan()
        {
            // COLUMNSTORE SCAN Bytecode Format:
            // - Index UUID (16 bytes)
            // - Column ID (2 bytes)
            // - Start row (4 bytes)
            // - End row (4 bytes)

            // Read index UUID (16 bytes)
            core::ID index_uuid;
            for (int i = 0; i < 16; i++)
            {
                if (pc_ >= bytecode_size_)
                {
                    error("Incomplete index UUID in EXT_COLUMNSTORE_SCAN");
                    return;
                }
                index_uuid.bytes[i] = bytecode_[pc_++];
            }

            // Read column ID (2 bytes, little-endian)
            if (pc_ + 1 >= bytecode_size_)
            {
                error("Incomplete column ID in EXT_COLUMNSTORE_SCAN");
                return;
            }
            uint16_t column_id = bytecode_[pc_++];
            column_id |= (static_cast<uint16_t>(bytecode_[pc_++]) << 8);

            // Read start row (4 bytes, little-endian)
            if (pc_ + 3 >= bytecode_size_)
            {
                error("Incomplete start row in EXT_COLUMNSTORE_SCAN");
                return;
            }
            uint32_t start_row = 0;
            for (int i = 0; i < 4; i++)
            {
                start_row |= (static_cast<uint32_t>(bytecode_[pc_++]) << (i * 8));
            }

            // Read end row (4 bytes, little-endian)
            if (pc_ + 3 >= bytecode_size_)
            {
                error("Incomplete end row in EXT_COLUMNSTORE_SCAN");
                return;
            }
            uint32_t end_row = 0;
            for (int i = 0; i < 4; i++)
            {
                end_row |= (static_cast<uint32_t>(bytecode_[pc_++]) << (i * 8));
            }

            // Open columnstore index and scan
            core::ErrorContext err_ctx;
            core::CatalogManager::IndexInfo index_info;
            auto status = db_->catalog_manager()->getIndex(index_uuid, index_info, &err_ctx);
            if (status != core::Status::OK)
            {
                error("Index not found: " + std::string(err_ctx.message));
                return;
            }

            auto columnstore = core::ColumnstoreIndexSimple::open(db_, index_uuid, index_info.root_gpid, &err_ctx);
            if (!columnstore)
            {
                error("Failed to open Columnstore index");
                return;
            }

            std::vector<uint8_t> result_data;
            core::Status scan_status = columnstore->scanColumn(column_id, start_row, end_row, &result_data, &err_ctx);

            if (scan_status != core::Status::OK)
            {
                error("Columnstore scan failed: " + std::string(err_ctx.message));
                return;
            }

            // Push result data length onto stack
            push(Value::makeInt64(static_cast<int64_t>(result_data.size())));
        }

        // Index routing helpers - route to specific index implementations
        core::Status Executor::routeIndexInsert(IndexType type, const core::ID& index_uuid,
                                              const std::vector<uint8_t>& key,
                                              const core::TID& tid, uint64_t xmin,
                                              core::ErrorContext* ctx)
        {
            // Get index info from catalog
            core::CatalogManager::IndexInfo index_info;
            auto status = db_->catalog_manager()->getIndex(index_uuid, index_info, ctx);
            if (status != core::Status::OK)
            {
                SET_ERROR_CONTEXT(ctx, core::Status::INDEX_NOT_FOUND, "Index not found");
                return core::Status::INDEX_NOT_FOUND;
            }

            // Route to appropriate index type (with caching - November 19, 2025)
            switch (type)
            {
                case IndexType::BTREE:
                case IndexType::MONGODB_GEO_HAYSTACK:
                case IndexType::NEO4J_RANGE:
                case IndexType::NEO4J_POINT:
                case IndexType::REDIS_LIST:
                case IndexType::REDIS_ZSET:
                case IndexType::REDIS_STREAM:
                {
                    auto btree = getOrOpenIndex<core::BTree>(index_uuid, type, index_info.root_gpid, ctx);
                    if (btree)
                    {
                        return btree->insert(key, tid, xmin, ctx);
                    }
                    return core::Status::INTERNAL_ERROR;
                }

                case IndexType::HASH:
                case IndexType::REDIS_STRING:
                case IndexType::REDIS_HASH:
                case IndexType::REDIS_SET:
                case IndexType::REDIS_HLL:
                {
                    auto hash_idx = getOrOpenIndex<core::HashIndex>(index_uuid, type, index_info.root_gpid, ctx);
                    if (hash_idx)
                    {
                        // HashIndex::insert() expects (void*, size_t, TID, uint64_t, ErrorContext*)
                        return hash_idx->insert(key.data(), key.size(), tid, xmin, ctx);
                    }
                    return core::Status::INTERNAL_ERROR;
                }

                case IndexType::RTREE:
                case IndexType::MONGODB_2D:
                case IndexType::MONGODB_2DSPHERE:
                case IndexType::MONGODB_2DSPHERE_BUCKET:
                case IndexType::REDIS_GEO:
                {
                    auto rtree = getOrOpenIndex<core::RTreeIndex>(index_uuid, type, index_info.root_gpid, ctx);
                    if (rtree)
                    {
                        return rtree->insert(key, tid, xmin, ctx);
                    }
                    return core::Status::INTERNAL_ERROR;
                }

                case IndexType::GIST:
                {
                    // WP-5 EXEC-11: GiST index integration
                    auto gist = core::GiSTIndex::open(db_, index_uuid, index_info.root_gpid, ctx);
                    if (gist)
                    {
                        // Create GiSTPredicate from key bytes
                        // The operator class is loaded from the registry when the index is opened
                        core::GiSTPredicate predicate(key, 0);  // opclass_id 0 = use index's opclass
                        return gist->insert(predicate, tid, xmin, ctx);
                    }
                    return core::Status::INTERNAL_ERROR;
                }

                case IndexType::SPGIST:
                {
                    auto spgist = getOrOpenIndex<core::SPGiSTIndex>(index_uuid, type, index_info.root_gpid, ctx);
                    if (spgist)
                    {
                        return spgist->insert(key, tid, xmin, ctx);
                    }
                    return core::Status::INTERNAL_ERROR;
                }

                case IndexType::BRIN:
                {
                    auto brin = getOrOpenIndex<core::BrinIndex>(index_uuid, type, index_info.root_gpid, ctx);
                    if (brin)
                    {
                        // BRIN indexes work on block ranges, not individual tuples
                        // Convert TID to block number
                        uint32_t block_num = static_cast<uint32_t>(core::getPageNumber(tid.gpid));
                        return brin->insert(key, block_num, ctx);
                    }
                    return core::Status::INTERNAL_ERROR;
                }

                case IndexType::BITMAP:
                case IndexType::NEO4J_LOOKUP:
                case IndexType::REDIS_BITMAP:
                {
                    auto bitmap = getOrOpenIndex<core::BitmapIndex>(index_uuid, type, index_info.root_gpid, ctx);
                    if (bitmap)
                    {
                        // BitmapIndex::insert() expects (void*, size_t, TID, ErrorContext*)
                        return bitmap->insert(key.data(), key.size(), tid, ctx);
                    }
                    return core::Status::INTERNAL_ERROR;
                }

                case IndexType::LSM:
                {
                    auto lsm = getOrOpenIndex<core::LSMTreeIndex>(index_uuid, type, indexRootPage(index_info), ctx);
                    if (lsm)
                    {
                        // Serialize TID to byte vector (page_num + slot_num)
                        std::vector<uint8_t> value(sizeof(uint32_t) * 2);
                        uint32_t page = static_cast<uint32_t>(core::getPageNumber(tid.gpid));
                        uint32_t slot = tid.slot;
                        std::memcpy(value.data(), &page, sizeof(uint32_t));
                        std::memcpy(value.data() + sizeof(uint32_t), &slot, sizeof(uint32_t));

                        return lsm->put(key, value, xmin, ctx);  // LSM uses put(), not insert()
                    }
                    return core::Status::INTERNAL_ERROR;
                }

                case IndexType::GIN:
                {
                    auto gin = getOrOpenIndex<core::GinIndex>(index_uuid, type, index_info.root_gpid, ctx);
                    if (gin)
                    {
                        // GIN requires a key_extractor function to decompose values into searchable keys
                        // Get the default extractor from the registry
                        auto key_extractor = GinExtractorRegistry::instance().getExtractor(
                            static_cast<uint16_t>(GinExtractorId::DEFAULT));

                        if (!key_extractor)
                        {
                            // Fallback to default extractor
                            key_extractor = GinExtractorRegistry::defaultExtractor;
                        }

                        return gin->insert(key.data(), key.size(), tid, key_extractor, ctx);
                    }
                    return core::Status::INTERNAL_ERROR;
                }

                case IndexType::HNSW:
                case IndexType::NEO4J_VECTOR:
                {
                    auto hnsw = getOrOpenIndex<core::HnswIndex>(index_uuid, type, index_info.root_gpid, ctx);
                    if (hnsw)
                    {
                        // Decode vector from key bytes
                        auto vector_opt = core::Vector::decode(key);
                        if (!vector_opt.has_value())
                        {
                            SET_ERROR_CONTEXT(ctx, core::Status::INVALID_ARGUMENT,
                                                  "Failed to decode vector from key");
                            return core::Status::INVALID_ARGUMENT;
                        }
                        // HNSW insert doesn't take xmin parameter - it manages versioning internally
                        return hnsw->insert(vector_opt.value(), tid, ctx);
                    }
                    return core::Status::INTERNAL_ERROR;
                }

                case IndexType::COLUMNSTORE:
                    // Columnstore requires bulk load operations (not row-level insert/delete)
                    SET_ERROR_CONTEXT(ctx, core::Status::NOT_SUPPORTED,
                                          "Columnstore requires bulk load operations (use LOAD_COLUMNS opcode)");
                    return core::Status::NOT_SUPPORTED;

                case IndexType::FULLTEXT:
                case IndexType::MONGODB_WILDCARD:
                case IndexType::MONGODB_ENCRYPTED_RANGE:
                case IndexType::NEO4J_TEXT:
                case IndexType::CASSANDRA_SASI:
                case IndexType::CASSANDRA_SAI:
                {
                    void* index_ptr = nullptr;
                    core::Status open_status = core::IndexFactory::openIndex(
                        index_info.index_type, db_, index_info, &index_ptr, ctx);
                    if (open_status != core::Status::OK || !index_ptr)
                    {
                        return open_status != core::Status::OK ? open_status : core::Status::INTERNAL_ERROR;
                    }
                    std::unique_ptr<core::InvertedIndex> inverted(
                        static_cast<core::InvertedIndex*>(index_ptr));

                    std::string text;
                    size_t offset = 0;
                    while (offset < key.size())
                    {
                        uint32_t len = 0;
                        if (!core::readUint32LE(key.data(), key.size(), offset, len))
                        {
                            SET_ERROR_CONTEXT(ctx, core::Status::DATA_CORRUPTED,
                                              "FULLTEXT key length prefix invalid");
                            return core::Status::DATA_CORRUPTED;
                        }
                        if (offset + len > key.size())
                        {
                            SET_ERROR_CONTEXT(ctx, core::Status::DATA_CORRUPTED,
                                              "FULLTEXT key length exceeds payload");
                            return core::Status::DATA_CORRUPTED;
                        }
                        if (!text.empty())
                        {
                            text.push_back(' ');
                        }
                        text.append(reinterpret_cast<const char*>(key.data() + offset), len);
                        offset += len;
                    }
                    return inverted->insert(text.data(), text.size(), tid, ctx);
                }

                default:
                    SET_ERROR_CONTEXT(ctx, core::Status::INTERNAL_ERROR, "Unknown index type");
                    return core::Status::INTERNAL_ERROR;
            }
        }

        core::Status Executor::routeIndexSearch(IndexType type, const core::ID& index_uuid,
                                              const std::vector<uint8_t>& key,
                                              uint64_t current_xid,
                                              std::vector<core::TID>* results_out,
                                              core::ErrorContext* ctx)
        {
            // Get index info from catalog
            core::CatalogManager::IndexInfo index_info;
            auto status = db_->catalog_manager()->getIndex(index_uuid, index_info, ctx);
            if (status != core::Status::OK)
            {
                SET_ERROR_CONTEXT(ctx, core::Status::INDEX_NOT_FOUND, "Index not found");
                return core::Status::INDEX_NOT_FOUND;
            }

            // Route to appropriate index type
            switch (type)
            {
                case IndexType::BTREE:
                case IndexType::MONGODB_GEO_HAYSTACK:
                case IndexType::NEO4J_RANGE:
                case IndexType::NEO4J_POINT:
                case IndexType::REDIS_LIST:
                case IndexType::REDIS_ZSET:
                case IndexType::REDIS_STREAM:
                {
                    auto btree = getOrOpenIndex<core::BTree>(index_uuid, type, index_info.root_gpid, ctx);
                    if (btree)
                    {
                        return btree->search(key, current_xid, results_out, ctx);
                    }
                    return core::Status::INTERNAL_ERROR;
                }

                case IndexType::HASH:
                case IndexType::REDIS_STRING:
                case IndexType::REDIS_HASH:
                case IndexType::REDIS_SET:
                case IndexType::REDIS_HLL:
                {
                    auto hash_idx = getOrOpenIndex<core::HashIndex>(index_uuid, type, index_info.root_gpid, ctx);
                    if (hash_idx)
                    {
                        // HashIndex uses find() for point lookups, not search()
                        return hash_idx->find(key.data(), key.size(), current_xid, results_out, ctx);
                    }
                    return core::Status::INTERNAL_ERROR;
                }

                case IndexType::RTREE:
                case IndexType::MONGODB_2D:
                case IndexType::MONGODB_2DSPHERE:
                case IndexType::MONGODB_2DSPHERE_BUCKET:
                case IndexType::REDIS_GEO:
                {
                    auto rtree = getOrOpenIndex<core::RTreeIndex>(index_uuid, type, index_info.root_gpid, ctx);
                    if (rtree)
                    {
                        return rtree->search(key, current_xid, results_out, ctx);
                    }
                    return core::Status::INTERNAL_ERROR;
                }

                case IndexType::GIST:
                {
                    // WP-5 EXEC-11: GiST index integration
                    auto gist = core::GiSTIndex::open(db_, index_uuid, index_info.root_gpid, ctx);
                    if (gist)
                    {
                        // GiST search uses raw key bytes and defaults to OVERLAPS strategy
                        return gist->search(key, core::GiSTStrategy::OVERLAPS, current_xid, results_out, ctx);
                    }
                    return core::Status::INTERNAL_ERROR;
                }

                case IndexType::SPGIST:
                {
                    auto spgist = getOrOpenIndex<core::SPGiSTIndex>(index_uuid, type, index_info.root_gpid, ctx);
                    if (spgist)
                    {
                        return spgist->search(key, current_xid, results_out, ctx);
                    }
                    return core::Status::INTERNAL_ERROR;
                }

                case IndexType::BRIN:
                {
                    auto brin = getOrOpenIndex<core::BrinIndex>(index_uuid, type, index_info.root_gpid, ctx);
                    if (brin)
                    {
                        // BRIN doesn't have search() - it uses scan() for range queries
                        // For a point lookup, treat the key as both min and max value
                        std::vector<uint32_t> block_numbers;
                        core::Status status = brin->scan(&key, &key, current_xid, &block_numbers, ctx);

                        if (status != core::Status::OK)
                        {
                            return status;
                        }

                        // BRIN returns block numbers, not TIDs
                        // This is a design limitation - the caller needs to scan the returned blocks
                        // For now, return NOT_SUPPORTED since we can't return block numbers via TID vector
                        SET_ERROR_CONTEXT(ctx, core::Status::NOT_SUPPORTED,
                                         "BRIN point lookup requires block-level scan (use range scan instead)");
                        return core::Status::NOT_SUPPORTED;
                    }
                    return core::Status::INTERNAL_ERROR;
                }

                case IndexType::BITMAP:
                case IndexType::NEO4J_LOOKUP:
                case IndexType::REDIS_BITMAP:
                {
                    auto bitmap = getOrOpenIndex<core::BitmapIndex>(index_uuid, type, index_info.root_gpid, ctx);
                    if (bitmap)
                    {
                        // BitmapIndex::scan() expects (void*, size_t, uint64_t, ErrorContext*)
                        auto scanner = bitmap->scan(key.data(), key.size(), current_xid, ctx);
                        if (!scanner)
                        {
                            return core::Status::INTERNAL_ERROR;
                        }

                        // Iterate over scanner and collect matching TIDs
                        results_out->clear();
                        while (scanner->hasNext())
                        {
                            core::TID tid;
                            core::Status status = scanner->next(&tid, ctx);
                            if (status != core::Status::OK)
                            {
                                return status;
                            }
                            results_out->push_back(tid);
                        }
                        return core::Status::OK;
                    }
                    return core::Status::INTERNAL_ERROR;
                }

                case IndexType::LSM:
                {
                    auto lsm = getOrOpenIndex<core::LSMTreeIndex>(index_uuid, type, indexRootPage(index_info), ctx);
                    if (lsm)
                    {
                        std::vector<uint8_t> value;
                        bool found = false;
                        core::Status status = lsm->get(key, current_xid, &value, &found, ctx);
                        if (status == core::Status::OK && found && value.size() >= sizeof(uint32_t) * 2)
                        {
                            // Deserialize TID from byte vector
                            uint32_t page, slot;
                            std::memcpy(&page, value.data(), sizeof(uint32_t));
                            std::memcpy(&slot, value.data() + sizeof(uint32_t), sizeof(uint32_t));
                            core::TID result_tid(page, slot);
                            results_out->push_back(result_tid);
                        }
                        return status;
                    }
                    return core::Status::INTERNAL_ERROR;
                }

                case IndexType::FULLTEXT:
                case IndexType::MONGODB_WILDCARD:
                case IndexType::MONGODB_ENCRYPTED_RANGE:
                case IndexType::NEO4J_TEXT:
                case IndexType::CASSANDRA_SASI:
                case IndexType::CASSANDRA_SAI:
                {
                    void* index_ptr = nullptr;
                    core::Status open_status = core::IndexFactory::openIndex(
                        index_info.index_type, db_, index_info, &index_ptr, ctx);
                    if (open_status != core::Status::OK || !index_ptr)
                    {
                        return open_status != core::Status::OK ? open_status : core::Status::INTERNAL_ERROR;
                    }
                    std::unique_ptr<core::InvertedIndex> inverted(
                        static_cast<core::InvertedIndex*>(index_ptr));

                    std::string query;
                    size_t offset = 0;
                    while (offset < key.size())
                    {
                        uint32_t len = 0;
                        if (!core::readUint32LE(key.data(), key.size(), offset, len))
                        {
                            SET_ERROR_CONTEXT(ctx, core::Status::DATA_CORRUPTED,
                                              "FULLTEXT key length prefix invalid");
                            return core::Status::DATA_CORRUPTED;
                        }
                        if (offset + len > key.size())
                        {
                            SET_ERROR_CONTEXT(ctx, core::Status::DATA_CORRUPTED,
                                              "FULLTEXT key length exceeds payload");
                            return core::Status::DATA_CORRUPTED;
                        }
                        if (!query.empty())
                        {
                            query.push_back(' ');
                        }
                        query.append(reinterpret_cast<const char*>(key.data() + offset), len);
                        offset += len;
                    }

                    return inverted->search(query, current_xid, results_out, ctx);
                }

                case IndexType::GIN:
                    // GIN (Generalized Inverted Index) requires specialized query operators
                    // Generic key search doesn't apply to inverted indexes
                    SET_ERROR_CONTEXT(ctx, core::Status::NOT_SUPPORTED,
                                          "GIN requires specialized query operators (e.g., @>, @@)");
                    return core::Status::NOT_SUPPORTED;

                case IndexType::HNSW:
                case IndexType::NEO4J_VECTOR:
                    // HNSW uses k-NN search, not exact key search
                    SET_ERROR_CONTEXT(ctx, core::Status::NOT_SUPPORTED,
                                          "HNSW requires k-NN search operator (<-> with LIMIT)");
                    return core::Status::NOT_SUPPORTED;

                case IndexType::COLUMNSTORE:
                    // Columnstore uses specialized scan operations
                    SET_ERROR_CONTEXT(ctx, core::Status::NOT_SUPPORTED,
                                          "Columnstore requires specialized scan operations");
                    return core::Status::NOT_SUPPORTED;

                default:
                    SET_ERROR_CONTEXT(ctx, core::Status::INTERNAL_ERROR, "Unknown index type");
                    return core::Status::INTERNAL_ERROR;
            }
        }

        core::Status Executor::routeIndexDelete(IndexType type, const core::ID& index_uuid,
                                              const std::vector<uint8_t>& key,
                                              const core::TID& tid, uint64_t xmax,
                                              core::ErrorContext* ctx)
        {
            // Get index info from catalog
            core::CatalogManager::IndexInfo index_info;
            auto status = db_->catalog_manager()->getIndex(index_uuid, index_info, ctx);
            if (status != core::Status::OK)
            {
                SET_ERROR_CONTEXT(ctx, core::Status::INDEX_NOT_FOUND, "Index not found");
                return core::Status::INDEX_NOT_FOUND;
            }

            // Route to appropriate index type
            // Use remove() or markDeleted() depending on what's available
            switch (type)
            {
                case IndexType::BTREE:
                case IndexType::MONGODB_GEO_HAYSTACK:
                case IndexType::NEO4J_RANGE:
                case IndexType::NEO4J_POINT:
                case IndexType::REDIS_LIST:
                case IndexType::REDIS_ZSET:
                case IndexType::REDIS_STREAM:
                {
                    auto btree = getOrOpenIndex<core::BTree>(index_uuid, type, index_info.root_gpid, ctx);
                    if (btree)
                    {
                        // B-Tree has markDeleted() for MGA-compliant soft deletion
                        return btree->markDeleted(key, tid, xmax, ctx);
                    }
                    return core::Status::INTERNAL_ERROR;
                }

                case IndexType::HASH:
                case IndexType::REDIS_STRING:
                case IndexType::REDIS_HASH:
                case IndexType::REDIS_SET:
                case IndexType::REDIS_HLL:
                {
                    auto hash_idx = getOrOpenIndex<core::HashIndex>(index_uuid, type, index_info.root_gpid, ctx);
                    if (hash_idx)
                    {
                        // HashIndex::remove() expects (void*, size_t, TID, uint64_t, ErrorContext*)
                        return hash_idx->remove(key.data(), key.size(), tid, xmax, ctx);
                    }
                    return core::Status::INTERNAL_ERROR;
                }

                case IndexType::RTREE:
                case IndexType::MONGODB_2D:
                case IndexType::MONGODB_2DSPHERE:
                case IndexType::MONGODB_2DSPHERE_BUCKET:
                case IndexType::REDIS_GEO:
                {
                    auto rtree = getOrOpenIndex<core::RTreeIndex>(index_uuid, type, index_info.root_gpid, ctx);
                    if (rtree)
                    {
                        return rtree->remove(key, tid, xmax, ctx);
                    }
                    return core::Status::INTERNAL_ERROR;
                }

                case IndexType::GIST:
                {
                    // WP-5 EXEC-11: GiST index integration
                    auto gist = core::GiSTIndex::open(db_, index_uuid, index_info.root_gpid, ctx);
                    if (gist)
                    {
                        // Create GiSTPredicate from key bytes
                        core::GiSTPredicate predicate(key, 0);
                        return gist->remove(predicate, tid, xmax, ctx);
                    }
                    return core::Status::INTERNAL_ERROR;
                }

                case IndexType::SPGIST:
                {
                    auto spgist = getOrOpenIndex<core::SPGiSTIndex>(index_uuid, type, index_info.root_gpid, ctx);
                    if (spgist)
                    {
                        return spgist->remove(key, tid, xmax, ctx);
                    }
                    return core::Status::INTERNAL_ERROR;
                }

                case IndexType::BRIN:
                {
                    auto brin = getOrOpenIndex<core::BrinIndex>(index_uuid, type, index_info.root_gpid, ctx);
                    if (brin)
                    {
                        // BRIN remove is a no-op (returns OK)
                        return brin->remove(key, 0, ctx);
                    }
                    return core::Status::INTERNAL_ERROR;
                }

                case IndexType::BITMAP:
                case IndexType::NEO4J_LOOKUP:
                case IndexType::REDIS_BITMAP:
                {
                    auto bitmap = getOrOpenIndex<core::BitmapIndex>(index_uuid, type, index_info.root_gpid, ctx);
                    if (bitmap)
                    {
                        // BitmapIndex::remove() only takes TID, not key or xmax
                        // The xmax is handled internally by the index
                        return bitmap->remove(tid, ctx);
                    }
                    return core::Status::INTERNAL_ERROR;
                }

                case IndexType::LSM:
                {
                    auto lsm = getOrOpenIndex<core::LSMTreeIndex>(index_uuid, type, indexRootPage(index_info), ctx);
                    if (lsm)
                    {
                        // LSMTreeIndex remove only needs key and transaction ID
                        return lsm->remove(key, xmax, ctx);
                    }
                    return core::Status::INTERNAL_ERROR;
                }

                case IndexType::GIN:
                {
                    auto gin = getOrOpenIndex<core::GinIndex>(index_uuid, type, index_info.root_gpid, ctx);
                    if (gin)
                    {
                        // GIN requires a key_extractor function to decompose values into searchable keys
                        // Get the default extractor from the registry
                        auto key_extractor = GinExtractorRegistry::instance().getExtractor(
                            static_cast<uint16_t>(GinExtractorId::DEFAULT));

                        if (!key_extractor)
                        {
                            // Fallback to default extractor
                            key_extractor = GinExtractorRegistry::defaultExtractor;
                        }

                        return gin->remove(key.data(), key.size(), tid, key_extractor, xmax, ctx);
                    }
                    return core::Status::INTERNAL_ERROR;
                }

                case IndexType::HNSW:
                case IndexType::NEO4J_VECTOR:
                {
                    auto hnsw = getOrOpenIndex<core::HnswIndex>(index_uuid, type, index_info.root_gpid, ctx);
                    if (hnsw)
                    {
                        // HNSW remove() only takes TID (doesn't need key or xmax)
                        // It manages xmax internally
                        return hnsw->remove(tid, ctx);
                    }
                    return core::Status::INTERNAL_ERROR;
                }

                case IndexType::COLUMNSTORE:
                    // Columnstore requires bulk operations
                    SET_ERROR_CONTEXT(ctx, core::Status::NOT_SUPPORTED,
                                          "Columnstore requires bulk load operations");
                    return core::Status::NOT_SUPPORTED;

                case IndexType::FULLTEXT:
                case IndexType::MONGODB_WILDCARD:
                case IndexType::MONGODB_ENCRYPTED_RANGE:
                case IndexType::NEO4J_TEXT:
                case IndexType::CASSANDRA_SASI:
                case IndexType::CASSANDRA_SAI:
                {
                    void* index_ptr = nullptr;
                    core::Status open_status = core::IndexFactory::openIndex(
                        index_info.index_type, db_, index_info, &index_ptr, ctx);
                    if (open_status != core::Status::OK || !index_ptr)
                    {
                        return open_status != core::Status::OK ? open_status : core::Status::INTERNAL_ERROR;
                    }
                    std::unique_ptr<core::InvertedIndex> inverted(
                        static_cast<core::InvertedIndex*>(index_ptr));

                    std::string text;
                    size_t offset = 0;
                    while (offset < key.size())
                    {
                        uint32_t len = 0;
                        if (!core::readUint32LE(key.data(), key.size(), offset, len))
                        {
                            SET_ERROR_CONTEXT(ctx, core::Status::DATA_CORRUPTED,
                                              "FULLTEXT key length prefix invalid");
                            return core::Status::DATA_CORRUPTED;
                        }
                        if (offset + len > key.size())
                        {
                            SET_ERROR_CONTEXT(ctx, core::Status::DATA_CORRUPTED,
                                              "FULLTEXT key length exceeds payload");
                            return core::Status::DATA_CORRUPTED;
                        }
                        if (!text.empty())
                        {
                            text.push_back(' ');
                        }
                        text.append(reinterpret_cast<const char*>(key.data() + offset), len);
                        offset += len;
                    }
                    return inverted->remove(text.data(), text.size(), tid, xmax, ctx);
                }

                default:
                    SET_ERROR_CONTEXT(ctx, core::Status::INTERNAL_ERROR, "Unknown index type");
                    return core::Status::INTERNAL_ERROR;
            }
        }

        core::Status Executor::routeIndexScan(IndexType type, const core::ID& index_uuid,
                                             const std::vector<uint8_t>* start_key,
                                             const std::vector<uint8_t>* end_key,
                                             bool start_inclusive, bool end_inclusive,
                                             uint64_t current_xid,
                                             std::vector<core::TID>* results_out,
                                             core::ErrorContext* ctx)
        {
            // Get index info from catalog
            core::CatalogManager::IndexInfo index_info;
            auto status = db_->catalog_manager()->getIndex(index_uuid, index_info, ctx);
            if (status != core::Status::OK)
            {
                SET_ERROR_CONTEXT(ctx, core::Status::INDEX_NOT_FOUND, "Index not found");
                return core::Status::INDEX_NOT_FOUND;
            }

            // Route to appropriate index type
            // Only indexes that support range scans are routed
            switch (type)
            {
                case IndexType::BTREE:
                case IndexType::MONGODB_GEO_HAYSTACK:
                case IndexType::NEO4J_RANGE:
                case IndexType::NEO4J_POINT:
                case IndexType::REDIS_LIST:
                case IndexType::REDIS_ZSET:
                case IndexType::REDIS_STREAM:
                {
                    auto btree = getOrOpenIndex<core::BTree>(index_uuid, type, index_info.root_gpid, ctx);
                    if (btree)
                    {
                        // Use B-Tree rangeScan() to get an iterator
                        auto iter = btree->rangeScan(start_key, end_key, current_xid,
                                                    start_inclusive, end_inclusive, ctx);
                        if (!iter)
                        {
                            if (ctx) {
                                ctx->set(core::Status::INTERNAL_ERROR, "Failed to create B-Tree iterator",
                                        __FILE__, __LINE__, __func__);
                            }
                            return core::Status::INTERNAL_ERROR;
                        }

                        // Collect results from iterator
                        results_out->clear();
                        while (iter->hasNext())
                        {
                            std::vector<uint8_t> key_result;
                            core::TID tid_result;
                            core::Status status = iter->next(&key_result, &tid_result, ctx);
                            if (status == core::Status::OK)
                            {
                                results_out->push_back(tid_result);
                            }
                            else
                            {
                                break;
                            }
                        }
                        return core::Status::OK;
                    }
                    return core::Status::INTERNAL_ERROR;
                }

                case IndexType::RTREE:
                case IndexType::MONGODB_2D:
                case IndexType::MONGODB_2DSPHERE:
                case IndexType::MONGODB_2DSPHERE_BUCKET:
                case IndexType::REDIS_GEO:
                {
                    auto rtree = getOrOpenIndex<core::RTreeIndex>(index_uuid, type, index_info.root_gpid, ctx);
                    if (rtree)
                    {
                        // R-Tree spatial scan
                        // For R-Tree, start_key and end_key represent the bounding box
                        if (!start_key || !end_key)
                        {
                            if (ctx) {
                                ctx->set(core::Status::INVALID_ARGUMENT, "R-Tree scan requires bounding box (start and end keys)",
                                        __FILE__, __LINE__, __func__);
                            }
                            return core::Status::INVALID_ARGUMENT;
                        }

                        // Use search() with bounding box
                        return rtree->search(*start_key, current_xid, results_out, ctx);
                    }
                    return core::Status::INTERNAL_ERROR;
                }

                case IndexType::GIST:
                {
                    // WP-5 EXEC-11: GiST index integration
                    auto gist = core::GiSTIndex::open(db_, index_uuid, index_info.root_gpid, ctx);
                    if (gist)
                    {
                        // GiST scan uses start_key as the search predicate
                        if (!start_key)
                        {
                            if (ctx) {
                                ctx->set(core::Status::INVALID_ARGUMENT, "GiST scan requires search predicate",
                                        __FILE__, __LINE__, __func__);
                            }
                            return core::Status::INVALID_ARGUMENT;
                        }
                        return gist->search(*start_key, core::GiSTStrategy::OVERLAPS, current_xid, results_out, ctx);
                    }
                    return core::Status::INTERNAL_ERROR;
                }

                case IndexType::SPGIST:
                {
                    auto spgist = getOrOpenIndex<core::SPGiSTIndex>(index_uuid, type, index_info.root_gpid, ctx);
                    if (spgist)
                    {
                        // SP-GiST scan
                        if (!start_key)
                        {
                            if (ctx) {
                                ctx->set(core::Status::INVALID_ARGUMENT, "SP-GiST scan requires search predicate",
                                        __FILE__, __LINE__, __func__);
                            }
                            return core::Status::INVALID_ARGUMENT;
                        }

                        return spgist->search(*start_key, current_xid, results_out, ctx);
                    }
                    return core::Status::INTERNAL_ERROR;
                }

                case IndexType::BRIN:
                {
                    auto brin = getOrOpenIndex<core::BrinIndex>(index_uuid, type, index_info.root_gpid, ctx);
                    if (brin)
                    {
                        // BRIN block range scan
                        if (!start_key || !end_key)
                        {
                            if (ctx) {
                                ctx->set(core::Status::INVALID_ARGUMENT, "BRIN scan requires value range",
                                        __FILE__, __LINE__, __func__);
                            }
                            return core::Status::INVALID_ARGUMENT;
                        }

                        // BRIN returns block numbers that might contain values in range
                        std::vector<uint32_t> block_numbers;
                        core::Status status = brin->scan(start_key, end_key, current_xid, &block_numbers, ctx);

                        if (status != core::Status::OK)
                        {
                            return status;
                        }

                        // BRIN returns block numbers, not TIDs
                        // This is a design limitation - the caller needs to scan the returned blocks
                        // For now, return NOT_SUPPORTED since we can't return block numbers via TID vector
                        SET_ERROR_CONTEXT(ctx, core::Status::NOT_SUPPORTED,
                                         "BRIN range scan requires block-level scan (use heap scan on returned blocks)");
                        return core::Status::NOT_SUPPORTED;
                    }
                    return core::Status::INTERNAL_ERROR;
                }

                case IndexType::BITMAP:
                case IndexType::NEO4J_LOOKUP:
                case IndexType::REDIS_BITMAP:
                {
                    auto bitmap = getOrOpenIndex<core::BitmapIndex>(index_uuid, type, index_info.root_gpid, ctx);
                    if (bitmap)
                    {
                        // Bitmap scan for matching bits
                        if (!start_key)
                        {
                            if (ctx) {
                                ctx->set(core::Status::INVALID_ARGUMENT, "Bitmap scan requires value",
                                        __FILE__, __LINE__, __func__);
                            }
                            return core::Status::INVALID_ARGUMENT;
                        }

                        // Create scanner with proper parameters (data pointer, size, xid, ctx)
                        auto scanner = bitmap->scan(start_key->data(), start_key->size(), current_xid, ctx);
                        if (!scanner)
                        {
                            return core::Status::INTERNAL_ERROR;
                        }

                        // Iterate over scanner and collect matching TIDs
                        while (scanner->hasNext())
                        {
                            core::TID tid;
                            core::Status status = scanner->next(&tid, ctx);
                            if (status != core::Status::OK)
                            {
                                return status;
                            }
                            results_out->push_back(tid);
                        }

                        return core::Status::OK;
                    }
                    return core::Status::INTERNAL_ERROR;
                }

                case IndexType::LSM:
                {
                    auto lsm = getOrOpenIndex<core::LSMTreeIndex>(index_uuid, type, indexRootPage(index_info), ctx);
                    if (lsm)
                    {
                        // LSM-Tree range scan
                        std::vector<core::MemtableEntry> entries;
                        std::vector<uint8_t> start_key_vec = start_key ? *start_key : std::vector<uint8_t>();
                        std::vector<uint8_t> end_key_vec = end_key ? *end_key : std::vector<uint8_t>();

                        core::Status status = lsm->scan(start_key_vec, end_key_vec, current_xid, &entries, ctx);
                        if (status != core::Status::OK)
                        {
                            return status;
                        }

                        // Collect results - deserialize TIDs from entry values
                        results_out->clear();
                        for (const auto &entry : entries)
                        {
                            if (entry.value.size() >= sizeof(uint32_t) * 2)
                            {
                                uint32_t page, slot;
                                std::memcpy(&page, entry.value.data(), sizeof(uint32_t));
                                std::memcpy(&slot, entry.value.data() + sizeof(uint32_t), sizeof(uint32_t));
                                results_out->push_back(core::TID(page, slot));
                            }
                        }
                        return core::Status::OK;
                    }
                    return core::Status::INTERNAL_ERROR;
                }

                case IndexType::FULLTEXT:
                case IndexType::MONGODB_WILDCARD:
                case IndexType::MONGODB_ENCRYPTED_RANGE:
                case IndexType::NEO4J_TEXT:
                case IndexType::CASSANDRA_SASI:
                case IndexType::CASSANDRA_SAI:
                {
                    if (ctx) {
                        ctx->set(core::Status::NOT_SUPPORTED, "FULLTEXT indexes require @@ search operator",
                                __FILE__, __LINE__, __func__);
                    }
                    return core::Status::NOT_SUPPORTED;
                }

                case IndexType::HASH:
                case IndexType::REDIS_STRING:
                case IndexType::REDIS_HASH:
                case IndexType::REDIS_SET:
                case IndexType::REDIS_HLL:
                {
                    // Hash indexes don't support range scans
                    if (ctx) {
                        ctx->set(core::Status::NOT_SUPPORTED, "Hash indexes do not support range scans",
                                __FILE__, __LINE__, __func__);
                    }
                    return core::Status::NOT_SUPPORTED;
                }

                case IndexType::GIN:
                {
                    // GIN (Generalized Inverted Index) doesn't support range scans
                    if (ctx) {
                        ctx->set(core::Status::NOT_SUPPORTED, "GIN indexes do not support range scans",
                                __FILE__, __LINE__, __func__);
                    }
                    return core::Status::NOT_SUPPORTED;
                }

                case IndexType::HNSW:
                case IndexType::NEO4J_VECTOR:
                {
                    // HNSW uses k-NN search, not range scans
                    if (ctx) {
                        ctx->set(core::Status::NOT_SUPPORTED, "HNSW indexes do not support range scans (use k-NN search)",
                                __FILE__, __LINE__, __func__);
                    }
                    return core::Status::NOT_SUPPORTED;
                }

                case IndexType::COLUMNSTORE:
                {
                    // Columnstore uses specialized scan operations
                    if (ctx) {
                        ctx->set(core::Status::NOT_SUPPORTED, "Columnstore uses specialized scan operations",
                                __FILE__, __LINE__, __func__);
                    }
                    return core::Status::NOT_SUPPORTED;
                }

                default:
                {
                    if (ctx) {
                        ctx->set(core::Status::INTERNAL_ERROR, "Unknown index type",
                                __FILE__, __LINE__, __func__);
                    }
                    return core::Status::INTERNAL_ERROR;
                }
            }
        }

        namespace {
            inline core::CatalogManager::ParameterMode decodeParameterMode(uint8_t mode_byte)
            {
                using Mode = core::CatalogManager::ParameterMode;
                switch (mode_byte)
                {
                    case 1: return Mode::OUT;
                    case 2: return Mode::INOUT;
                    default: return Mode::IN;
                }
            }

            inline core::DataType decodeDataType(uint8_t type_byte)
            {
                if (type_byte == 0)
                {
                    return core::DataType::UNKNOWN;
                }
                return static_cast<core::DataType>(type_byte);
            }

            inline core::CatalogManager::FunctionInfo::SqlSecurity decodeSqlSecurity(uint8_t flags)
            {
                return (flags & 0x04)
                    ? core::CatalogManager::FunctionInfo::SqlSecurity::DEFINER
                    : core::CatalogManager::FunctionInfo::SqlSecurity::INVOKER;
            }

            inline core::CatalogManager::ProcedureInfo::SqlSecurity decodeProcSqlSecurity(uint8_t flags)
            {
                return (flags & 0x04)
                    ? core::CatalogManager::ProcedureInfo::SqlSecurity::DEFINER
                    : core::CatalogManager::ProcedureInfo::SqlSecurity::INVOKER;
            }

            inline bool isZeroUuid(const core::ID& id)
            {
                for (auto b : id.bytes) {
                    if (b != 0) {
                        return false;
                    }
                }
                return true;
            }

            QueryHash computeResultCacheHash(const std::vector<uint8_t>& bytecode,
                                              const std::vector<std::string>& params,
                                              const std::vector<bool>& nulls,
                                              uint64_t policy_epoch)
            {
                std::vector<uint8_t> payload;
                payload.reserve(bytecode.size() + params.size() * 16);
                payload.insert(payload.end(), bytecode.begin(), bytecode.end());

                for (size_t i = 0; i < params.size(); ++i)
                {
                    payload.push_back(0x1f);
                    bool is_null = (i < nulls.size()) ? nulls[i] : false;
                    payload.push_back(is_null ? 0 : 1);
                    if (!is_null)
                    {
                        payload.insert(payload.end(), params[i].begin(), params[i].end());
                    }
                    payload.push_back(0x1e);
                }

                for (int i = 7; i >= 0; --i)
                {
                    payload.push_back(static_cast<uint8_t>((policy_epoch >> (i * 8)) & 0xFF));
                }

                return QueryResultCache::computeHash(payload);
            }

            std::unique_ptr<ResultSet> buildResultSetFromCache(const CachedResultSet& cached)
            {
                auto result_set = std::make_unique<ResultSet>();
                for (size_t i = 0; i < cached.column_names.size(); ++i)
                {
                    result_set->addColumn(cached.column_names[i], cached.column_types[i]);
                }
                for (const auto& row : cached.rows)
                {
                    std::vector<Value> values;
                    values.reserve(row.size());
                    for (const auto& value : row)
                    {
                        values.push_back(value);
                    }
                    result_set->addRow(std::move(values));
                }
                return result_set;
            }

            CachedResultSet buildCachedResultSetFromResultSet(
                const ResultSet& result_set,
                const std::unordered_set<core::ID, core::IDHash>& table_ids)
            {
                CachedResultSet cached;
                cached.table_ids = table_ids;
                size_t column_count = result_set.columnCount();
                cached.column_names.reserve(column_count);
                cached.column_types.reserve(column_count);
                for (size_t i = 0; i < column_count; ++i)
                {
                    cached.column_names.push_back(result_set.columnName(i));
                    cached.column_types.push_back(result_set.columnType(i));
                }
                size_t row_count = result_set.rowCount();
                cached.rows.reserve(row_count);
                for (size_t r = 0; r < row_count; ++r)
                {
                    std::vector<Value> row;
                    row.reserve(column_count);
                    for (size_t c = 0; c < column_count; ++c)
                    {
                        row.push_back(result_set.getValue(r, c));
                    }
                    cached.rows.push_back(std::move(row));
                }
                return cached;
            }

            bool isDbOwnerRole(core::CatalogManager* catalog, core::ConnectionContext* conn_ctx)
            {
                if (!catalog || !conn_ctx) {
                    return false;
                }
                core::CatalogManager::RoleInfo role_info;
                core::ErrorContext role_ctx;
                if (catalog->getRoleByName("DB_OWNER", role_info, &role_ctx) != core::Status::OK) {
                    return false;
                }
                if (!isZeroUuid(conn_ctx->getActiveRoleId()) &&
                    conn_ctx->getActiveRoleId() == role_info.role_id) {
                    return true;
                }
                if (isZeroUuid(conn_ctx->getCurrentUserId())) {
                    return false;
                }
                std::vector<core::CatalogManager::RoleMembershipInfo> roles;
                if (catalog->getUserRoles(conn_ctx->getCurrentUserId(), roles, &role_ctx) != core::Status::OK) {
                    return false;
                }
                for (const auto& membership : roles) {
                    if (membership.role_id == role_info.role_id) {
                        return true;
                    }
                }
                return false;
            }

            bool hasJobAdminPrivilege(core::CatalogManager* catalog, core::ConnectionContext* conn_ctx)
            {
                if (!conn_ctx) {
                    return false;
                }
                if (conn_ctx->isSuperuser()) {
                    return true;
                }
                return isDbOwnerRole(catalog, conn_ctx);
            }

            bool userHasRole(core::CatalogManager* catalog, core::ConnectionContext* conn_ctx,
                             const core::ID& role_id)
            {
                if (!conn_ctx || !catalog) {
                    return false;
                }
                if (conn_ctx->isSuperuser() || hasJobAdminPrivilege(catalog, conn_ctx)) {
                    return true;
                }
                const core::ID& current_user = conn_ctx->getCurrentUserId();
                if (isZeroUuid(current_user)) {
                    return false;
                }
                std::vector<core::CatalogManager::RoleMembershipInfo> roles;
                core::ErrorContext err_ctx;
                if (catalog->getUserRoles(current_user, roles, &err_ctx) != core::Status::OK) {
                    return false;
                }
                for (const auto& membership : roles) {
                    if (membership.role_id == role_id) {
                        return true;
                    }
                }
                return false;
            }

            core::Status checkJobDependencyCycle(core::CatalogManager* catalog,
                                                 const core::ID& job_id,
                                                 const std::vector<core::ID>& deps,
                                                 bool& has_cycle,
                                                 core::ErrorContext& err_ctx)
            {
                has_cycle = false;
                if (!catalog) {
                    return core::Status::INVALID_ARGUMENT;
                }
                for (const auto& dep_id : deps)
                {
                    if (dep_id == job_id)
                    {
                        has_cycle = true;
                        return core::Status::OK;
                    }
                    std::vector<core::ID> stack;
                    std::unordered_set<core::ID, core::IDHash> visited;
                    stack.push_back(dep_id);
                    while (!stack.empty())
                    {
                        core::ID current = stack.back();
                        stack.pop_back();
                        if (current == job_id)
                        {
                            has_cycle = true;
                            return core::Status::OK;
                        }
                        if (visited.find(current) != visited.end())
                        {
                            continue;
                        }
                        visited.insert(current);

                        std::vector<core::CatalogManager::JobDependencyInfo> child_deps;
                        auto status = catalog->listJobDependencies(current, child_deps, &err_ctx);
                        if (status != core::Status::OK)
                        {
                            return status;
                        }
                        for (const auto& child : child_deps)
                        {
                            stack.push_back(child.depends_on_job_id);
                        }
                    }
                }
                return core::Status::OK;
            }

            std::string trimAsciiLocal(const std::string& value)
            {
                size_t start = 0;
                while (start < value.size() &&
                       std::isspace(static_cast<unsigned char>(value[start])) != 0) {
                    ++start;
                }
                size_t end = value.size();
                while (end > start &&
                       std::isspace(static_cast<unsigned char>(value[end - 1])) != 0) {
                    --end;
                }
                return value.substr(start, end - start);
            }

            bool parseUuidText(const std::string& text, core::ID& out)
            {
                std::string trimmed = trimAsciiLocal(text);
                if (trimmed.empty()) {
                    return false;
                }

                if (trimmed.rfind("urn:uuid:", 0) == 0 || trimmed.rfind("URN:UUID:", 0) == 0) {
                    trimmed = trimmed.substr(9);
                }

                std::string hex;
                hex.reserve(trimmed.size());
                for (char ch : trimmed) {
                    if (ch == '{' || ch == '}' || ch == '-') {
                        continue;
                    }
                    hex.push_back(ch);
                }

                if (hex.size() != 32) {
                    return false;
                }

                auto hexValue = [](char ch) -> int {
                    if (ch >= '0' && ch <= '9') return ch - '0';
                    if (ch >= 'a' && ch <= 'f') return 10 + (ch - 'a');
                    if (ch >= 'A' && ch <= 'F') return 10 + (ch - 'A');
                    return -1;
                };

                for (size_t i = 0; i < 16; ++i) {
                    int high = hexValue(hex[i * 2]);
                    int low = hexValue(hex[i * 2 + 1]);
                    if (high < 0 || low < 0) {
                        return false;
                    }
                    out.bytes[i] = static_cast<uint8_t>((high << 4) | low);
                }

                return true;
            }

            void logJobAudit(core::Database* db,
                             core::ConnectionContext* conn_ctx,
                             core::AuditEventType type,
                             const core::CatalogManager::JobInfo& job,
                             const core::ID* run_id,
                             bool success,
                             const std::string& message)
            {
                if (!db) {
                    return;
                }
                auto* audit_logger = db->audit_logger();
                if (!audit_logger) {
                    return;
                }

                core::AuditEvent event;
                event.event_type = type;
                event.success = success;
                event.object_type = "JOB";
                event.object_name = job.job_name;
                event.object_id = job.job_id;

                if (conn_ctx) {
                    event.user_id = conn_ctx->getCurrentUserId();
                    event.role_id = conn_ctx->getActiveRoleId();
                    event.session_id = conn_ctx->sessionId();
                    event.authkey_id = conn_ctx->authKeyId();
                } else {
                    event.user_id = job.created_by_user_uuid;
                }

                if (!isZeroUuid(event.user_id)) {
                    core::CatalogManager::UserInfo user_info;
                    core::ErrorContext user_ctx;
                    if (db->catalog_manager() &&
                        db->catalog_manager()->getUser(event.user_id, user_info, &user_ctx) == core::Status::OK) {
                        event.username = user_info.username;
                    }
                }

                json details;
                if (run_id) {
                    details["job_run_uuid"] = run_id->toString();
                }
                if (!message.empty()) {
                    details["message"] = message;
                }
                event.details = details.dump();

                core::ErrorContext audit_ctx;
                audit_logger->logEvent(event, &audit_ctx);
            }

            core::ID resolveDefaultSchema(core::CatalogManager* catalog)
            {
                core::ID schema_id{};
                if (!catalog) { return schema_id; }
                core::CatalogManager::SchemaInfo schema_info;
                core::ErrorContext ctx;
                if (catalog->getSchema("users.public", schema_info, &ctx) == core::Status::OK ||
                    catalog->getSchema("public", schema_info, &ctx) == core::Status::OK)
                {
                    schema_id = schema_info.schema_id;
                }
                return schema_id;
            }

            std::string normalizeSchemaPath(const std::string& path)
            {
                if (path.find('/') == std::string::npos)
                {
                    return path;
                }
                std::string normalized;
                size_t start = 0;
                while (start < path.size())
                {
                    while (start < path.size() && path[start] == '/')
                    {
                        ++start;
                    }
                    if (start >= path.size())
                    {
                        break;
                    }
                    size_t end = path.find('/', start);
                    if (end == std::string::npos)
                    {
                        end = path.size();
                    }
                    if (!normalized.empty())
                    {
                        normalized.push_back('.');
                    }
                    normalized.append(path, start, end - start);
                    start = end + 1;
                }
                return normalized;
            }

            std::string trimWhitespace(const std::string& input)
            {
                size_t start = 0;
                while (start < input.size() &&
                       std::isspace(static_cast<unsigned char>(input[start])))
                {
                    ++start;
                }
                if (start >= input.size())
                {
                    return "";
                }
                size_t end = input.size();
                while (end > start &&
                       std::isspace(static_cast<unsigned char>(input[end - 1])))
                {
                    --end;
                }
                return input.substr(start, end - start);
            }

            std::string stripStringLiteral(const std::string& input)
            {
                std::string trimmed = trimWhitespace(input);
                if (trimmed.size() >= 2 && trimmed.front() == '\'' && trimmed.back() == '\'')
                {
                    std::string value = trimmed.substr(1, trimmed.size() - 2);
                    std::string unescaped;
                    unescaped.reserve(value.size());
                    for (size_t i = 0; i < value.size(); ++i)
                    {
                        if (value[i] == '\'' && i + 1 < value.size() && value[i + 1] == '\'')
                        {
                            unescaped.push_back('\'');
                            ++i;
                        }
                        else
                        {
                            unescaped.push_back(value[i]);
                        }
                    }
                    return unescaped;
                }
                return trimmed;
            }

            std::string normalizePartitionLiteral(const std::string& input)
            {
                std::string trimmed = trimWhitespace(input);
                std::string upper = scratchbird::core::IdentifierUtils::toUpper(trimmed);
                if (upper.rfind("DATE", 0) == 0 || upper.rfind("TIME", 0) == 0 ||
                    upper.rfind("TIMESTAMP", 0) == 0)
                {
                    size_t quote_pos = trimmed.find('\'');
                    if (quote_pos != std::string::npos)
                    {
                        return stripStringLiteral(trimmed.substr(quote_pos));
                    }
                    size_t space = trimmed.find(' ');
                    if (space != std::string::npos)
                    {
                        return stripStringLiteral(trimmed.substr(space + 1));
                    }
                }
                return stripStringLiteral(trimmed);
            }

            bool parseNumericLiteral(const std::string& input, int64_t& out)
            {
                std::string trimmed = trimWhitespace(input);
                if (trimmed.empty())
                {
                    return false;
                }
                try
                {
                    size_t idx = 0;
                    long long value = std::stoll(trimmed, &idx, 10);
                    if (idx != trimmed.size())
                    {
                        return false;
                    }
                    out = static_cast<int64_t>(value);
                    return true;
                }
                catch (...)
                {
                    return false;
                }
            }

            bool parseDoubleLiteral(const std::string& input, double& out)
            {
                std::string trimmed = trimWhitespace(input);
                if (trimmed.empty())
                {
                    return false;
                }
                try
                {
                    size_t idx = 0;
                    double value = std::stod(trimmed, &idx);
                    if (idx != trimmed.size())
                    {
                        return false;
                    }
                    out = value;
                    return true;
                }
                catch (...)
                {
                    return false;
                }
            }

            std::vector<std::string> splitTopLevel(const std::string& text)
            {
                std::vector<std::string> parts;
                std::string current;
                int depth = 0;
                bool in_quote = false;
                for (size_t i = 0; i < text.size(); ++i)
                {
                    char ch = text[i];
                    if (ch == '\'' && (i == 0 || text[i - 1] != '\\'))
                    {
                        in_quote = !in_quote;
                        current.push_back(ch);
                        continue;
                    }
                    if (!in_quote)
                    {
                        if (ch == '(')
                        {
                            depth++;
                        }
                        else if (ch == ')' && depth > 0)
                        {
                            depth--;
                        }
                        else if (ch == ',' && depth == 0)
                        {
                            parts.push_back(trimWhitespace(current));
                            current.clear();
                            continue;
                        }
                    }
                    current.push_back(ch);
                }
                if (!current.empty())
                {
                    parts.push_back(trimWhitespace(current));
                }
                return parts;
            }

            bool parsePartitionBounds(const std::string& bounds_text, PartitionBound& bound_out)
            {
                std::string trimmed = trimWhitespace(bounds_text);
                std::string upper = scratchbird::core::IdentifierUtils::toUpper(trimmed);
                if (upper.find("DEFAULT") != std::string::npos)
                {
                    bound_out.kind = PartitionBound::Kind::DEFAULT;
                    return true;
                }

                auto find_keyword = [&](const std::string& keyword) -> size_t {
                    size_t pos = upper.find(keyword);
                    if (pos == std::string::npos)
                    {
                        return pos;
                    }
                    return pos;
                };

                size_t in_pos = find_keyword("IN");
                size_t from_pos = find_keyword("FROM");
                size_t to_pos = find_keyword("TO");

                auto extract_paren_content = [&](size_t start_pos, std::string& out) -> bool {
                    size_t open_pos = trimmed.find('(', start_pos);
                    if (open_pos == std::string::npos)
                    {
                        return false;
                    }
                    int depth = 0;
                    for (size_t i = open_pos; i < trimmed.size(); ++i)
                    {
                        if (trimmed[i] == '(')
                        {
                            depth++;
                        }
                        else if (trimmed[i] == ')')
                        {
                            depth--;
                            if (depth == 0)
                            {
                                out = trimmed.substr(open_pos + 1, i - open_pos - 1);
                                return true;
                            }
                        }
                    }
                    return false;
                };

                if (in_pos != std::string::npos)
                {
                    std::string list_content;
                    if (!extract_paren_content(in_pos, list_content))
                    {
                        return false;
                    }
                    bound_out.kind = PartitionBound::Kind::LIST;
                    auto items = splitTopLevel(list_content);
                    for (const auto& item : items)
                    {
                        std::string value = trimWhitespace(item);
                        if (value.empty())
                        {
                            continue;
                        }
                        if (value.front() == '(' && value.back() == ')')
                        {
                            std::string inner = value.substr(1, value.size() - 2);
                            bound_out.list_values.push_back(splitTopLevel(inner));
                        }
                        else
                        {
                            bound_out.list_values.push_back({value});
                        }
                    }
                    return true;
                }

                if (from_pos != std::string::npos && to_pos != std::string::npos)
                {
                    std::string from_content;
                    std::string to_content;
                    if (!extract_paren_content(from_pos, from_content) ||
                        !extract_paren_content(to_pos, to_content))
                    {
                        return false;
                    }
                    bound_out.kind = PartitionBound::Kind::RANGE;
                    bound_out.range_start = splitTopLevel(from_content);
                    bound_out.range_end = splitTopLevel(to_content);
                    bound_out.has_start = !bound_out.range_start.empty();
                    bound_out.has_end = !bound_out.range_end.empty();
                    return true;
                }

                return false;
            }

            bool parseSblrExpressionList(const std::vector<uint8_t>& data,
                                         std::vector<std::vector<uint8_t>>& expressions_out)
            {
                expressions_out.clear();
                if (data.size() < 8)
                {
                    return false;
                }
                if (data[0] != 'S' || data[1] != 'B' || data[2] != 'L' || data[3] != 'R')
                {
                    return false;
                }

                auto read_u32 = [&](size_t offset, uint32_t& out) -> bool {
                    if (offset + 4 > data.size())
                    {
                        return false;
                    }
                    out = static_cast<uint32_t>(data[offset]) |
                          (static_cast<uint32_t>(data[offset + 1]) << 8) |
                          (static_cast<uint32_t>(data[offset + 2]) << 16) |
                          (static_cast<uint32_t>(data[offset + 3]) << 24);
                    return true;
                };

                size_t pos = 4;
                uint32_t count = 0;
                if (!read_u32(pos, count))
                {
                    return false;
                }
                pos += 4;

                expressions_out.reserve(count);
                for (uint32_t i = 0; i < count; ++i)
                {
                    uint32_t len = 0;
                    if (!read_u32(pos, len))
                    {
                        return false;
                    }
                    pos += 4;
                    if (pos + len > data.size())
                    {
                        return false;
                    }
                    auto start = static_cast<std::vector<uint8_t>::difference_type>(pos);
                    auto end = static_cast<std::vector<uint8_t>::difference_type>(pos + len);
                    expressions_out.emplace_back(data.begin() + start,
                                                 data.begin() + end);
                    pos += len;
                }

                return pos == data.size();
            }

            bool loadTableMetadata(core::CatalogManager* catalog,
                                   const core::CatalogManager::TableInfo& table_info,
                                   json& metadata_out,
                                   core::ErrorContext* ctx)
            {
                metadata_out = json::object();
                if (!catalog || isZeroId(table_info.storage_params_oid))
                {
                    return false;
                }
                std::string params;
                if (catalog->loadStringFromToast(table_info.storage_params_oid, 0, params, ctx) != core::Status::OK ||
                    params.empty())
                {
                    return false;
                }
                try
                {
                    metadata_out = json::parse(params);
                }
                catch (...)
                {
                    metadata_out = json::object();
                    return false;
                }
                return true;
            }

            bool resolveTableByQualifiedName(core::CatalogManager* catalog,
                                             const core::ID& default_schema_id,
                                             const std::string& qualified_name,
                                             core::CatalogManager::TableInfo& table_info_out,
                                             core::ErrorContext* ctx)
            {
                if (!catalog)
                {
                    return false;
                }
                std::string normalized = normalizeSchemaPath(qualified_name);
                auto components = splitSchemaComponents(normalized);
                if (components.empty())
                {
                    return false;
                }
                std::string table_name = components.back();
                if (components.size() == 1)
                {
                    if (catalog->getTable(default_schema_id, table_name, table_info_out, ctx) != core::Status::OK)
                    {
                        return false;
                    }
                    return true;
                }

                std::vector<std::string> schema_components = components;
                schema_components.pop_back();
                std::string schema_path = joinSchemaComponents(schema_components, 0);
                core::CatalogManager::SchemaInfo schema_info;
                if (catalog->getSchema(schema_path, schema_info, ctx) != core::Status::OK)
                {
                    return false;
                }
                if (catalog->getTable(schema_info.schema_id, table_name, table_info_out, ctx) != core::Status::OK)
                {
                    return false;
                }
                return true;
            }

            std::vector<core::CatalogManager::TableInfo> collectPartitionChildren(
                core::CatalogManager* catalog,
                const core::CatalogManager::TableInfo& parent,
                const json& parent_meta,
                core::ErrorContext* ctx)
            {
                std::vector<core::CatalogManager::TableInfo> children;
                if (!catalog)
                {
                    return children;
                }
                if (!parent_meta.contains("partition") || !parent_meta["partition"].is_object())
                {
                    return children;
                }
                const auto& partition = parent_meta["partition"];
                if (!partition.contains("children") || !partition["children"].is_array())
                {
                    return children;
                }

                for (const auto& entry : partition["children"])
                {
                    if (!entry.contains("name"))
                    {
                        continue;
                    }
                    std::string name = entry["name"].get<std::string>();
                    core::CatalogManager::TableInfo child_info;
                    if (!resolveTableByQualifiedName(catalog, parent.schema_id, name, child_info, ctx))
                    {
                        continue;
                    }
                    children.push_back(std::move(child_info));
                }
                return children;
            }

            std::vector<core::CatalogManager::TableInfo> collectInheritanceChildren(
                core::CatalogManager* catalog,
                const core::CatalogManager::TableInfo& parent,
                core::ErrorContext* ctx)
            {
                std::vector<core::CatalogManager::TableInfo> children;
                if (!catalog)
                {
                    return children;
                }
                std::vector<core::CatalogManager::SchemaInfo> schemas;
                if (catalog->listSchemas(schemas, ctx) != core::Status::OK)
                {
                    return children;
                }

                for (const auto& schema : schemas)
                {
                    std::vector<core::CatalogManager::TableInfo> tables;
                    if (catalog->listTables(schema.schema_id, tables, ctx) != core::Status::OK)
                    {
                        continue;
                    }
                    for (const auto& table : tables)
                    {
                        if (table.table_id == parent.table_id)
                        {
                            continue;
                        }
                        json meta;
                        if (!loadTableMetadata(catalog, table, meta, ctx))
                        {
                            continue;
                        }
                        bool matches = false;
                        if (meta.contains("inherits_refs") && meta["inherits_refs"].is_array())
                        {
                            for (const auto& entry : meta["inherits_refs"])
                            {
                                if (!entry.is_object())
                                {
                                    continue;
                                }
                                if (entry.contains("id") && entry["id"].is_string())
                                {
                                    core::ID parent_id;
                                    if (parseUuidText(entry["id"].get<std::string>(), parent_id) &&
                                        parent_id == parent.table_id)
                                    {
                                        matches = true;
                                        break;
                                    }
                                }
                                if (entry.contains("name") && entry["name"].is_string())
                                {
                                    std::string parent_name = entry["name"].get<std::string>();
                                    core::CatalogManager::TableInfo parent_info;
                                    if (resolveTableByQualifiedName(catalog, table.schema_id,
                                                                    parent_name, parent_info, ctx) &&
                                        parent_info.table_id == parent.table_id)
                                    {
                                        matches = true;
                                        break;
                                    }
                                }
                            }
                        }

                        if (!matches &&
                            meta.contains("inherits") && meta["inherits"].is_array())
                        {
                            for (const auto& entry : meta["inherits"])
                            {
                                if (!entry.is_string())
                                {
                                    continue;
                                }
                                std::string parent_name = entry.get<std::string>();
                                core::CatalogManager::TableInfo parent_info;
                                if (resolveTableByQualifiedName(catalog, table.schema_id,
                                                                parent_name, parent_info, ctx) &&
                                    parent_info.table_id == parent.table_id)
                                {
                                    matches = true;
                                    break;
                                }
                            }
                        }
                        if (matches)
                        {
                            children.push_back(table);
                        }
                    }
                }
                return children;
            }

            std::vector<core::CatalogManager::TableInfo> collectExpandedTables(
                core::CatalogManager* catalog,
                const core::CatalogManager::TableInfo& base_table,
                core::ErrorContext* ctx)
            {
                std::vector<core::CatalogManager::TableInfo> expanded;
                if (!catalog)
                {
                    return expanded;
                }
                expanded.push_back(base_table);

                json meta;
                loadTableMetadata(catalog, base_table, meta, ctx);

                auto partition_children = collectPartitionChildren(catalog, base_table, meta, ctx);
                auto inherit_children = collectInheritanceChildren(catalog, base_table, ctx);

                std::unordered_set<core::ID, core::IDHash> seen;
                seen.insert(base_table.table_id);
                for (auto& child : partition_children)
                {
                    if (seen.insert(child.table_id).second)
                    {
                        expanded.push_back(std::move(child));
                    }
                }
                for (auto& child : inherit_children)
                {
                    if (seen.insert(child.table_id).second)
                    {
                        expanded.push_back(std::move(child));
                    }
                }
                return expanded;
            }

            std::vector<std::string> splitSchemaComponents(const std::string& path)
            {
                std::vector<std::string> components;
                std::string normalized = normalizeSchemaPath(path);
                size_t start = 0;
                while (start < normalized.size())
                {
                    size_t dot = normalized.find('.', start);
                    size_t end = (dot == std::string::npos) ? normalized.size() : dot;
                    if (end > start)
                    {
                        components.emplace_back(normalized.substr(start, end - start));
                    }
                    if (dot == std::string::npos)
                    {
                        break;
                    }
                    start = dot + 1;
                }
                return components;
            }

            std::string joinSchemaComponents(const std::vector<std::string>& components,
                                             size_t start_index)
            {
                std::string joined;
                for (size_t i = start_index; i < components.size(); ++i)
                {
                    if (!joined.empty())
                    {
                        joined.push_back('.');
                    }
                    joined.append(components[i]);
                }
                return joined;
            }

            core::Status buildAbsoluteSchemaPath(core::CatalogManager* catalog,
                                                 const core::ConnectionContext* conn_ctx,
                                                 const core::ObjectPath& path,
                                                 std::string& path_out,
                                                 core::ErrorContext* ctx)
            {
                path_out.clear();
                if (!catalog)
                {
                    SET_ERROR_CONTEXT(ctx, core::Status::INTERNAL_ERROR,
                                      "Catalog manager not available");
                    return core::Status::INTERNAL_ERROR;
                }

                std::string suffix = joinSchemaComponents(path.components);
                if (suffix.empty())
                {
                    SET_ERROR_CONTEXT(ctx, core::Status::INVALID_ARGUMENT,
                                      "Schema path is empty");
                    return core::Status::INVALID_ARGUMENT;
                }

                core::PathType type = path.type;
                if (type == core::PathType::UNQUALIFIED)
                {
                    type = core::PathType::ABSOLUTE;
                }

                if (type == core::PathType::ABSOLUTE)
                {
                    path_out = suffix;
                    return core::Status::OK;
                }

                if (!conn_ctx)
                {
                    SET_ERROR_CONTEXT(ctx, core::Status::NOT_FOUND,
                                      "Current schema not available");
                    return core::Status::NOT_FOUND;
                }

                core::ID base_schema_id = conn_ctx->getCurrentSchemaId();
                if (isZeroUuid(base_schema_id))
                {
                    SET_ERROR_CONTEXT(ctx, core::Status::NOT_FOUND,
                                      "Current schema not available");
                    return core::Status::NOT_FOUND;
                }

                if (type == core::PathType::PARENT)
                {
                    core::CatalogManager::SchemaInfo schema_info;
                    auto status = catalog->getSchema(base_schema_id, schema_info, ctx);
                    if (status != core::Status::OK)
                    {
                        return status;
                    }
                    base_schema_id = schema_info.parent_schema_id;
                    if (isZeroUuid(base_schema_id))
                    {
                        SET_ERROR_CONTEXT(ctx, core::Status::NOT_FOUND,
                                          "Current schema has no parent");
                        return core::Status::NOT_FOUND;
                    }
                }

                std::string base_path;
                auto status = catalog->getSchemaPath(base_schema_id, base_path, ctx);
                if (status != core::Status::OK)
                {
                    return status;
                }

                if (base_path.empty())
                {
                    path_out = suffix;
                }
                else
                {
                    path_out = base_path + "." + suffix;
                }

                return core::Status::OK;
            }

            core::Status extractEmulatedDatabaseComponents(const std::string& path,
                                                           std::string& normalized_path_out,
                                                           std::string& dialect_out,
                                                           std::string& server_out,
                                                           std::string& database_out,
                                                           core::ErrorContext* ctx)
            {
                normalized_path_out = normalizeSchemaPath(path);
                auto components = splitSchemaComponents(normalized_path_out);
                if (components.empty())
                {
                    SET_ERROR_CONTEXT(ctx, core::Status::INVALID_ARGUMENT,
                                      "Emulated database path is empty");
                    return core::Status::INVALID_ARGUMENT;
                }

                size_t start = 0;
                if (scratchbird::core::IdentifierUtils::namesMatch(
                        components[0], false, "root", false))
                {
                    start = 1;
                }

                // Legacy path support:
                //   remote.emulation.<dialect>.<server>...
                // Canonical path:
                //   emulated.<dialect>.<server>...
                if (components.size() > start + 1 &&
                    scratchbird::core::IdentifierUtils::namesMatch(
                        components[start], false, "remote", false) &&
                    (scratchbird::core::IdentifierUtils::namesMatch(
                         components[start + 1], false, "emulation", false) ||
                     scratchbird::core::IdentifierUtils::namesMatch(
                         components[start + 1], false, "emulated", false)))
                {
                    start += 1;
                }

                if (components.size() - start < 4)
                {
                    SET_ERROR_CONTEXT(ctx, core::Status::INVALID_ARGUMENT,
                                      "Emulated database path is incomplete");
                    return core::Status::INVALID_ARGUMENT;
                }

                if (!(scratchbird::core::IdentifierUtils::namesMatch(
                          components[start], false, "emulated", false) ||
                      scratchbird::core::IdentifierUtils::namesMatch(
                          components[start], false, "emulation", false)))
                {
                    SET_ERROR_CONTEXT(ctx, core::Status::INVALID_ARGUMENT,
                                      "Emulated database path must start with emulated");
                    return core::Status::INVALID_ARGUMENT;
                }

                components[start] = "emulated";
                dialect_out = components[start + 1];
                server_out = components[start + 2];
                database_out = components.back();
                normalized_path_out = joinSchemaComponents(components, start);

                return core::Status::OK;
            }

            core::Status expandEmulatedAliasPath(core::CatalogManager* catalog,
                                                 const std::string& path_in,
                                                 std::string& path_out,
                                                 core::ErrorContext* ctx)
            {
                path_out = normalizeSchemaPath(path_in);
                if (!catalog)
                {
                    SET_ERROR_CONTEXT(ctx, core::Status::INTERNAL_ERROR,
                                      "Catalog manager not available");
                    return core::Status::INTERNAL_ERROR;
                }

                auto components = splitSchemaComponents(path_out);
                if (components.empty())
                {
                    return core::Status::OK;
                }

                size_t start = 0;
                if (scratchbird::core::IdentifierUtils::namesMatch(
                        components[0], false, "root", false))
                {
                    start = 1;
                }

                size_t dialect_index = 0;
                size_t alias_index = 0;
                size_t suffix_index = 0;
                bool is_emulated_path = false;

                if (components.size() > start + 3 &&
                    scratchbird::core::IdentifierUtils::namesMatch(
                        components[start], false, "remote", false) &&
                    (scratchbird::core::IdentifierUtils::namesMatch(
                         components[start + 1], false, "emulation", false) ||
                     scratchbird::core::IdentifierUtils::namesMatch(
                         components[start + 1], false, "emulated", false)))
                {
                    dialect_index = start + 2;
                    alias_index = start + 3;
                    suffix_index = start + 4;
                    is_emulated_path = true;
                }
                else if (components.size() > start + 2 &&
                         (scratchbird::core::IdentifierUtils::namesMatch(
                              components[start], false, "emulated", false) ||
                          scratchbird::core::IdentifierUtils::namesMatch(
                              components[start], false, "emulation", false)))
                {
                    dialect_index = start + 1;
                    alias_index = start + 2;
                    suffix_index = start + 3;
                    is_emulated_path = true;
                }

                if (!is_emulated_path)
                {
                    return core::Status::OK;
                }

                std::string dialect = components[dialect_index];
                std::string alias = components[alias_index];
                if (alias.empty())
                {
                    SET_ERROR_CONTEXT(ctx, core::Status::INVALID_ARGUMENT,
                                      "Emulated alias is empty");
                    return core::Status::INVALID_ARGUMENT;
                }

                core::CatalogManager::SynonymInfo synonym;
                bool found_synonym = false;
                std::array<std::string, 3> alias_schema_candidates = {
                    "emulated." + dialect,
                    "remote.emulation." + dialect,
                    "remote.emulated." + dialect};

                for (const auto& alias_schema_path : alias_schema_candidates)
                {
                    core::CatalogManager::SchemaInfo alias_schema;
                    core::ErrorContext schema_ctx;
                    auto status = catalog->getSchema(alias_schema_path, alias_schema, &schema_ctx);
                    if (status != core::Status::OK)
                    {
                        continue;
                    }

                    core::ErrorContext synonym_ctx;
                    status = catalog->getSynonymByName(alias_schema.schema_id, alias, synonym, &synonym_ctx);
                    if (status == core::Status::OK)
                    {
                        found_synonym = true;
                        break;
                    }
                    if (status == core::Status::INVALID_ARGUMENT ||
                        status == core::Status::NOT_FOUND)
                    {
                        continue;
                    }
                    copyErrorContext(ctx, synonym_ctx);
                    return status;
                }

                if (!found_synonym)
                {
                    return core::Status::OK;
                }

                if (synonym.target_type != core::CatalogManager::ObjectType::SCHEMA)
                {
                    SET_ERROR_CONTEXT(ctx, core::Status::INVALID_ARGUMENT,
                                      "Emulated alias does not reference a schema");
                    return core::Status::INVALID_ARGUMENT;
                }

                std::string target_path = normalizeSchemaPath(synonym.target_path);
                auto target_components = splitSchemaComponents(target_path);
                std::vector<std::string> expanded = target_components;
                if (components.size() > suffix_index)
                {
                    expanded.insert(expanded.end(),
                                    components.begin() +
                                        static_cast<std::vector<std::string>::difference_type>(suffix_index),
                                    components.end());
                }
                path_out = joinSchemaComponents(expanded, 0);
                return core::Status::OK;
            }

            core::Status createEmulatedAliasSynonym(core::CatalogManager* catalog,
                                                    const std::string& dialect,
                                                    const std::string& alias,
                                                    const std::string& target_path,
                                                    core::ErrorContext* ctx)
            {
                if (!catalog)
                {
                    SET_ERROR_CONTEXT(ctx, core::Status::INTERNAL_ERROR,
                                      "Catalog manager not available");
                    return core::Status::INTERNAL_ERROR;
                }
                if (alias.empty())
                {
                    SET_ERROR_CONTEXT(ctx, core::Status::INVALID_ARGUMENT,
                                      "Alias name cannot be empty");
                    return core::Status::INVALID_ARGUMENT;
                }
                if (alias.find('.') != std::string::npos || alias.find('/') != std::string::npos)
                {
                    SET_ERROR_CONTEXT(ctx, core::Status::INVALID_ARGUMENT,
                                      "Alias name must be a single identifier");
                    return core::Status::INVALID_ARGUMENT;
                }

                core::CatalogManager::SchemaInfo alias_schema;
                core::Status status = core::Status::NOT_FOUND;
                std::array<std::string, 3> alias_schema_candidates = {
                    "emulated." + dialect,
                    "remote.emulation." + dialect,
                    "remote.emulated." + dialect};

                bool found_schema = false;
                for (const auto& alias_schema_path : alias_schema_candidates)
                {
                    core::ErrorContext schema_ctx;
                    status = catalog->getSchema(alias_schema_path, alias_schema, &schema_ctx);
                    if (status == core::Status::OK)
                    {
                        found_schema = true;
                        break;
                    }
                    if (status != core::Status::INVALID_ARGUMENT &&
                        status != core::Status::NOT_FOUND)
                    {
                        copyErrorContext(ctx, schema_ctx);
                        return status;
                    }
                }

                if (!found_schema)
                {
                    SET_ERROR_CONTEXT(ctx, core::Status::NOT_FOUND,
                                      "Emulated alias schema not found");
                    return core::Status::NOT_FOUND;
                }

                core::ID synonym_id;
                status = catalog->createSynonym(alias_schema.schema_id,
                                                alias,
                                                target_path,
                                                core::CatalogManager::ObjectType::SCHEMA,
                                                true,
                                                synonym_id,
                                                ctx);
                if (status != core::Status::OK)
                {
                    return status;
                }
                return core::Status::OK;
            }

            core::Status dropEmulatedAliasSynonym(core::CatalogManager* catalog,
                                                  const std::string& dialect,
                                                  const std::string& alias,
                                                  core::ErrorContext* ctx)
            {
                if (!catalog)
                {
                    SET_ERROR_CONTEXT(ctx, core::Status::INTERNAL_ERROR,
                                      "Catalog manager not available");
                    return core::Status::INTERNAL_ERROR;
                }
                if (alias.empty())
                {
                    SET_ERROR_CONTEXT(ctx, core::Status::INVALID_ARGUMENT,
                                      "Alias name cannot be empty");
                    return core::Status::INVALID_ARGUMENT;
                }

                std::array<std::string, 3> alias_schema_candidates = {
                    "emulated." + dialect,
                    "remote.emulation." + dialect,
                    "remote.emulated." + dialect};

                bool dropped_any = false;
                for (const auto& alias_schema_path : alias_schema_candidates)
                {
                    core::CatalogManager::SchemaInfo alias_schema;
                    core::ErrorContext schema_ctx;
                    auto status = catalog->getSchema(alias_schema_path, alias_schema, &schema_ctx);
                    if (status == core::Status::INVALID_ARGUMENT ||
                        status == core::Status::NOT_FOUND)
                    {
                        continue;
                    }
                    if (status != core::Status::OK)
                    {
                        copyErrorContext(ctx, schema_ctx);
                        return status;
                    }

                    core::CatalogManager::SynonymInfo synonym;
                    core::ErrorContext synonym_ctx;
                    status = catalog->getSynonymByName(alias_schema.schema_id, alias, synonym, &synonym_ctx);
                    if (status == core::Status::INVALID_ARGUMENT ||
                        status == core::Status::NOT_FOUND)
                    {
                        continue;
                    }
                    if (status != core::Status::OK)
                    {
                        copyErrorContext(ctx, synonym_ctx);
                        return status;
                    }

                    status = catalog->dropSynonym(synonym.synonym_id, ctx);
                    if (status != core::Status::OK)
                    {
                        return status;
                    }
                    dropped_any = true;
                }

                if (!dropped_any)
                {
                    SET_ERROR_CONTEXT(ctx, core::Status::NOT_FOUND,
                                      "Emulated alias not found");
                    return core::Status::NOT_FOUND;
                }

                return core::Status::OK;
            }

            core::Status buildObjectPathFromName(const std::string& qualified_name,
                                                 core::ObjectPath& path,
                                                 core::ErrorContext* ctx)
            {
                path.components.clear();
                path.type = core::PathType::UNQUALIFIED;
                path.no_search_path = false;

                if (qualified_name.empty())
                {
                    SET_ERROR_CONTEXT(ctx, core::Status::INVALID_ARGUMENT,
                                      "Object name is empty");
                    return core::Status::INVALID_ARGUMENT;
                }

                std::string normalized = normalizeSchemaPath(qualified_name);
                if (normalized.empty())
                {
                    SET_ERROR_CONTEXT(ctx, core::Status::INVALID_ARGUMENT,
                                      "Object name is empty");
                    return core::Status::INVALID_ARGUMENT;
                }

                if (normalized.rfind("!:", 0) == 0)
                {
                    path.no_search_path = true;
                    normalized.erase(0, 2);
                    if (normalized.empty())
                    {
                        SET_ERROR_CONTEXT(ctx, core::Status::INVALID_ARGUMENT,
                                          "Object name is empty");
                        return core::Status::INVALID_ARGUMENT;
                    }
                }

                size_t start = 0;
                if (normalized.rfind("..", 0) == 0)
                {
                    path.type = core::PathType::PARENT;
                    start = 2;
                }
                else if (normalized.rfind(".", 0) == 0)
                {
                    path.type = core::PathType::CURRENT;
                    start = 1;
                }

                if (start >= normalized.size())
                {
                    SET_ERROR_CONTEXT(ctx, core::Status::INVALID_ARGUMENT,
                                      "Object name is empty");
                    return core::Status::INVALID_ARGUMENT;
                }

                while (start < normalized.size())
                {
                    size_t dot_pos = normalized.find('.', start);
                    if (dot_pos == start)
                    {
                        SET_ERROR_CONTEXT(ctx, core::Status::INVALID_ARGUMENT,
                                          "Invalid object path");
                        return core::Status::INVALID_ARGUMENT;
                    }

                    std::string component = dot_pos == std::string::npos
                        ? normalized.substr(start)
                        : normalized.substr(start, dot_pos - start);
                    if (component.empty())
                    {
                        SET_ERROR_CONTEXT(ctx, core::Status::INVALID_ARGUMENT,
                                          "Invalid object path");
                        return core::Status::INVALID_ARGUMENT;
                    }

                    path.components.push_back(component);
                    if (dot_pos == std::string::npos)
                    {
                        break;
                    }
                    start = dot_pos + 1;
                }

                if (path.components.empty())
                {
                    SET_ERROR_CONTEXT(ctx, core::Status::INVALID_ARGUMENT,
                                      "Object name is empty");
                    return core::Status::INVALID_ARGUMENT;
                }

                if (path.type == core::PathType::UNQUALIFIED && path.components.size() > 1)
                {
                    path.type = core::PathType::ABSOLUTE;
                }

                return core::Status::OK;
            }

            bool isTableScopedType(core::CatalogManager::ObjectType type)
            {
                switch (type)
                {
                    case core::CatalogManager::ObjectType::INDEX:
                    case core::CatalogManager::ObjectType::TRIGGER:
                    case core::CatalogManager::ObjectType::CONSTRAINT:
                    case core::CatalogManager::ObjectType::COLUMN:
                    case core::CatalogManager::ObjectType::POLICY:
                        return true;
                    default:
                        return false;
                }
            }

            uint64_t emulatedTablespaceHash64(const std::string& input)
            {
                uint64_t hash = 14695981039346656037ull; // FNV-1a 64-bit offset basis
                for (unsigned char ch : input)
                {
                    hash ^= static_cast<uint64_t>(ch);
                    hash *= 1099511628211ull; // FNV-1a 64-bit prime
                }
                return hash;
            }

            std::string emulatedTablespaceHashHex(uint64_t value)
            {
                std::ostringstream oss;
                oss << std::hex << std::nouppercase << value;
                return oss.str();
            }

            std::string sanitizeEmulatedTablespaceToken(const std::string& input,
                                                        size_t max_length)
            {
                std::string token;
                token.reserve(input.size());
                for (unsigned char ch : input)
                {
                    if (std::isalnum(ch) || ch == '_' || ch == '-')
                    {
                        token.push_back(static_cast<char>(std::tolower(ch)));
                    }
                    else
                    {
                        token.push_back('_');
                    }
                }

                while (!token.empty() && token.front() == '_')
                {
                    token.erase(token.begin());
                }
                while (!token.empty() && token.back() == '_')
                {
                    token.pop_back();
                }

                if (token.empty())
                {
                    token = "x";
                }
                if (token.size() > max_length)
                {
                    token.resize(max_length);
                }
                return token;
            }

            [[maybe_unused]] std::string emulatedTablespaceParentDir(const std::string& db_path)
            {
                if (db_path.empty())
                {
                    return ".";
                }

                size_t slash = db_path.find_last_of('/');
                if (slash == std::string::npos)
                {
                    return ".";
                }
                if (slash == 0)
                {
                    return "/";
                }
                return db_path.substr(0, slash);
            }

            std::string emulatedTablespaceDbStem(const std::string& db_path)
            {
                std::string file_name = db_path;
                size_t slash = file_name.find_last_of('/');
                if (slash != std::string::npos)
                {
                    file_name = (slash + 1 < file_name.size())
                        ? file_name.substr(slash + 1)
                        : std::string();
                }

                if (file_name.empty())
                {
                    file_name = "scratchbird";
                }

                size_t dot = file_name.find_last_of('.');
                if (dot != std::string::npos && dot > 0)
                {
                    file_name = file_name.substr(0, dot);
                }

                return sanitizeEmulatedTablespaceToken(file_name, 32);
            }

            constexpr const char* kEmulatedVirtualTablespacePrefix = "sb://emu-ts/";

            bool isEmulatedVirtualTablespaceToken(const std::string& location)
            {
                return location.size() >= std::strlen(kEmulatedVirtualTablespacePrefix) &&
                       location.compare(0,
                                        std::strlen(kEmulatedVirtualTablespacePrefix),
                                        kEmulatedVirtualTablespacePrefix) == 0;
            }

            bool tablespaceUsesVirtualMetadata(const core::TablespaceInfo& ts_info)
            {
                for (const auto& path : ts_info.file_paths)
                {
                    if (isEmulatedVirtualTablespaceToken(path))
                    {
                        return true;
                    }
                }
                return false;
            }

            std::string buildEmulatedVirtualTablespaceNamespacePath(const std::string& root_path)
            {
                std::string normalized = normalizeSchemaPath(root_path);
                if (normalized.empty())
                {
                    return "system.tablespaces";
                }
                return normalized + ".system.tablespaces";
            }

            std::string buildEmulatedVirtualTablespaceBindingNamespacePath(
                const std::string& root_path)
            {
                std::string normalized = normalizeSchemaPath(root_path);
                if (normalized.empty())
                {
                    return "system.tablespace_bindings";
                }
                return normalized + ".system.tablespace_bindings";
            }

            std::string emulatedVirtualTablespaceKey(const std::string& root_path,
                                                     const std::string& tablespace_name)
            {
                const std::string root_upper = scratchbird::core::IdentifierUtils::toUpper(
                    normalizeSchemaPath(root_path));
                const std::string name_upper = scratchbird::core::IdentifierUtils::toUpper(
                    trimAsciiCopy(tablespace_name));
                return root_upper + "|" + name_upper;
            }

            std::string emulatedVirtualTablespaceBindingKey(
                const std::string& root_path,
                const std::string& object_path)
            {
                const std::string root_upper = scratchbird::core::IdentifierUtils::toUpper(
                    normalizeSchemaPath(root_path));
                const std::string object_upper = scratchbird::core::IdentifierUtils::toUpper(
                    normalizeSchemaPath(object_path));
                return root_upper + "|" + object_upper;
            }

            bool tryResolveEmulatedRootCandidate(const std::string& raw_candidate,
                                                 const std::string& dialect_upper,
                                                 std::string& root_out)
            {
                root_out.clear();
                std::string candidate = normalizeSchemaPath(raw_candidate);
                if (candidate.empty())
                {
                    return false;
                }

                auto components = splitSchemaComponents(candidate);
                if (components.size() < 2)
                {
                    return false;
                }

                size_t start = 0;
                if (scratchbird::core::IdentifierUtils::namesMatch(
                        components[0], false, "root", false))
                {
                    start = 1;
                }
                if (start >= components.size())
                {
                    return false;
                }

                size_t cursor = std::string::npos;
                bool emulation_prefix = scratchbird::core::IdentifierUtils::namesMatch(
                                            components[start], false, "emulated", false) ||
                                        scratchbird::core::IdentifierUtils::namesMatch(
                                            components[start], false, "emulation", false);
                if (emulation_prefix)
                {
                    if (start + 1 < components.size() &&
                        scratchbird::core::IdentifierUtils::toUpper(
                            components[start + 1]) == dialect_upper)
                    {
                        cursor = start + 2;
                    }
                }
                else if (scratchbird::core::IdentifierUtils::namesMatch(
                             components[start], false, "remote", false))
                {
                    if (start + 2 < components.size() &&
                        (scratchbird::core::IdentifierUtils::namesMatch(
                             components[start + 1], false, "emulated", false) ||
                         scratchbird::core::IdentifierUtils::namesMatch(
                             components[start + 1], false, "emulation", false)) &&
                        scratchbird::core::IdentifierUtils::toUpper(
                            components[start + 2]) == dialect_upper)
                    {
                        cursor = start + 3;
                    }
                }

                if (cursor == std::string::npos || cursor >= components.size())
                {
                    return false;
                }

                size_t root_component_count = components.size();
                for (size_t i = cursor; i + 1 < components.size(); ++i)
                {
                    if (scratchbird::core::IdentifierUtils::namesMatch(
                            components[i], false, "databases", false))
                    {
                        root_component_count = i + 2;
                        break;
                    }
                }

                if (root_component_count == 0 || root_component_count > components.size())
                {
                    return false;
                }

                std::vector<std::string> root_components(
                    components.begin(),
                    components.begin() +
                        static_cast<std::vector<std::string>::difference_type>(
                            root_component_count));
                root_out = joinSchemaComponents(root_components, 0);
                return !root_out.empty();
            }

            bool resolveEmulatedRootPath(const core::ConnectionContext* conn_ctx,
                                         std::string& root_path_out)
            {
                root_path_out.clear();
                if (!conn_ctx)
                {
                    return false;
                }

                std::string dialect = scratchbird::core::IdentifierUtils::toUpper(
                    conn_ctx->dialect_tag());
                if (dialect.empty() || dialect == "SCRATCHBIRD")
                {
                    return false;
                }

                auto try_set_root = [&](const std::string& candidate) {
                    std::string resolved_root;
                    if (!tryResolveEmulatedRootCandidate(candidate, dialect, resolved_root))
                    {
                        return false;
                    }
                    root_path_out = resolved_root;
                    return true;
                };

                if (try_set_root(conn_ctx->current_schema()))
                {
                    return true;
                }

                for (const auto& entry : conn_ctx->search_path())
                {
                    if (try_set_root(entry))
                    {
                        return true;
                    }
                }

                return false;
            }

            std::string buildEmulatedTablespaceSandboxPath(const core::Database* db,
                                                           const std::string& root_path,
                                                           const std::string& tablespace_name)
            {
                const std::string db_path = db ? db->path() : std::string();
                const std::string db_stem = emulatedTablespaceDbStem(db_path);
                const std::string root_token =
                    sanitizeEmulatedTablespaceToken(root_path, 24);
                const std::string tablespace_token =
                    sanitizeEmulatedTablespaceToken(tablespace_name, 24);

                const std::string root_hash =
                    emulatedTablespaceHashHex(emulatedTablespaceHash64(root_path));
                const std::string name_hash = emulatedTablespaceHashHex(
                    emulatedTablespaceHash64(root_path + "|" + tablespace_name));

                // T0 virtualization: emit a metadata-only token, never a host path.
                return std::string(kEmulatedVirtualTablespacePrefix) +
                       db_stem + "/" + root_hash + "/" + name_hash + "/" +
                       root_token + "/" + tablespace_token;
            }

            bool tablespaceBelongsToEmulatedRoot(const core::TablespaceInfo& ts_info,
                                                 const std::string& root_path)
            {
                if (root_path.empty())
                {
                    return false;
                }

                const std::string root_hash =
                    emulatedTablespaceHashHex(emulatedTablespaceHash64(root_path));
                const std::string hash_marker = "." + root_hash + ".";
                for (const auto& path : ts_info.file_paths)
                {
                    if (isEmulatedVirtualTablespaceToken(path))
                    {
                        const std::string marker = "/" + root_hash + "/";
                        if (path.find(marker) != std::string::npos)
                        {
                            return true;
                        }
                        continue;
                    }
                    if (path.find(".emu_ts.") == std::string::npos)
                    {
                        continue;
                    }
                    if (path.find(hash_marker) != std::string::npos)
                    {
                        return true;
                    }
                }

                return false;
            }

            bool decryptValueForColumn(core::Database* db,
                                       const core::CatalogManager::ColumnInfo& column,
                                       core::TypedValue& value,
                                       core::ErrorContext* ctx)
            {
                if (!value.isEncrypted())
                {
                    return true;
                }
                if (column.domain_id == core::ID())
                {
                    SET_ERROR_CONTEXT(ctx, core::Status::INVALID_ARGUMENT,
                                      "Encrypted column missing domain reference");
                    return false;
                }
                if (db == nullptr || db->domain_manager() == nullptr)
                {
                    SET_ERROR_CONTEXT(ctx, core::Status::INTERNAL_ERROR,
                                      "Domain manager unavailable for decryption");
                    return false;
                }

                core::Status status = db->domain_manager()->decryptValue(column.domain_id,
                                                                         value, ctx);
                if (status != core::Status::OK)
                {
                    if (ctx && ctx->message.empty())
                    {
                        SET_ERROR_CONTEXT(ctx, status, "Failed to decrypt value");
                    }
                    return false;
                }
                return true;
            }

            core::Status findFunctionById(core::CatalogManager* catalog,
                                           const core::ID& function_id,
                                           core::CatalogManager::FunctionInfo& info_out,
                                           core::ErrorContext* ctx)
            {
                if (!catalog)
                {
                    SET_ERROR_CONTEXT(ctx, core::Status::INTERNAL_ERROR,
                                      "Catalog manager not available");
                    return core::Status::INTERNAL_ERROR;
                }

                std::vector<core::CatalogManager::FunctionInfo> functions;
                auto status = catalog->listFunctions(functions, ctx);
                if (status != core::Status::OK)
                {
                    return status;
                }

                for (const auto& func : functions)
                {
                    if (func.function_id == function_id)
                    {
                        info_out = func;
                        return core::Status::OK;
                    }
                }

                SET_ERROR_CONTEXT(ctx, core::Status::NOT_FOUND, "Function not found");
                return core::Status::NOT_FOUND;
            }

            core::Status findProcedureById(core::CatalogManager* catalog,
                                            const core::ID& procedure_id,
                                            core::CatalogManager::ProcedureInfo& info_out,
                                            core::ErrorContext* ctx)
            {
                if (!catalog)
                {
                    SET_ERROR_CONTEXT(ctx, core::Status::INTERNAL_ERROR,
                                      "Catalog manager not available");
                    return core::Status::INTERNAL_ERROR;
                }

                std::vector<core::CatalogManager::ProcedureInfo> procedures;
                auto status = catalog->listProcedures(procedures, ctx);
                if (status != core::Status::OK)
                {
                    return status;
                }

                for (const auto& proc : procedures)
                {
                    if (proc.procedure_id == procedure_id)
                    {
                        info_out = proc;
                        return core::Status::OK;
                    }
                }

                SET_ERROR_CONTEXT(ctx, core::Status::NOT_FOUND, "Procedure not found");
                return core::Status::NOT_FOUND;
            }

            std::string stripRootPrefixForDisplay(const std::string& schema_path)
            {
                if (schema_path.empty())
                {
                    return schema_path;
                }

                size_t dot_pos = schema_path.find('.');
                std::string first_component =
                    dot_pos == std::string::npos ? schema_path : schema_path.substr(0, dot_pos);
                if (core::IdentifierUtils::namesMatch(first_component, false /*search_delimited*/,
                                                      "root", false /*stored_delimited*/))
                {
                    if (dot_pos == std::string::npos)
                    {
                        return std::string();
                    }
                    return schema_path.substr(dot_pos + 1);
                }

                return schema_path;
            }
        } // namespace

        void Executor::executeCreateFunctionStatement()
        {
            uint8_t flags = readByte();
            bool or_replace = (flags & 0x01) != 0;
            bool deterministic = (flags & 0x02) != 0;
            bool has_dependencies = (flags & 0x08) != 0;  // Dependency list appended after body
            bool has_bytecode = (flags & 0x10) != 0;

            std::string function_name = readString();
            core::ErrorContext ctx;
            core::ID schema_id;
            std::string resolved_function_name;
            auto schema_status = resolveSchemaIdForQualifiedName(function_name, resolved_function_name,
                                                                 schema_id, &ctx, false);
            if (schema_status != core::Status::OK)
            {
                std::string err_msg = "Schema not found for function '" + function_name + "'";
                if (!ctx.message.empty())
                {
                    err_msg += ": " + ctx.message;
                }
                error(err_msg);
            }

            uint8_t param_count = readByte();
            std::vector<core::CatalogManager::ParameterInfo> params;
            params.reserve(param_count);
            for (uint8_t i = 0; i < param_count; ++i)
            {
                uint8_t mode_byte = readByte();
                std::string param_name = readString();
                uint8_t type_byte = readByte();
                uint32_t precision = readInt32();
                uint32_t scale = readInt32();

                core::CatalogManager::ParameterInfo param;
                param.name = param_name;
                param.type = decodeDataType(type_byte);
                param.type_precision = precision;
                param.type_scale = scale;
                param.mode = decodeParameterMode(mode_byte);
                params.push_back(param);
            }

            uint8_t return_type_byte = readByte();
            uint32_t return_precision = readInt32();
            uint32_t return_scale = readInt32();

            std::string body = readString();
            std::vector<uint8_t> bytecode;
            if (has_bytecode)
            {
                uint32_t bytecode_len = readInt32();
                bytecode.reserve(bytecode_len);
                for (uint32_t i = 0; i < bytecode_len; ++i)
                {
                    bytecode.push_back(readByte());
                }
            }

            core::CatalogManager::FunctionInfo info;
            info.function_id = core::generateUuidV7();
            info.schema_id = schema_id;
            info.name = resolved_function_name;
            core::ErrorContext owner_ctx;
            info.owner_id = conn_ctx_ ? conn_ctx_->getCurrentUserId()
                                      : db_->catalog_manager()->getSystemUserId(&owner_ctx);
            info.parameters = params;
            info.return_type = decodeDataType(return_type_byte);
            info.return_type_precision = return_precision;
            info.return_type_scale = return_scale;
            info.or_replace = or_replace;
            info.deterministic = deterministic;
            info.sql_security = decodeSqlSecurity(flags);
            info.source_text = body;
            if (!bytecode.empty())
            {
                info.bytecode = std::move(bytecode);
            }
            info.created_time = info.modified_time =
                static_cast<uint64_t>(std::chrono::system_clock::now().time_since_epoch().count());
            if (has_dependencies)
            {
                readDependencies(info.referenced_objects);
            }

            auto status = db_->catalog_manager()->registerFunction(info, &ctx);
            if (status != core::Status::OK)
            {
                const bool postgresql_dialect = isPostgreSqlDialectContext(conn_ctx_);
                const std::string ctx_upper =
                    scratchbird::core::IdentifierUtils::toUpper(ctx.message);
                const bool already_exists = ctx_upper.find("ALREADY EXISTS") != std::string::npos;
                const std::string function_upper =
                    scratchbird::core::IdentifierUtils::toUpper(resolved_function_name);
                const bool is_fipshash =
                    function_upper == "FIPSHASH" ||
                    (function_upper.size() > 9 &&
                     function_upper.rfind(".FIPSHASH") == function_upper.size() - 9);
                if (already_exists &&
                    (postgresql_dialect || is_fipshash))
                {
                    const std::string key = toUpperAsciiCopy(resolved_function_name);
                    uint32_t& count = postgresql_compat_function_overloads_[key];
                    count = (count == 0) ? 2u : (count + 1u);
                    return;
                }
                std::string msg = "Failed to create function '" + function_name + "'";
                if (!ctx.message.empty()) { msg += ": " + ctx.message; }
                error(msg);
            }

            if (isPostgreSqlDialectContext(conn_ctx_))
            {
                const std::string key = toUpperAsciiCopy(resolved_function_name);
                auto it = postgresql_compat_function_overloads_.find(key);
                if (it == postgresql_compat_function_overloads_.end())
                {
                    postgresql_compat_function_overloads_.emplace(key, 1u);
                }
            }

            recordObjectDefinition(core::CatalogManager::ObjectType::FUNCTION, info.function_id);

            core::ErrorContext priv_ctx;
            db_->catalog_manager()->applyDefaultPrivileges(
                schema_id,
                core::CatalogManager::PermissionObjectType::FUNCTION,
                info.function_id,
                getCurrentUserID(),
                &priv_ctx);
        }

